// Mock Test 1 — Full Syllabus (526 questions: English, Quant, Reasoning, Professional Knowledge)
// This file defines ONE mock. To add another mock, copy this file's pattern into a new file
// (see mock2-data.js for a template), then register it in mocks-index.js.
const MOCK1_SECTIONS = [{ "id": "english", "title": "English Language", "questions": [{ "topic": "RC", "question": "Read the following passage carefully and answer the questions that follow:Digital banking has transformed the way financial institutions interact with their customers. What once required a visit to a physical branch can now be accomplished within seconds through a mobile application. This shift has been particularly significant in developing economies, where mobile penetration often exceeds traditional banking infrastructure. However, this convenience comes with heightened responsibility: banks must now investheavily in cybersecurity to protect customer data and prevent fraud. Regulators, too, have had to adapt quickly,framing new guidelines to keep pace with technological change while ensuring that financial inclusion does not come at the cost of security. Analysts argue that the institutions which will thrive in the coming decade are those that strike the right balance between innovation and prudence,   According to the passage, what has been a major driver of change in the banking sector?", "options": ["Government subsidies", "Digital/mobile banking technology", "Reduction in bank branches by law", "International trade agreements", "Rising interest rates"], "correct": "B", "explanation": "The passage opens by stating that digital banking has transformed customer interaction, directly identifying it as the key driver of change described throughout the passage." }, { "topic": "RC", "question": "As per the passage, why is mobile banking particularly significant in developing economies?", "options": ["Because interest rates are lower there", "Because mobile penetration often exceeds traditional banking infrastructure", "Because banks are legally required to go digital there", "Because paper currency has been banned", "Because it is cheaper to print currency"], "correct": "B", "explanation": "The passage explicitly states that the shift 'has been particularly significant in developing economies, where mobile penetration often exceeds traditional banking infrastructure.'" }, { "topic": "RC", "question": "What responsibility does the passage say has increased for banks alongside the convenience of digital banking?", "options": ["Hiring more branch staff", "Investing in cybersecurity to protect customer data and prevent fraud", "Reducing loan interest rates", "Printing more physical currency", "Opening more rural branches"], "correct": "B", "explanation": "The passage states that 'this convenience comes with heightened responsibility: banks must now invest heavily in cybersecurity to protect customer data and prevent fraud.'" }, { "topic": "RC", "question": "What does the passage suggest regulators have had to do in response to technological change?", "options": ["Ban digital banking until further notice", "Frame new guidelines to keep pace with change while ensuring security", "Transfer regulatory power to private banks", "Eliminate financial inclusion programs", "Increase transaction fees"], "correct": "B", "explanation": "The passage states that 'Regulators, too, have had to adapt quickly, framing new guidelines to keep pace with technological change while ensuring that financial inclusion does not come at the cost of security.'" }, { "topic": "RC", "question": "Which institutions does the passage suggest will succeed in the coming decade?", "options": ["Only government-owned banks", "Those that balance innovation with prudence", "Those with the most physical branches", "Those that avoid digital technology entirely", "Only foreign banks"], "correct": "B", "explanation": "The passage concludes that 'the institutions which will thrive in the coming decade are those that strike the right balance between innovation and prudence.'" }, { "topic": "Cloze", "question": "Blank (1):", "options": ["decline", "advancement", "stagnation", "elimination", "postponement"], "correct": "B", "explanation": "'Advancement' fits the context of AI rapidly progressing/developing, matching the overall positive-momentum tone of the sentence." }, { "topic": "Cloze", "question": "Blank (2):", "options": ["forced", "prevented", "discouraged", "ignored", "delayed"], "correct": "A", "explanation": "'Forced' fits best — the rapid advancement of AI has compelled (forced) organizations to rethink their strategies." }, { "topic": "Cloze", "question": "Blank (3):", "options": ["reject", "adopt", "postpone", "criticize", "forget"], "correct": "B", "explanation": "'Adopt' fits logically — companies that fail to adopt (start using) the technology risk falling behind, which matches the sentence's warning tone." }, { "topic": "Cloze", "question": "Blank (4):", "options": ["deny", "caution", "forget", "celebrate", "ignore"], "correct": "B", "explanation": "'Caution' fits the context — experts are warning/cautioning that the transition must be handled carefully, consistent with the sentence's concern about risks." }, { "topic": "Cloze", "question": "Blank (5):", "options": ["solve", "create", "prevent", "reduce", "avoid"], "correct": "B", "explanation": "'Create' fits best — poorly implemented systems can create (cause) more problems than they solve, forming a natural contrast with 'solve' later in the sentence." }, { "topic": "Error Spotting", "question": "The bank have (A) / decided to launch (B) / a new mobile application (C) / for its customers next month (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "A", "explanation": "Part (A) contains a subject-verb agreement error — 'bank' is singular and should take 'has', not 'have'. Correct: 'The bank has decided...'" }, { "topic": "Error Spotting", "question": "Neither the manager nor his assistants (A) / was aware of (B) / the changes that had been made (C) / to the company's policy (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "B", "explanation": "With 'neither...nor', the verb should agree with the subject CLOSER to it — here 'assistants' (plural) is closer, so it should be 'were aware of', not 'was aware of'. The error is in part (B)." }, { "topic": "Error Spotting", "question": "She is one of the most talented employee (A) / in the entire organization (B) / and has been recognized (C) / for her outstanding contributions (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "A", "explanation": "The phrase 'one of the most talented' must be followed by a PLURAL noun — it should be 'employees', not 'employee'. The error is in part (A)." }, { "topic": "Error Spotting", "question": "Each of the candidates were asked (A) / to submit their documents (B) / before the deadline (C) / for verification purposes (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "A", "explanation": "'Each' is always treated as singular, so the verb should be 'was asked', not 'were asked'. The error is in part (A)." }, { "topic": "Error Spotting", "question": "Despite of his best efforts (A) / he could not complete (B) / the project within (C) / the given time frame (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "A", "explanation": "'Despite' should NOT be followed by 'of' — it should simply be 'Despite his best efforts'. ('In spite of' would be correct with 'of', but 'despite of' is incorrect.) The error is in part (A)." }, { "topic": "Sentence Improvement", "question": "The committee <u>have submitted their</u> report to the board of directors yesterday.", "options": ["have submitted their", "has submitted its", "had submitted their", "having submitted its", "No improvement needed"], "correct": "B", "explanation": "'Committee' is a collective noun treated as singular here, so it should be 'has submitted its' — matching singular subject-verb-pronoun agreement." }, { "topic": "Sentence Improvement", "question": "If I <u>would have known</u> about the meeting, I would have attended it.", "options": ["would have known", "had known", "have known", "would know", "No improvement needed"], "correct": "B", "explanation": "This is a third conditional sentence (about a hypothetical past situation), which requires 'had known' in the if-clause, not 'would have known'." }, { "topic": "Sentence Improvement", "question": "Neither the manager <u>or</u> his team was available for the client call.", "options": ["or", "nor", "and", "but", "No improvement needed"], "correct": "B", "explanation": "'Neither' must be paired with 'nor', not 'or'. The correct pairing is 'neither...nor'." }, { "topic": "Sentence Improvement", "question": "She has been working in this company <u>since five years</u>.", "options": ["since five years", "for five years", "from five years", "during five years", "No improvement needed"], "correct": "B", "explanation": "'Since' is used with a specific POINT in time (e.g., since 2019), while 'for' is used with a DURATION (e.g., for five years). The correct phrase is 'for five years'." }, { "topic": "Sentence Improvement", "question": "The report was so complicated that <u>nobody could not understand</u> it.", "options": ["nobody could not understand", "nobody could understand", "nobody couldn't understand", "anybody could not understand", "No improvement needed"], "correct": "B", "explanation": "The original sentence contains a double negative ('nobody' + 'could not'), which is grammatically incorrect. The correct form is simply 'nobody could understand'." }, { "topic": "Para Jumble", "question": "Rearrange the following sentences (P, Q, R, S) into a logical order:<br/>P: As a result, many banks began offering round-the-clock services through ATMs and online portals.<br/>Q: In the early 2000s, banking was largely confined to fixed working hours.<br/>R: This shift dramatically improved customer convenience and satisfaction.<br/>S: Customers had to visit branches during the day to complete even simple transactions.", "options": ["QSPR", "QSRP", "SQPR", "PQSR", "QPSR"], "correct": "A", "explanation": "Logical flow: Q (sets the historical context of limited hours) then S (explains the resulting inconvenience) then P (introduces the change/solution, 24x7 services) then R (states the positive result of that change). So the correct order is QSPR." }, { "topic": "Vocabulary", "question": "Choose the word most SIMILAR in meaning to 'MERIDIAN' as used in: 'She was at the meridian of her career.'", "options": ["Beginning", "Peak", "Decline", "Middle stage only", "Ending"], "correct": "B", "explanation": "'Meridian' in this figurative context means the highest point or peak (as in the sun's meridian, its highest point in the sky), so the closest synonym is 'Peak'." }, { "topic": "Vocabulary", "question": "Choose the word most OPPOSITE in meaning to 'PRUDENT'.", "options": ["Cautious", "Wise", "Reckless", "Sensible", "Careful"], "correct": "C", "explanation": "'Prudent' means acting with careful judgment and caution. Its opposite is 'Reckless', meaning acting without thinking of consequences." }, { "topic": "Vocabulary", "question": "Choose the word most SIMILAR in meaning to 'AMBIGUOUS'.", "options": ["Clear", "Unclear/Vague", "Certain", "Precise", "Obvious"], "correct": "B", "explanation": "'Ambiguous' means open to more than one interpretation, i.e., unclear or vague — the closest synonym among the options." }, { "topic": "Vocabulary", "question": "Choose the one-word substitute for: 'A person who can speak more than one language.'", "options": ["Linguist", "Polyglot", "Interpreter", "Translator", "Bilingual only"], "correct": "B", "explanation": "'Polyglot' specifically means a person who knows and can speak several languages, which is the precise one-word substitute for the given definition." }, { "topic": "Vocabulary", "question": "Choose the one-word substitute for: 'A statement that is difficult to understand because it appears to contradict itself.'", "options": ["Anomaly", "Paradox", "Irony", "Metaphor", "Analogy"], "correct": "B", "explanation": "A 'Paradox' is a statement that seems self-contradictory or absurd but may express a deeper truth — matching the given definition exactly." }, { "topic": "RC", "question": "Read the following passage carefully and answer the questions that follow:Monetary policy operates through a complex transmission mechanism that connects a central bank's actions tothe broader economy, yet the lags involved make it notoriously difficult to calibrate. When a central bank raisesits policy rate, the effects ripple through bank lending rates, asset prices, and eventually consumer spending,but each of these channels operates with a different time lag, some measured in months and others in years.This asynchrony creates a persistent risk: policymakers may either tighten too aggressively, having not yetobserved the delayed effects of prior hikes, or ease prematurely under pressure from short-term politicalconsiderations. Compounding this challenge is the increasing interconnectedness of global financial markets,where a rate decision in one major economy can trigger capital flows that undermine the intended effects ofpolicy elsewhere. Central bankers, therefore, must navigate not only domestic economic indicators but also thesecond-order consequences of their counterparts' decisions abroad. According to the passage, why is calibrating monetary policy particularly difficult?", "options": ["Central banks lack sufficient data on inflation", "The effects of policy actions operate through channels with varying and uncertain time lags", "Governments do not allow central banks to act independently", "Consumer spending never responds to interest rate changes", "Bank lending rates are fixed by law"], "correct": "B", "explanation": "The passage states that 'each of these channels operates with a different time lag, some measured in months and others in years,' directly identifying varying time lags as the core difficulty." }, { "topic": "RC", "question": "What risk does the passage identify as arising from the 'asynchrony' of policy transmission channels?", "options": ["Policymakers may tighten too aggressively or ease too soon, based on incomplete information about delayed effects", "Banks will refuse to lend altogether", "Asset prices will remain constant regardless of policy", "Global markets will become completely disconnected", "Political considerations will disappear entirely"], "correct": "A", "explanation": "The passage explicitly states this risk: 'policymakers may either tighten too aggressively, having not yet observed the delayed effects of prior hikes, or ease prematurely under pressure from short-term political considerations.'" }, { "topic": "RC", "question": "What does the passage suggest about the interconnectedness of global financial markets?", "options": ["It has eliminated the need for domestic monetary policy", "A rate decision in one economy can cause capital flows that interfere with policy effectiveness elsewhere", "It has no bearing on how central banks make decisions", "It only affects developing economies", "It has made monetary policy transmission instantaneous"], "correct": "B", "explanation": "The passage states that 'a rate decision in one major economy can trigger capital flows that undermine the intended effects of policy elsewhere,' matching this option directly." }, { "topic": "RC", "question": "The phrase 'second-order consequences' in the passage most likely refers to:", "options": ["The primary, direct effects of a central bank's own policy decisions", "Indirect effects stemming from other countries' policy decisions", "Consequences that occur immediately after a rate hike", "Effects that are entirely predictable and easy to calibrate", "The publication delay of economic data"], "correct": "B", "explanation": "The passage says central bankers must navigate 'the second-order consequences of their counterparts' decisions abroad' — i.e., indirect effects caused by OTHER countries' policy actions, not their own direct/primary effects." }, { "topic": "RC", "question": "Which of the following best captures the overall purpose of the passage?", "options": ["To argue that central banks should abandon interest rate policy altogether", "To explain the structural challenges that make monetary policy calibration inherently uncertain", "To criticize specific central bank governors by name", "To provide a historical account of a particular financial crisis", "To recommend a specific interest rate level for the coming year"], "correct": "B", "explanation": "The passage is explanatory throughout, describing WHY monetary policy calibration is difficult (transmission lags, asynchrony, global interconnectedness) rather than arguing for a specific action, criticizing individuals, or recounting history." }, { "topic": "Cloze", "question": "Blank (1):", "options": ["reinforced", "challenged", "ignored", "confirmed", "replicated"], "correct": "B", "explanation": "'Challenged' fits the context — behavioral economics questions/challenges the assumption of perfect rationality in traditional models, which is the entire premise of the field." }, { "topic": "Cloze", "question": "Blank (2):", "options": ["unaffected", "distorted", "clarified", "simplified", "standardized"], "correct": "B", "explanation": "'Distorted' fits best — real-world decisions are shown to be distorted (skewed away from pure rationality) by biases, social pressure, and emotion." }, { "topic": "Cloze", "question": "Blank (3):", "options": ["emphasize", "overstate", "disregard", "calculate", "publicize"], "correct": "C", "explanation": "'Disregard' fits logically — classical theory, by assuming perfect rationality, tends to disregard (overlook) the influence of biases and emotions that behavioral economics highlights." }, { "topic": "Cloze", "question": "Blank (4):", "options": ["translating", "delaying", "rejecting", "celebrating", "disproving"], "correct": "A", "explanation": "'Translating' fits — critics caution against directly translating (converting) behavioral insights into real-world policy without proper validation first." }, { "topic": "Cloze", "question": "Blank (5):", "options": ["worsen", "guarantee", "eliminate", "replicate", "validate"], "correct": "A", "explanation": "'Worsen' fits the contrast set up by 'rather than improve' — the sentence warns that interventions could worsen outcomes instead of improving them." }, { "topic": "Error Spotting", "question": "The board of directors, along with the CEO, (A) / were scheduled to present (B) / their strategic roadmap (C) / to the shareholders next quarter (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "B", "explanation": "'Along with the CEO' is a parenthetical phrase and does NOT make the subject plural. The subject is 'The board of directors' (treated as singular here), so the verb should be 'was scheduled', not 'were scheduled'. The error is in part (B)." }, { "topic": "Error Spotting", "question": "Had she known about the risks involved, (A) / she would of invested (B) / a smaller sum of money (C) / in that speculative venture (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "B", "explanation": "'Would of' is a common written error — the correct form is 'would have invested', using the auxiliary verb 'have', not the preposition 'of'. The error is in part (B)." }, { "topic": "Error Spotting", "question": "Each of the members of the committee, including the chairperson and secretary, (A) / are required to submit (B) / a written declaration of interest (C) / before the annual general meeting (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "B", "explanation": "'Each' is always treated as singular, regardless of the plural phrase that follows it ('including the chairperson and secretary' is parenthetical). The verb should be 'is required', not 'are required'. The error is in part (B)." }, { "topic": "Error Spotting", "question": "Not only did the company miss its quarterly targets, (A) / but its market share also declined (B) / to a level lower than it had been (C) / in over a decade (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "E", "explanation": "This sentence is grammatically correct: the 'Not only...but also' construction is properly inverted ('did the company miss'), and the comparison 'lower than it had been' is correctly formed. There is no error." }, { "topic": "Error Spotting", "question": "The reason the merger failed was because (A) / both companies had fundamentally different (B) / organizational cultures that proved (C) / impossible to reconcile (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "A", "explanation": "'The reason...was because' is a common redundancy error — since 'reason' already implies causation, it should be followed by 'that', not 'because'. The correct form is 'The reason the merger failed was THAT...'. The error is in part (A)." }, { "topic": "Sentence Improvement", "question": "The manager insisted that the report <u>should be submitted</u> by Friday without fail.", "options": ["should be submitted", "be submitted", "is submitted", "was submitted", "No improvement needed"], "correct": "B", "explanation": "After verbs expressing demand or insistence (insist, demand, recommend, suggest), formal grammar requires the SUBJUNCTIVE mood — the base form of the verb without 'should'. The most precise correct form is 'insisted that the report be submitted', not 'should be submitted'." }, { "topic": "Sentence Improvement", "question": "Scarcely had the meeting begun <u>than</u> the fire alarm went off.", "options": ["than", "when", "then", "that", "No improvement needed"], "correct": "B", "explanation": "'Scarcely/Hardly' is correctly paired with 'when', not 'than'. The correct correlative construction is 'Scarcely had...when...' (similarly, 'No sooner...than' is the pairing that uses 'than')." }, { "topic": "Sentence Improvement", "question": "The committee members could not agree <u>on should the policy be revised</u> immediately or not.", "options": ["on should the policy be revised", "on whether the policy should be revised", "that should the policy revised", "upon the policy should be revised", "No improvement needed"], "correct": "B", "explanation": "An indirect/embedded question must follow normal (non-inverted) word order, introduced by 'whether' or 'if' — the correct form is 'on whether the policy should be revised', not the inverted question form 'should the policy be revised'." }, { "topic": "Sentence Improvement", "question": "<u>Being a public holiday, the office</u> remained closed and none of the employees came to work.", "options": ["Being a public holiday, the office", "Since it was a public holiday, the office", "The office being a public holiday", "As the office was a public holiday", "No improvement needed"], "correct": "B", "explanation": "The original has a dangling modifier — 'Being a public holiday' illogically modifies 'the office' (an office cannot BE a holiday). The correct fix restructures the clause with its own subject: 'Since it was a public holiday, the office remained closed...'." }, { "topic": "Double Blanks", "question": "The new policy was designed to _____ bureaucratic delays, but in practice it only served to _____ them.", "options": ["reduce, worsen", "increase, reduce", "eliminate, eliminate", "worsen, reduce", "ignore, resolve"], "correct": "A", "explanation": "The sentence sets up a contrast between INTENTION and OUTCOME ('designed to...but in practice'). The intent was positive (reduce delays), while the actual result was negative (worsen them) — matching 'reduce, worsen'." }, { "topic": "Double Blanks", "question": "Despite the company's public claims of transparency, insiders say that key financial decisions are still made in a remarkably _____ manner, with even senior managers kept largely _____ of the board's true intentions.", "options": ["open, informed", "opaque, unaware", "transparent, aware", "public, knowledgeable", "clear, certain"], "correct": "B", "explanation": "The word 'Despite' signals a contrast with the claimed 'transparency' — so decisions must actually be made in an 'opaque' (non-transparent) manner, with managers kept 'unaware' (not informed), matching the intended contrast." }, { "topic": "Double Blanks", "question": "The professor's lecture was so _____ that even students who normally struggled with the subject found themselves _____ by the clarity of his explanations.", "options": ["confusing, frustrated", "lucid, captivated", "monotonous, bored", "brief, disappointed", "technical, overwhelmed"], "correct": "B", "explanation": "The phrase 'clarity of his explanations' at the end confirms the lecture was clear and engaging, matching 'lucid' (clear) for the first blank and 'captivated' (engaged/fascinated) for the second." }, { "topic": "Para Jumble", "question": "Choose the correct sequence:", "options": ["QRTPS", "QRPTS", "RQTPS", "QTRPS", "QRTSP"], "correct": "A", "explanation": "Logical flow: Q (the crisis originates with institutional collapse) &rarr; R (immediate panic and credit freeze) &rarr; T (summarizes the escalation from a localized problem into a systemic crisis) &rarr; P (this escalation forces regulatory response) &rarr; S (in later years, the scope of that regulatory response expands further). The correct order is QRTPS." }, { "topic": "Vocabulary", "question": "Choose the meaning closest to the idiom: 'to read between the lines'", "options": ["To read very carefully, word by word", "To understand the hidden or implied meaning not directly stated", "To skip unimportant parts while reading", "To translate a text literally", "To proofread a document for errors"], "correct": "B", "explanation": "'To read between the lines' means to grasp an implied or hidden meaning that is not explicitly stated in the text — the closest match is option B." }, { "topic": "Vocabulary", "question": "Choose the meaning closest to the idiom: 'a blessing in disguise'", "options": ["An obvious advantage from the very start", "Something that seems bad or unfortunate at first but turns out to be beneficial", "A disguised threat or danger", "A gift given anonymously or in secret", "A misfortune with no redeeming outcome at all"], "correct": "B", "explanation": "'A blessing in disguise' describes something that initially appears negative or unfortunate but ultimately results in a positive outcome — matching option B exactly." }, { "topic": "RC", "question": "Why is clicking 'accept' on terms-of-service agreements considered problematic as a form of consent, according to the passage?", "options": ["Because it is illegal in most countries", "Because users rarely read these lengthy agreements in full, yet the click is still treated as informed consent", "Because terms-of-service agreements are always written in a foreign language", "Because companies never enforce these agreements", "Because such agreements are optional in every jurisdiction"], "correct": "B", "explanation": "The passage states these agreements are 'rarely read in their entirety, yet clicking accept is treated as informed consent under most existing legal regimes.'" }, { "topic": "RC", "question": "What tension does the passage identify regarding simplified privacy disclosures?", "options": ["They are universally praised as a perfect solution", "They are illegal in most jurisdictions", "Simplification may improve readability but can sacrifice precision, potentially obscuring important practices", "They eliminate the need for terms-of-service agreements entirely", "They have no effect on consumer understanding"], "correct": "C", "explanation": "The passage states critics contend that 'simplification often comes at the cost of precision, potentially obscuring the very practices it aims to clarify.'" }, { "topic": "RC", "question": "What phenomenon does the passage describe regarding the aggregation of 'seemingly innocuous' data points?", "options": ["Individual data points become MORE sensitive when isolated from others", "Combining multiple non-sensitive data points algorithmically can create surprisingly detailed personal profiles", "Aggregated data automatically becomes anonymous", "Regulators have fully solved this problem through existing law", "Location data cannot be combined with app usage data"], "correct": "B", "explanation": "The passage states that aggregating innocuous data points 'can yield surprisingly detailed profiles when combined algorithmically.'" }, { "topic": "RC", "question": "Why have regulators reportedly struggled to address the data aggregation phenomenon described in the passage?", "options": ["Because no laws exist anywhere addressing data privacy", "Because no single data point, viewed in isolation, appears sensitive enough to regulate", "Because aggregation is technically impossible", "Because companies refuse to collect any data", "Because users always opt out of data collection"], "correct": "B", "explanation": "The passage explains this is 'a phenomenon regulators have struggled to address because no single data point, in isolation, appears sensitive.'" }, { "topic": "RC", "question": "What does the passage identify as 'one of the central challenges of digital governance today'?", "options": ["The lack of internet access in rural areas", "The mismatch between how privacy harms accumulate and how privacy law is structured to address them", "The high cost of connected devices", "The absence of any terms-of-service agreements", "The complete failure of encryption technology"], "correct": "B", "explanation": "The passage's final sentence directly states this mismatch 'remains one of the central challenges of digital governance today.'" }, { "topic": "Cloze", "question": "Blank (1):", "options": ["hindered", "accelerated", "reversed", "halted", "obscured"], "correct": "B", "explanation": "'Accelerated' fits — falling technology costs speed up (accelerate) the transition to renewable energy." }, { "topic": "Cloze", "question": "Blank (2):", "options": ["predictable", "intermittent", "constant", "uniform", "stable"], "correct": "B", "explanation": "'Intermittent' fits — solar and wind generation fluctuate with weather, making them intermittent rather than constant sources." }, { "topic": "Cloze", "question": "Blank (3):", "options": ["dismantled", "throttled", "ignored", "sold", "relocated"], "correct": "B", "explanation": "'Throttled' fits — conventional plants can be ramped up or down (throttled) to match demand, unlike weather-dependent renewables." }, { "topic": "Cloze", "question": "Blank (4):", "options": ["abandon", "refine", "delete", "publicize", "simplify"], "correct": "B", "explanation": "'Refine' fits — utilities must continuously improve (refine) their forecasting models to handle renewable variability." }, { "topic": "Cloze", "question": "Blank (5):", "options": ["guarantee", "undermine", "celebrate", "replicate", "ignore"], "correct": "B", "explanation": "'Undermine' fits — the sentence warns that variability could undercut (undermine) the reliability gains renewables are meant to provide." }, { "topic": "Error Spotting", "question": "Not until the results were officially announced (A) / did the candidates realize (B) / how close the election (C) / had actually been (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "E", "explanation": "This sentence is correct: 'Not until...' at the start of a sentence correctly triggers subject-auxiliary inversion ('did the candidates realize'). There is no error." }, { "topic": "Error Spotting", "question": "The number of applicants who have qualified for the next round (A) / have increased significantly (B) / compared to last year's figures (C) / according to the latest report (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "B", "explanation": "The subject of the main clause is 'The number' (singular), even though 'of applicants' follows it. The verb should be 'has increased', not 'have increased'. The error is in part (B)." }, { "topic": "Error Spotting", "question": "Scientists have discovered that the ancient civilization (A) / had developed a sophisticated irrigation system (B) / far more advanced than what historians (C) / had previously gave them credit for (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "D", "explanation": "After the auxiliary 'had', the past PARTICIPLE form is required, not the simple past. It should be 'had previously given', not 'had previously gave'. The error is in part (D)." }, { "topic": "Error Spotting", "question": "If the committee would have approved the budget earlier, (A) / the project could have been completed (B) / well before the original deadline (C) / set by the stakeholders (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "A", "explanation": "In a third conditional (hypothetical past), the 'if' clause should use the past perfect ('had approved'), not 'would have approved'. The correct form is 'If the committee had approved...'. The error is in part (A)." }, { "topic": "Error Spotting", "question": "Between you and I, (A) / the proposal presented yesterday (B) / seems far less viable (C) / than the one we discussed last week (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "A", "explanation": "As the object of the preposition 'between', the objective case pronoun 'me' is required, not the subjective 'I'. The correct form is 'Between you and me'. The error is in part (A)." }, { "topic": "Sentence Improvement", "question": "The report, together with all supporting documents, <u>were submitted</u> before the deadline.", "options": ["were submitted", "was submitted", "have been submitted", "are submitted", "No improvement needed"], "correct": "B", "explanation": "'Together with...' is a parenthetical phrase and doesn't make the subject plural. The subject is 'The report' (singular), so the verb should be 'was submitted'." }, { "topic": "Sentence Improvement", "question": "He is one of those managers who <u>always insist</u> on punctuality.", "options": ["always insist", "always insists", "is always insisting", "has always insisted", "No improvement needed"], "correct": "E", "explanation": "This is correct: in the construction 'one of those X who...', the relative clause verb agrees with the plural antecedent 'managers', so 'who always insist' is grammatically correct." }, { "topic": "Sentence Improvement", "question": "The new regulations require that every employee <u>completes</u> the mandatory training within 30 days of joining.", "options": ["completes", "complete", "will complete", "completed", "No improvement needed"], "correct": "B", "explanation": "After verbs of demand/requirement ('require that'), formal grammar calls for the subjunctive mood, using the base form of the verb ('complete'), not the third-person singular 'completes'." }, { "topic": "Sentence Improvement", "question": "The data suggests that consumer confidence, as well as spending, <u>have declined</u> this quarter.", "options": ["have declined", "has declined", "had declining", "are declining", "No improvement needed"], "correct": "B", "explanation": "'As well as spending' is a parenthetical phrase that does NOT make the subject plural. The subject is 'consumer confidence' (singular), so the verb should be 'has declined'." }, { "topic": "Double Blanks", "question": "Although the merger was initially expected to _____ costs, internal audits revealed that overlapping departments had actually _____ operational expenses.", "options": ["reduce, inflated", "increase, reduced", "eliminate, minimized", "lower, decreased", "ignore, doubled"], "correct": "A", "explanation": "The sentence contrasts EXPECTATION with ACTUAL OUTCOME ('expected to...but actually'). The expectation was positive (reduce costs), while the real result was negative (inflated expenses), matching 'reduce, inflated'." }, { "topic": "Double Blanks", "question": "Critics praised the novel for its _____ prose, even as they questioned whether its _____ plot could sustain reader interest until the final chapter.", "options": ["clumsy, gripping", "elegant, meandering", "dull, focused", "verbose, concise", "plain, thrilling"], "correct": "B", "explanation": "The sentence needs a positive word for the praised prose ('elegant') and a critical word for the questioned plot ('meandering', i.e., wandering/unfocused), matching the contrast set up by 'even as'." }, { "topic": "Para Jumble", "question": "Choose the correct sequence:", "options": ["QPRTS", "QRPTS", "PQRTS", "QPTRS", "QRTPS"], "correct": "A", "explanation": "Logical flow: Q (treaty drafted broadly) then P ('yet this same flexibility' refers back to Q's flexible language, introducing the enforcement problem) then R (specific manifestation: states interpreting provisions differently) then T ('as a result' ties directly to R, showing varied compliance) then S (final consequence: calls for a successor agreement). The correct order is QPRTS." }, { "topic": "Para Jumble", "question": "Choose the correct sequence:", "options": ["QRPS", "QPRS", "RQPS", "QRSP", "PQRS"], "correct": "A", "explanation": "Logical flow: Q (governments began issuing exclusive licenses) then R (explains WHY, driven by tax/export promises) then P ('as a result' of this shift, small fishers were excluded) then S (this exclusion sparked protests, forcing policy revisits). The correct order is QRPS." }, { "topic": "Vocabulary", "question": "Choose the word most SIMILAR in meaning to 'PARSIMONIOUS'.", "options": ["Generous", "Extremely frugal or stingy with money", "Wasteful", "Indifferent", "Reckless"], "correct": "B", "explanation": "'Parsimonious' describes someone extremely unwilling to spend money or resources, i.e., excessively frugal or stingy." }, { "topic": "Vocabulary", "question": "Choose the word most OPPOSITE in meaning to 'CANDID'.", "options": ["Honest", "Evasive or secretive", "Frank", "Direct", "Transparent"], "correct": "B", "explanation": "'Candid' means being open, honest, and straightforward. Its opposite is 'Evasive' (avoiding giving direct or honest answers) or 'Secretive'." }] }, { "id": "quant", "title": "Quantitative Aptitude", "questions": [{ "topic": "Simplification", "question": "(15% of 240) + (25% of 180) = ?", "options": ["71", "76", "81", "86", "91"], "correct": "C", "explanation": "15% of 240 = 0.15 &times; 240 = 36. 25% of 180 = 0.25 &times; 180 = 45. Sum = 36 + 45 = 81." }, { "topic": "Simplification", "question": "12.5% of 480 &divide; 5 + 15 = ?", "options": ["22", "24", "27", "30", "33"], "correct": "C", "explanation": "12.5% of 480 = 0.125 &times; 480 = 60. 60 &divide; 5 = 12. 12 + 15 = 27." }, { "topic": "Number Series", "question": "Find the next number in the series: 5, 11, 23, 47, 95, ?", "options": ["189", "190", "191", "192", "193"], "correct": "C", "explanation": "Each term follows the pattern: (previous term &times; 2) + 1. 5&times;2+1=11, 11&times;2+1=23, 23&times;2+1=47, 47&times;2+1=95, 95&times;2+1=191." }, { "topic": "Number Series", "question": "Find the WRONG number in the series: 2, 5, 10, 17, 26, 37, 50, 64", "options": ["10", "26", "37", "50", "64"], "correct": "E", "explanation": "The differences between consecutive terms should be consecutive odd numbers: 3, 5, 7, 9, 11, 13, 15. Checking: 5-2=3, 10-5=5, 17-10=7, 26-17=9, 37-26=11, 50-37=13 (all correct so far), but 64-50=14, which should have been 15. So the correct term should be 50+15=65, making 64 the wrong number." }, { "topic": "Quadratic Equations", "question": "I. x<sup>2</sup> - 5x + 6 = 0    II. y<sup>2</sup> - 7y + 12 = 0", "options": ["x &gt; y", "x &lt; y", "x &le; y", "x &ge; y", "No relation can be established"], "correct": "C", "explanation": "Equation I: x<sup>2</sup>-5x+6=0 &rarr; (x-2)(x-3)=0 &rarr; x = 2 or 3. Equation II: y<sup>2</sup>-7y+12=0 &rarr; (y-3)(y-4)=0 &rarr; y = 3 or 4. Comparing all combinations: x is always less than OR equal to y (x=3, y=3 gives equality; all other combinations give x&lt;y). So the relationship is x &le; y." }, { "topic": "Quadratic Equations", "question": "I. 2x<sup>2</sup> + 11x + 12 = 0    II. 2y<sup>2</sup> + 7y + 3 = 0", "options": ["x &gt; y", "x &lt; y", "x &ge; y", "x = y", "No relation can be established"], "correct": "E", "explanation": "Equation I: 2x<sup>2</sup>+11x+12=0 &rarr; x = -1.5 or -4. Equation II: 2y<sup>2</sup>+7y+3=0 &rarr; y = -0.5 or -3. Checking all combinations: (x=-1.5,y=-0.5)&rarr;x&lt;y; (x=-1.5,y=-3)&rarr;x&gt;y; (x=-4,y=-0.5)&rarr;x&lt;y; (x=-4,y=-3)&rarr;x&lt;y. Since the results are mixed (both x&lt;y and x&gt;y occur), no definite relationship can be established." }, { "topic": "Percentage", "question": "In an exam, a student scored 486 marks and obtained 81% of the maximum marks. What is the maximum marks for the exam?", "options": ["550", "580", "600", "620", "650"], "correct": "C", "explanation": "Let maximum marks = M. Then 81% of M = 486, so M = 486 &divide; 0.81 = 600." }, { "topic": "Percentage", "question": "The population of a town increased by 20% in the first year and decreased by 10% in the second year. If the population after two years is 21,600, what was the initial population?", "options": ["18,000", "19,000", "20,000", "21,000", "22,000"], "correct": "C", "explanation": "Let initial population = P. After year 1: 1.20P. After year 2: 1.20P &times; 0.90 = 1.08P. Given 1.08P = 21,600, so P = 21,600 &divide; 1.08 = 20,000." }, { "topic": "Profit & Loss", "question": "A shopkeeper bought an article for Rs. 800 and sold it at a profit of 15%. Find the selling price.", "options": ["Rs. 880", "Rs. 900", "Rs. 910", "Rs. 920", "Rs. 940"], "correct": "D", "explanation": "Selling Price = Cost Price &times; (1 + Profit%/100) = 800 &times; 1.15 = Rs. 920." }, { "topic": "Profit & Loss", "question": "By selling an article for Rs. 720, a man loses 10%. At what price should he sell it to gain 15%?", "options": ["Rs. 880", "Rs. 900", "Rs. 920", "Rs. 940", "Rs. 960"], "correct": "C", "explanation": "Since selling at Rs. 720 causes a 10% loss: Cost Price = 720 &divide; 0.90 = Rs. 800. To gain 15%: Selling Price = 800 &times; 1.15 = Rs. 920." }, { "topic": "Simple Interest", "question": "Find the simple interest on Rs. 15,000 at 8% per annum for 3 years.", "options": ["Rs. 3,200", "Rs. 3,400", "Rs. 3,600", "Rs. 3,800", "Rs. 4,000"], "correct": "C", "explanation": "Simple Interest = (Principal &times; Rate &times; Time) &divide; 100 = (15,000 &times; 8 &times; 3) &divide; 100 = Rs. 3,600." }, { "topic": "Compound Interest", "question": "Find the compound interest on Rs. 10,000 at 10% per annum for 2 years, compounded annually.", "options": ["Rs. 1,900", "Rs. 2,000", "Rs. 2,100", "Rs. 2,200", "Rs. 2,300"], "correct": "C", "explanation": "Compound Interest = P[(1+R/100)<sup>2</sup> - 1] = 10,000[(1.10)<sup>2</sup> - 1] = 10,000[1.21 - 1] = 10,000 &times; 0.21 = Rs. 2,100." }, { "topic": "Ratio & Proportion", "question": "The ratio of two numbers is 3:5. If their sum is 128, find the larger number.", "options": ["64", "72", "76", "80", "84"], "correct": "D", "explanation": "Let the numbers be 3x and 5x. Then 3x + 5x = 128 &rarr; 8x = 128 &rarr; x = 16. The larger number = 5x = 5 &times; 16 = 80." }, { "topic": "Ratio & Proportion", "question": "If A:B = 2:3 and B:C = 4:5, find A:B:C.", "options": ["6:9:15", "8:12:15", "8:12:20", "2:3:5", "6:12:15"], "correct": "B", "explanation": "To combine, make B's value common: A:B = 2:3 = 8:12 (&times;4), and B:C = 4:5 = 12:15 (&times;3). Now B matches at 12 in both. So A:B:C = 8:12:15." }, { "topic": "Average", "question": "The average age of 30 students in a class is 12 years. If the teacher's age is also included, the average becomes 13 years. Find the teacher's age.", "options": ["40 years", "41 years", "42 years", "43 years", "44 years"], "correct": "D", "explanation": "Total age of 30 students = 30 &times; 12 = 360 years. Total age including teacher (31 people) = 31 &times; 13 = 403 years. Teacher's age = 403 - 360 = 43 years." }, { "topic": "Average", "question": "The average of five numbers is 42. If one number is excluded, the average of the remaining four becomes 40. Find the excluded number.", "options": ["44", "46", "48", "50", "52"], "correct": "D", "explanation": "Sum of 5 numbers = 42 &times; 5 = 210. Sum of remaining 4 numbers = 40 &times; 4 = 160. Excluded number = 210 - 160 = 50." }, { "topic": "Time & Work", "question": "A can complete a piece of work in 12 days and B can complete it in 18 days. In how many days will they complete the work together?", "options": ["6 days", "6.5 days", "7.2 days", "7.5 days", "8 days"], "correct": "C", "explanation": "A's rate = 1/12 per day, B's rate = 1/18 per day. Combined rate = 1/12 + 1/18 = 3/36 + 2/36 = 5/36 per day. Time taken together = 36/5 = 7.2 days." }, { "topic": "Time & Work", "question": "A and B together can complete a work in 10 days. A alone can complete it in 15 days. In how many days can B alone complete the work?", "options": ["20 days", "25 days", "28 days", "30 days", "35 days"], "correct": "D", "explanation": "Combined rate = 1/10. A's rate = 1/15. B's rate = 1/10 - 1/15 = 3/30 - 2/30 = 1/30. So B alone takes 30 days." }, { "topic": "Time-Speed-Distance", "question": "A train 150 m long crosses a pole in 15 seconds. Find the speed of the train in km/h.", "options": ["30 km/h", "32 km/h", "34 km/h", "36 km/h", "40 km/h"], "correct": "D", "explanation": "Speed = Distance &divide; Time = 150 m &divide; 15 s = 10 m/s. Converting to km/h: 10 &times; 18/5 = 36 km/h." }, { "topic": "Time-Speed-Distance", "question": "Two trains of length 120 m and 180 m are running in opposite directions at speeds of 54 km/h and 36 km/h respectively. Find the time taken by them to cross each other.", "options": ["10 seconds", "11 seconds", "12 seconds", "13 seconds", "14 seconds"], "correct": "C", "explanation": "Since the trains move in opposite directions, relative speed = 54 + 36 = 90 km/h = 90 &times; 5/18 = 25 m/s. Total distance to be covered = 120 + 180 = 300 m. Time = 300 &divide; 25 = 12 seconds." }, { "topic": "Data Interpretation", "question": "What is the total number of employees across all departments in 2023?", "options": ["455", "460", "465", "470", "475"], "correct": "C", "explanation": "Total for 2023 = 150 (IT) + 45 (HR) + 70 (Finance) + 110 (Sales) + 90 (Marketing) = 465." }, { "topic": "Data Interpretation", "question": "What is the percentage increase in the number of employees in the IT department from 2022 to 2024?", "options": ["40%", "45%", "50%", "55%", "60%"], "correct": "C", "explanation": "Increase in IT employees = 180 - 120 = 60. Percentage increase = (60 &divide; 120) &times; 100 = 50%." }, { "topic": "Data Interpretation", "question": "What is the ratio of the total employees in the Finance department (over all 3 years) to the total employees in the HR department (over all 3 years)?", "options": ["39:25", "40:26", "41:27", "42:28", "43:29"], "correct": "C", "explanation": "Total Finance employees (2022+2023+2024) = 60+70+75 = 205. Total HR employees = 40+45+50 = 135. Ratio = 205:135, which simplifies (dividing both by 5) to 41:27." }, { "topic": "Mensuration", "question": "A rectangular field has a length of 25 m and a breadth of 18 m. Find the cost of fencing it at Rs. 12 per meter.", "options": ["Rs. 984", "Rs. 1,008", "Rs. 1,032", "Rs. 1,056", "Rs. 1,080"], "correct": "C", "explanation": "Perimeter of the rectangle = 2 &times; (Length + Breadth) = 2 &times; (25+18) = 2 &times; 43 = 86 m. Cost of fencing = 86 &times; 12 = Rs. 1,032." }, { "topic": "Probability", "question": "A bag contains 5 red balls, 4 blue balls, and 3 green balls. If one ball is drawn at random, what is the probability that it is either red or green?", "options": ["1/2", "5/12", "7/12", "2/3", "3/4"], "correct": "D", "explanation": "Total balls = 5+4+3 = 12. Favorable outcomes (red or green) = 5+3 = 8. Probability = 8/12 = 2/3." }, { "topic": "Simplification", "question": "(18% of 350) - (12% of 250) = ?", "options": ["29", "31", "33", "35", "37"], "correct": "C", "explanation": "18% of 350 = 63. 12% of 250 = 30. Difference = 63 - 30 = 33." }, { "topic": "Simplification", "question": "(2/5 of 625) + (3/8 of 480) = ?", "options": ["410", "420", "430", "440", "450"], "correct": "C", "explanation": "2/5 of 625 = 250. 3/8 of 480 = 180. Sum = 250 + 180 = 430." }, { "topic": "Number Series", "question": "Find the next number in the series: 4, 9, 20, 43, 90, ?", "options": ["180", "183", "185", "187", "190"], "correct": "C", "explanation": "Pattern: each term = (previous term &times; 2) + (an increasing value: 1, 2, 3, 4, 5). 4&times;2+1=9, 9&times;2+2=20, 20&times;2+3=43, 43&times;2+4=90, 90&times;2+5=185." }, { "topic": "Number Series", "question": "Find the WRONG number in the series: 6, 12, 21, 33, 48, 66, 84", "options": ["21", "33", "48", "66", "84"], "correct": "E", "explanation": "The differences should increase by 3 each time: 6, 9, 12, 15, 18, 21. Checking: 12-6=6, 21-12=9, 33-21=12, 48-33=15, 66-48=18 (correct so far), but 84-66=18, which should have been 21. The correct term should be 66+21=87, making 84 the wrong number." }, { "topic": "Quadratic Equations", "question": "I. x<sup>2</sup> + 2x - 15 = 0    II. y<sup>2</sup> - 2y - 24 = 0", "options": ["x &gt; y", "x &lt; y", "x &le; y", "x &ge; y", "No relation can be established"], "correct": "E", "explanation": "Equation I: x<sup>2</sup>+2x-15=0 &rarr; (x+5)(x-3)=0 &rarr; x = -5 or 3. Equation II: y<sup>2</sup>-2y-24=0 &rarr; (y-6)(y+4)=0 &rarr; y = 6 or -4. Checking combinations: (x=-5,y=6)&rarr;x&lt;y; (x=-5,y=-4)&rarr;x&lt;y; (x=3,y=6)&rarr;x&lt;y; (x=3,y=-4)&rarr;x&gt;y. Since results are mixed, no definite relationship can be established." }, { "topic": "Quadratic Equations", "question": "I. x<sup>2</sup> - 9x + 20 = 0    II. y<sup>2</sup> - 11y + 30 = 0", "options": ["x &gt; y", "x &lt; y", "x &le; y", "x &ge; y", "No relation can be established"], "correct": "C", "explanation": "Equation I: x<sup>2</sup>-9x+20=0 &rarr; (x-4)(x-5)=0 &rarr; x = 4 or 5. Equation II: y<sup>2</sup>-11y+30=0 &rarr; (y-5)(y-6)=0 &rarr; y = 5 or 6. Checking combinations: (x=4,y=5)&rarr;x&lt;y; (x=4,y=6)&rarr;x&lt;y; (x=5,y=5)&rarr;x=y; (x=5,y=6)&rarr;x&lt;y. Since x is always less than or equal to y (with equality possible), the relationship is x &le; y." }, { "topic": "Percentage", "question": "A number is first increased by 25% and then decreased by 20%. What is the net percentage change in the number?", "options": ["+5%", "0% (no change)", "-5%", "+10%", "-10%"], "correct": "B", "explanation": "Net multiplying factor = 1.25 &times; 0.80 = 1.00. Since the factor is exactly 1, there is no net change (0%) in the number." }, { "topic": "Percentage", "question": "In an election between two candidates, the winner received 56% of the total votes polled and won by a margin of 4,200 votes. Find the total number of votes polled.", "options": ["32,000", "33,000", "34,000", "35,000", "36,000"], "correct": "D", "explanation": "Winner got 56%, loser got 44%, so the margin represents 56%-44%=12% of total votes. 12% = 4,200, so 1% = 350, and total votes = 350 &times; 100 = 35,000." }, { "topic": "Profit & Loss", "question": "A trader marks his goods 40% above the cost price and then offers a discount of 15% on the marked price. Find his profit percentage.", "options": ["15%", "17%", "19%", "21%", "23%"], "correct": "C", "explanation": "Let Cost Price = 100. Marked Price = 140. Selling Price = 140 &times; 0.85 = 119. Profit = 119 - 100 = 19, so Profit% = 19%." }, { "topic": "Profit & Loss", "question": "A shopkeeper professes to sell his goods at cost price but uses a false weight of 800 grams instead of 1000 grams. Find his profit percentage.", "options": ["20%", "22%", "25%", "28%", "30%"], "correct": "C", "explanation": "By giving only 800g while charging for 1000g (at cost price), his profit on the actual goods used = (1000-800)/800 &times; 100 = 200/800 &times; 100 = 25%." }, { "topic": "Simple Interest", "question": "A sum of money amounts to Rs. 9,200 in 4 years and Rs. 11,600 in 7 years at simple interest. Find the principal.", "options": ["Rs. 5,000", "Rs. 5,500", "Rs. 6,000", "Rs. 6,500", "Rs. 7,000"], "correct": "C", "explanation": "SI for the extra 3 years (7-4) = 11,600 - 9,200 = Rs. 2,400, so SI per year = Rs. 800. SI for 4 years = 800 &times; 4 = Rs. 3,200. Principal = 9,200 - 3,200 = Rs. 6,000." }, { "topic": "Compound Interest", "question": "Find the difference between Compound Interest and Simple Interest on Rs. 8,000 at 10% per annum for 2 years.", "options": ["Rs. 60", "Rs. 70", "Rs. 80", "Rs. 90", "Rs. 100"], "correct": "C", "explanation": "SI = (8000 &times; 10 &times; 2)/100 = Rs. 1,600. CI = 8000[(1.10)<sup>2</sup> - 1] = 8000[1.21-1] = 8000 &times; 0.21 = Rs. 1,680. Difference = 1,680 - 1,600 = Rs. 80." }, { "topic": "Ratio & Proportion", "question": "Rs. 7,800 is divided among A, B, and C in the ratio 3:4:6. Find C's share.", "options": ["Rs. 3,200", "Rs. 3,400", "Rs. 3,600", "Rs. 3,800", "Rs. 4,000"], "correct": "C", "explanation": "Total parts = 3+4+6 = 13. C's share = (6/13) &times; 7,800 = Rs. 3,600." }, { "topic": "Ratio & Proportion", "question": "A mixture of 60 litres contains milk and water in the ratio 2:1. How many litres of water should be added to make the ratio of milk to water 1:1?", "options": ["15 litres", "18 litres", "20 litres", "22 litres", "25 litres"], "correct": "C", "explanation": "Milk = 40 litres, Water = 20 litres (from the 2:1 ratio of 60 litres). For a 1:1 ratio, water needed = 40 litres (equal to milk), so water to be added = 40 - 20 = 20 litres." }, { "topic": "Average", "question": "The average weight of 8 people increases by 2.5 kg when a new person replaces one of them who weighed 65 kg. Find the weight of the new person.", "options": ["80 kg", "82 kg", "85 kg", "88 kg", "90 kg"], "correct": "C", "explanation": "Total weight increase = 8 &times; 2.5 = 20 kg. New person's weight = 65 + 20 = 85 kg." }, { "topic": "Average", "question": "The average marks of 25 students in a class is 68. If the average of the first 15 students is 72, find the average of the remaining 10 students.", "options": ["58", "60", "62", "64", "66"], "correct": "C", "explanation": "Total marks of 25 students = 25 &times; 68 = 1,700. Total marks of first 15 = 15 &times; 72 = 1,080. Remaining 10 students' total = 1,700 - 1,080 = 620, so their average = 620/10 = 62." }, { "topic": "Time & Work", "question": "A can complete a piece of work in 20 days. B is 25% more efficient than A. In how many days can B alone complete the work?", "options": ["14 days", "15 days", "16 days", "17 days", "18 days"], "correct": "C", "explanation": "A's rate = 1/20 per day. Since B is 25% more efficient, B's rate = 1.25 &times; (1/20) = 1/16 per day. So B alone takes 16 days." }, { "topic": "Time & Work", "question": "A, B, and C can complete a work in 12, 15, and 20 days respectively. They start working together, but A leaves after 3 days. In how many more days will B and C complete the remaining work?", "options": ["3 days", "3(3/7) days", "4 days", "3(1/2) days", "3(5/7) days"], "correct": "B", "explanation": "Combined rate of A+B+C = 1/12+1/15+1/20 = 5/60+4/60+3/60 = 12/60 = 1/5. Work done in 3 days = 3/5, leaving 2/5 of the work. B+C's combined rate = 1/15+1/20 = 4/60+3/60 = 7/60. Time needed = (2/5) &divide; (7/60) = (2/5) &times; (60/7) = 24/7 = 3(3/7) days." }, { "topic": "Boats & Streams", "question": "A boat covers 24 km downstream in 2 hours and returns upstream in 3 hours. Find the speed of the boat in still water.", "options": ["8 km/h", "9 km/h", "10 km/h", "11 km/h", "12 km/h"], "correct": "C", "explanation": "Downstream speed = 24/2 = 12 km/h. Upstream speed = 24/3 = 8 km/h. Speed of boat in still water = (12+8)/2 = 10 km/h." }, { "topic": "Time-Speed-Distance", "question": "A car travels from City X to City Y at 60 km/h and returns at 40 km/h. Find the average speed for the entire round trip.", "options": ["45 km/h", "46 km/h", "48 km/h", "50 km/h", "52 km/h"], "correct": "C", "explanation": "For equal distances at two different speeds, average speed = (2 &times; a &times; b)/(a+b) = (2 &times; 60 &times; 40)/(60+40) = 4,800/100 = 48 km/h." }, { "topic": "Data Interpretation", "question": "What is the total revenue generated by all 4 products in Q2?", "options": ["155", "160", "165", "170", "175"], "correct": "C", "explanation": "Total Q2 revenue = 55 (P1) + 35 (P2) + 45 (P3) + 30 (P4) = 165." }, { "topic": "Data Interpretation", "question": "What is the percentage increase in revenue of P4 from Q1 to Q3?", "options": ["30%", "35%", "40%", "45%", "50%"], "correct": "C", "explanation": "Increase = 35 - 25 = 10. Percentage increase = (10/25) &times; 100 = 40%." }, { "topic": "Data Interpretation", "question": "What is the ratio of total revenue of P1 (across all 3 quarters) to total revenue of P3 (across all 3 quarters)?", "options": ["16:15", "15:16", "17:15", "8:7", "4:3"], "correct": "A", "explanation": "P1 total = 45+55+60 = 160. P3 total = 50+45+55 = 150. Ratio = 160:150, which simplifies (dividing by 10) to 16:15." }, { "topic": "Mensuration", "question": "The radius of a circular garden is 21 m. Find its area. (Use &pi; = 22/7)", "options": ["1,216 sq m", "1,256 sq m", "1,386 sq m", "1,466 sq m", "1,512 sq m"], "correct": "C", "explanation": "Area = &pi;r&sup2; = (22/7) &times; 21 &times; 21 = 22 &times; 3 &times; 21 = 1,386 sq m." }, { "topic": "Probability", "question": "From a well-shuffled deck of 52 playing cards, one card is drawn at random. What is the probability that it is either a King or a Queen?", "options": ["1/13", "2/13", "3/13", "4/13", "1/26"], "correct": "B", "explanation": "There are 4 Kings and 4 Queens, giving 8 favorable outcomes out of 52 total cards. Probability = 8/52 = 2/13." }] }, { "id": "reasoning", "title": "Reasoning Ability", "questions": [{ "topic": "Syllogism", "question": "Statements: All cats are dogs. All dogs are birds.<br/>Conclusions: I. All cats are birds. II. Some birds are cats.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Cannot be determined"], "correct": "C", "explanation": "All cats are dogs + All dogs are birds &rarr; by transitivity, All cats are birds (I follows). Since all cats are birds, it also means some birds are definitely cats (II follows). Both conclusions follow." }, { "topic": "Syllogism", "question": "Statements: Some pens are pencils. All pencils are erasers.<br/>Conclusions: I. Some pens are erasers. II. All erasers are pencils.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Cannot be determined"], "correct": "A", "explanation": "Some pens are pencils + All pencils are erasers &rarr; Some pens are erasers (I follows, a valid 'Some + All = Some' syllogism). II is a converse error — 'All pencils are erasers' does NOT mean 'All erasers are pencils', so II does not follow." }, { "topic": "Syllogism", "question": "Statements: No book is a pen. All pens are pencils.<br/>Conclusions: I. No pencil is a book. II. Some pencils are not books.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Cannot be determined"], "correct": "B", "explanation": "No book is a pen + All pens are pencils &rarr; Some pencils (those that are pens) are definitely not books, so II follows. However, I ('No pencil is a book') is too strong a claim — some OTHER pencils (not pens) could still be books, so I does not necessarily follow." }, { "topic": "Blood Relations", "question": "Pointing to a photograph, a man said, 'She is the daughter of my grandfather's only son.' How is the woman related to the man?", "options": ["Mother", "Sister", "Cousin", "Aunt", "Daughter"], "correct": "B", "explanation": "The man's grandfather's ONLY son must be the man's own father (since there is only one son, and the man himself traces descent through his father). The daughter of the man's father is his sister." }, { "topic": "Blood Relations", "question": "A is the brother of B. B is the sister of C. C is the father of D. How is A related to D?", "options": ["Father", "Brother", "Uncle", "Grandfather", "Cousin"], "correct": "C", "explanation": "A, B, and C are all siblings (A is B's brother, B is C's sister). Since C is D's father, and A is C's sibling, A is D's uncle." }, { "topic": "Blood Relations", "question": "Introducing a woman, a man said, 'Her mother is the only daughter of my mother.' How is the man related to the woman?", "options": ["Father", "Brother", "Maternal Uncle", "Cousin", "Grandfather"], "correct": "C", "explanation": "The 'only daughter of my mother' is the man's own sister (since he is male and she is his mother's only daughter). This sister is the woman's mother, which makes the man the woman's maternal uncle." }, { "topic": "Direction Sense", "question": "Ravi walks 5 km towards East, then turns left and walks 3 km, then turns left again and walks 5 km. How far is he from his starting point and in which direction?", "options": ["3 km, North", "5 km, East", "8 km, West", "3 km, South", "5 km, North"], "correct": "A", "explanation": "East 5 km &rarr; turn left (now facing North) &rarr; 3 km North &rarr; turn left again (now facing West) &rarr; 5 km West. The final 5 km West exactly cancels the initial 5 km East. Net displacement = 3 km due North of the starting point." }, { "topic": "Direction Sense", "question": "Point A is 10 m to the north of Point B. Point C is 6 m to the east of Point A. Point D is 6 m to the east of Point B. What is the direction of Point C with respect to Point D?", "options": ["East", "West", "North", "South", "South-West"], "correct": "C", "explanation": "Since C is 6 m east of A, and D is 6 m east of B (the same eastward shift applied to both A and B), the North-South relationship between A and B (A is 10 m north of B) is preserved between C and D. So C is 10 m north of D — i.e., C is to the North of D." }, { "topic": "Coding-Decoding", "question": "In a certain code, 'COMPUTER' is written as 'RETUPMOC'. How will 'LANGUAGE' be written in that code?", "options": ["EGAUGNAL", "LANGUAEG", "GEAUGNAL", "EAGUGNAL", "LAEGUGNA"], "correct": "A", "explanation": "The code simply reverses the letters of the word (COMPUTER reversed = RETUPMOC). Applying the same rule, LANGUAGE reversed letter-by-letter gives EGAUGNAL." }, { "topic": "Coding-Decoding", "question": "If 'TEACHER' is coded as 'VGCEJGT' (each letter shifted forward by 2 places in the alphabet), what is the code for 'STUDENT'?", "options": ["UVWFGPV", "UVWFGVP", "VUWFGPV", "UWVFGPV", "UVWGFPV"], "correct": "A", "explanation": "Each letter is shifted forward by 2: S&rarr;U, T&rarr;V, U&rarr;W, D&rarr;F, E&rarr;G, N&rarr;P, T&rarr;V. Combining gives 'UVWFGPV'." }, { "topic": "Coding-Decoding", "question": "In a certain code, 'CAT' is written as 'XZG' (each letter is replaced by the letter that is the same number of positions from the END of the alphabet as it is from the start, i.e., a mirror code where A&harr;Z, B&harr;Y, C&harr;X, etc.). What is the code for 'DOG'?", "options": ["WLT", "WLU", "XLT", "WMT", "VLT"], "correct": "A", "explanation": "Using the mirror code (position n maps to position 27-n): D(4)&rarr;23=W, O(15)&rarr;12=L, G(7)&rarr;20=T. So 'DOG' is coded as 'WLT'." }, { "topic": "Inequality", "question": "Statements: A &gt; B &ge; C = D &gt; E<br/>Conclusions: I. A &gt; E   II. B &gt; E", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Cannot be determined"], "correct": "C", "explanation": "Chain: A &gt; B &ge; C = D &gt; E. Following the chain from A to E, since there is at least one strict '&gt;' in the path, A &gt; E holds (I follows). Similarly, from B to E: B &ge; C = D &gt; E, which also guarantees B &gt; E (II follows)." }, { "topic": "Inequality", "question": "Statements: P &le; Q &lt; R; R = S &gt; T<br/>Conclusions: I. Q &lt; S   II. P &le; S", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Cannot be determined"], "correct": "C", "explanation": "Since R = S, we can substitute: P &le; Q &lt; R = S, so Q &lt; S (I follows) and P &le; Q &lt; S, which gives P &lt; S, and therefore P &le; S is also true (II follows)." }, { "topic": "Inequality", "question": "Statements: A &gt; B; C &gt; B; D &gt; C<br/>Conclusions: I. D &gt; A   II. A &gt; C", "options": ["Only I follows", "Only II follows", "Either I or II follows", "Neither I nor II follows", "Both I and II follow"], "correct": "D", "explanation": "We know A &gt; B and D &gt; C &gt; B, but there is NO direct relationship established between A and C, or between A and D, from the given statements. So neither 'D &gt; A' nor 'A &gt; C' can be confirmed — neither conclusion follows." }, { "topic": "Series", "question": "Find the next number in the series: 3, 8, 15, 24, 35, ?", "options": ["46", "47", "48", "49", "50"], "correct": "C", "explanation": "The differences between consecutive terms are 5, 7, 9, 11 (increasing by 2 each time). The next difference should be 13, so the next term = 35 + 13 = 48." }, { "topic": "Series", "question": "Find the missing number in the series: 7, 26, 63, 124, 215, ?", "options": ["330", "336", "342", "348", "354"], "correct": "C", "explanation": "Each term follows the pattern n&sup3; - 1: 2&sup3;-1=7, 3&sup3;-1=26, 4&sup3;-1=63, 5&sup3;-1=124, 6&sup3;-1=215, so the next term is 7&sup3;-1 = 343-1 = 342." }, { "topic": "Series", "question": "Find the missing term in the series: B2, D4, F6, H8, ?", "options": ["I9", "J10", "J9", "I10", "K10"], "correct": "B", "explanation": "The letters skip one each time (B, D, F, H, J — every alternate letter), and the numbers increase by 2 each time (2, 4, 6, 8, 10). The next term combines J with 10, giving 'J10'." }, { "topic": "Ranking", "question": "In a class of 40 students, Rohan is ranked 14th from the top. What is his rank from the bottom?", "options": ["25th", "26th", "27th", "28th", "29th"], "correct": "C", "explanation": "Rank from bottom = Total students - Rank from top + 1 = 40 - 14 + 1 = 27th." }, { "topic": "Ranking", "question": "Sita is 8th from the left and 15th from the right in a row of students. How many students are there in the row in total?", "options": ["20", "21", "22", "23", "24"], "correct": "C", "explanation": "Total students = (Position from left) + (Position from right) - 1 = 8 + 15 - 1 = 22 (subtracting 1 because Sita herself is counted in both positions)." }, { "topic": "Ranking", "question": "In a row of children, Aman is 10th from the left and Vijay is 12th from the right. If there are exactly 5 children seated between Aman and Vijay, how many children are there in the row in total?", "options": ["25", "26", "27", "28", "29"], "correct": "C", "explanation": "When two people are counted from opposite ends with a known number of people between them: Total = (Aman's position from left) + (Vijay's position from right) + (children between them) = 10 + 12 + 5 = 27." }, { "topic": "Puzzle", "question": "Who sits at the extreme right end of the row?", "options": ["A", "B", "C", "D", "E"], "correct": "B", "explanation": "From the solved arrangement D-E-A-C-B (left to right), the person at the extreme right end (position 5) is B." }, { "topic": "Puzzle", "question": "Who sits second to the left of C?", "options": ["A", "B", "D", "E", "None of these"], "correct": "D", "explanation": "C is at position 4. Second to the left of C is position 2, which is occupied by E." }, { "topic": "Puzzle", "question": "How many people sit between A and B?", "options": ["None", "One", "Two", "Three", "Four"], "correct": "B", "explanation": "A is at position 3 and B is at position 5. Only position 4 (occupied by C) lies between them — so exactly one person sits between A and B." }, { "topic": "Logical Reasoning", "question": "Statement: 'All employees must complete the annual compliance training by March 31 to remain eligible for their annual bonus.' Which of the following can be logically concluded from this statement?", "options": ["All employees who complete the training will definitely get a bonus", "Employees who do not complete the training by March 31 will not be eligible for the bonus", "The compliance training takes one full day to complete", "Only senior employees are required to do the training", "The bonus amount depends on training performance"], "correct": "B", "explanation": "The statement sets completing the training as a NECESSARY condition for bonus eligibility. So failing to complete it by the deadline directly means the employee is NOT eligible for the bonus. Option A is a converse error — completing the training makes one ELIGIBLE, but doesn't guarantee the bonus itself (other criteria could still apply)." }, { "topic": "Logical Reasoning", "question": "Statement: 'Ever since the new online grievance redressal system was launched, the average resolution time for customer complaints has reduced by 40%.' Which of the following, if true, would MOST STRONGLY support the claim that the new system itself caused this improvement?", "options": ["The complexity of complaints received has remained the same or increased during this period", "The company hired more customer service staff during the same period", "The number of complaints received has decreased significantly", "Customers rate the new system poorly in satisfaction surveys", "The old system was retired six months before the new one was launched"], "correct": "A", "explanation": "If complaint complexity stayed the same (or even increased) while resolution time still dropped, this rules out 'easier complaints' as an alternative explanation, strongly supporting that the NEW SYSTEM itself drove the improvement. The other options either introduce alternative causes (B, C) or contradict/weaken the claim (D, E)." }, { "topic": "Syllogism", "question": "Statements: Some teachers are writers. All writers are readers.<br/>Conclusions: I. Some teachers are readers. II. All readers are writers.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Cannot be determined"], "correct": "A", "explanation": "Some teachers are writers + All writers are readers &rarr; Some teachers are readers (I follows, a valid 'Some+All=Some' syllogism). II is a converse error ('All writers are readers' does not mean 'All readers are writers'), so II does not follow." }, { "topic": "Syllogism", "question": "Statements: All squares are rectangles. No rectangle is a triangle.<br/>Conclusions: I. No square is a triangle. II. Some rectangles are squares.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Cannot be determined"], "correct": "C", "explanation": "All squares are rectangles + No rectangle is a triangle &rarr; No square is a triangle (I follows, valid form). Also, since all squares are rectangles, by conversion, some rectangles must indeed be squares (II follows)." }, { "topic": "Syllogism", "question": "Statements: No fruit is a vegetable. Some vegetables are green.<br/>Conclusions: I. No fruit is green. II. Some green things are not fruits.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Cannot be determined"], "correct": "B", "explanation": "No fruit is vegetable + Some vegetables are green &rarr; Some green things (the ones that are vegetables) are definitely not fruits, so II follows. I ('No fruit is green') is too strong a claim, since other green things (not vegetables) could still be fruits, so I does not necessarily follow." }, { "topic": "Blood Relations", "question": "Pointing to a man, a woman said, 'His mother is the only daughter-in-law of my mother.' How is the woman related to the man?", "options": ["Mother", "Sister", "Aunt", "Nephew's wife", "Grandmother"], "correct": "C", "explanation": "'The only daughter-in-law of my mother' is the wife of the woman's brother (her mother's only son). This woman is the man's mother, meaning the man is the son of the woman's brother — i.e., the man is the woman's nephew, and the woman is his aunt." }, { "topic": "Blood Relations", "question": "A said to B, 'Your mother's husband's sister is my aunt.' How is A related to B?", "options": ["Brother", "Cousin", "Uncle", "Father", "Nephew"], "correct": "B", "explanation": "B's mother's husband is B's father. B's father's sister is B's paternal aunt. Since this same woman is also A's aunt, A's parent must be a sibling of B's father — making A and B cousins." }, { "topic": "Blood Relations", "question": "Introducing a boy, a man said, 'He is the son of my father's only daughter's husband.' How is the boy related to the man?", "options": ["Son", "Brother", "Nephew", "Cousin", "Grandson"], "correct": "C", "explanation": "The man's father's only daughter is the man's own sister. Her husband is the man's brother-in-law. The son of that husband (and the man's sister) is the man's nephew (sister's son)." }, { "topic": "Direction Sense", "question": "A person walks 8 km towards South, then turns right and walks 6 km, then turns right again and walks 8 km, then turns left and walks 4 km. How far and in which direction is he from the starting point?", "options": ["6 km, West", "10 km, West", "4 km, North", "10 km, East", "8 km, West"], "correct": "B", "explanation": "South 8 km (facing South) &rarr; turn right (now facing West) &rarr; 6 km West &rarr; turn right (now facing North) &rarr; 8 km North (exactly cancels the initial 8 km South) &rarr; turn left (now facing West) &rarr; 4 km West. Total westward movement = 6+4 = 10 km West, with zero net North-South displacement. Final position: 10 km West of start." }, { "topic": "Direction Sense", "question": "Point P is 15 m East of Point Q. Point R is 8 m North of Point P. Point S is 8 m North of Point Q. What is the direction of R with respect to S?", "options": ["North", "South", "East", "West", "South-West"], "correct": "C", "explanation": "Taking Q as origin (0,0): P = (15,0). R = 8m North of P = (15,8). S = 8m North of Q = (0,8). R and S share the same North offset (8m), so R is directly 15m East of S — R is to the East of S." }, { "topic": "Coding-Decoding", "question": "In a code, each letter of a word is alternately shifted +1 then -1 (1st letter +1, 2nd letter -1, 3rd letter +1, and so on). Using this rule, 'PENCIL' becomes 'QDOBJK'. What is the code for 'MARKET' using the same rule?", "options": ["NZSJFS", "NZSJFR", "MZSJFS", "NZTJFS", "NZSJES"], "correct": "A", "explanation": "Applying +1,-1,+1,-1,+1,-1 to M-A-R-K-E-T: M+1=N, A-1=Z (wraps around from A to Z), R+1=S, K-1=J, E+1=F, T-1=S. This gives the code 'NZSJFS'." }, { "topic": "Coding-Decoding", "question": "If in a certain code language 'SUCCESS' is written as 'TVDDFTT' (each letter shifted forward by 1), what is the code for 'FAILURE'?", "options": ["GBJMVSF", "GBJMVFS", "FBJMVSF", "GAJMVSF", "GBIMVSF"], "correct": "A", "explanation": "Shifting each letter of FAILURE forward by 1: F&rarr;G, A&rarr;B, I&rarr;J, L&rarr;M, U&rarr;V, R&rarr;S, E&rarr;F. Combining gives 'GBJMVSF'." }, { "topic": "Coding-Decoding", "question": "In a certain code, each letter is assigned a number equal to twice its position in the alphabet (A=2, B=4, C=6, ...). What is the code for the word 'CAB'?", "options": ["6-2-4", "3-1-2", "6-1-4", "5-2-4", "6-2-2"], "correct": "A", "explanation": "C is the 3rd letter, so its code is 3&times;2=6. A is the 1st letter, code=1&times;2=2. B is the 2nd letter, code=2&times;2=4. So 'CAB' is coded as '6-2-4'." }, { "topic": "Inequality", "question": "Statements: P &gt; Q &ge; R = S &lt; T<br/>Conclusions: I. P &gt; S   II. Q &lt; T", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Either I or II follows"], "correct": "A", "explanation": "From P&gt;Q&ge;R=S, we get P&gt;S directly (I follows, since the chain from P to S includes at least one strict inequality). However, from Q&ge;R=S&lt;T, we only know Q&ge;S and S&lt;T; this does NOT guarantee Q&lt;T (e.g., Q could be 10, S=5, T=6, satisfying Q&ge;S and S&lt;T, but Q&lt;T would be false). So II does not necessarily follow. Only I follows." }, { "topic": "Inequality", "question": "Statements: A &le; B &lt; C; C = D &gt; E<br/>Conclusions: I. A &lt; D   II. B &lt; D", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Either I or II follows"], "correct": "C", "explanation": "Since C=D, we can write A&le;B&lt;C=D, so A&le;B&lt;D, which means A&lt;D (I follows, since B&lt;D is strict). Also directly, B&lt;C=D, so B&lt;D (II follows)." }, { "topic": "Inequality", "question": "Statements: X &gt; Y; Z &gt; Y; X &gt; W<br/>Conclusions: I. Z &gt; W   II. X &gt; Z", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Either I or II follows"], "correct": "D", "explanation": "We know X&gt;Y, Z&gt;Y, and X&gt;W, but there is NO direct relationship established between Z and W, or between X and Z. Both conclusions require information not given, so neither I nor II follows." }, { "topic": "Series", "question": "Find the next number in the series: 2, 6, 12, 20, 30, ?", "options": ["36", "40", "42", "44", "48"], "correct": "C", "explanation": "This series follows the pattern n(n+1): 1&times;2=2, 2&times;3=6, 3&times;4=12, 4&times;5=20, 5&times;6=30, so the next term is 6&times;7=42." }, { "topic": "Series", "question": "Find the next number in the series: 8, 10, 14, 20, 28, ?", "options": ["34", "36", "38", "40", "42"], "correct": "C", "explanation": "The differences between terms increase by 2 each time: 2, 4, 6, 8, and next 10. So the next term = 28 + 10 = 38." }, { "topic": "Series", "question": "Find the WRONG number in the series: 1, 4, 10, 22, 46, 93", "options": ["4", "10", "22", "46", "93"], "correct": "E", "explanation": "Each term follows the pattern: (previous term &times; 2) + 2. 1&times;2+2=4, 4&times;2+2=10, 10&times;2+2=22, 22&times;2+2=46, and 46&times;2+2=94 (not 93). So 93 is the wrong number; it should be 94." }, { "topic": "Ranking", "question": "In a queue, Simran is 18th from the front and 25th from the back. How many people are there in the queue in total?", "options": ["40", "41", "42", "43", "44"], "correct": "C", "explanation": "Total people = (Position from front) + (Position from back) - 1 = 18 + 25 - 1 = 42." }, { "topic": "Ranking", "question": "Rakesh ranks 15th from the top and 22nd from the bottom in his class. How many students are there in the class in total?", "options": ["34", "35", "36", "37", "38"], "correct": "C", "explanation": "Total students = (Rank from top) + (Rank from bottom) - 1 = 15 + 22 - 1 = 36." }, { "topic": "Ranking", "question": "Five boxes P, Q, R, S, T are stacked vertically. Box S is at the top. Box P is immediately above Box Q. Box R is below Box S but above Box T. Box Q is immediately above Box R. What is the position of Box P from the bottom?", "options": ["2nd from bottom", "3rd from bottom", "4th from bottom", "5th from bottom", "1st from bottom"], "correct": "C", "explanation": "Given S is at the top (position 1), and the chain P above Q above R above T must fit below S: positions from top are S(1), P(2), Q(3), R(4), T(5). Counting from the bottom (5 boxes total), P at position 2 from top is the 4th position from the bottom (since T=1st from bottom, R=2nd, Q=3rd, P=4th, S=5th from bottom)." }, { "topic": "Puzzle", "question": "Who sits immediately to the left of C?", "options": ["A", "B", "D", "E", "None of these"], "correct": "B", "explanation": "In the clockwise order A-E-B-C-D, the seat immediately to the left (counter-clockwise) of C is occupied by B." }, { "topic": "Puzzle", "question": "How is D placed with respect to B?", "options": ["Immediately to the right of B", "Second to the right of B", "Immediately to the left of B", "Second to the left of B", "Third to the left of B"], "correct": "B", "explanation": "In the order A-E-B-C-D (clockwise), moving two seats clockwise (to the right) from B lands on D (B&rarr;C&rarr;D). So D is second to the right of B." }, { "topic": "Puzzle", "question": "How many people sit between E and D when counted in the clockwise direction starting from E?", "options": ["One", "Two", "Three", "Four", "None"], "correct": "B", "explanation": "Starting from E and moving clockwise: E&rarr;B&rarr;C&rarr;D. The people between E and D in this direction are B and C — a total of two people." }, { "topic": "Logical Reasoning", "question": "Statement: 'Employees who report workplace safety violations will be protected from any form of retaliation under the new company policy.' Which of the following can be logically concluded?", "options": ["All workplace accidents will be eliminated entirely", "Employees who do not report safety violations will automatically face disciplinary action", "An employee who reports a violation and subsequently faces retaliation would be experiencing a breach of this policy protection", "The policy applies only to senior management", "Reporting violations is mandatory for all employees"], "correct": "C", "explanation": "This follows directly from the stated protection: if an employee who reports a violation faces retaliation, that outcome directly contradicts/breaches the policy's explicit protection guarantee." }, { "topic": "Logical Reasoning", "question": "Statement: 'After switching to a four-day work week on a trial basis, the company observed a 15% increase in overall productivity.' Which of the following, if true, would most WEAKEN the claim that the four-day work week caused this increase?", "options": ["Employee satisfaction scores also improved during the trial period", "The company simultaneously introduced new project management software during the same trial period", "The four-day week trial lasted exactly three months", "Employees reported feeling less stressed during the trial", "The company's competitors also use a four-day work week"], "correct": "B", "explanation": "Introducing new project management software at the SAME time provides an alternative explanation (a confounding variable) for the productivity increase, weakening the claim that the four-day week alone was the cause." }] }, { "id": "pk", "title": "Professional Knowledge", "questions": [{ "topic": "DSA", "question": "What is the load factor of a hash table if it stores 45 elements in a table with 60 buckets?", "options": ["0.45", "0.60", "0.75", "1.33", "1.50"], "correct": "C", "explanation": "Load factor = number of elements stored / total number of buckets = 45/60 = 0.75. It indicates how full the hash table is and guides when rehashing is needed." }, { "topic": "DSA", "question": "Convert the infix expression (P+Q)*(R-S) into postfix notation.", "options": ["PQ+RS-*", "PQ+*RS-", "*+PQ-RS", "PQRS+-*", "+PQ*-RS"], "correct": "A", "explanation": "Using standard infix-to-postfix conversion: operands before operator, innermost first. (P+Q) becomes PQ+, (R-S) becomes RS-, then combine with * to get PQ+RS-*." }, { "topic": "DSA", "question": "Which traversal of a Binary Search Tree visits nodes in ascending sorted order?", "options": ["Preorder (Root-Left-Right)", "Inorder (Left-Root-Right)", "Postorder (Left-Right-Root)", "Level order (BFS)", "Reverse postorder"], "correct": "B", "explanation": "Inorder traversal (Left-Root-Right) of a BST always produces elements in ascending sorted order, which is why it's used for sorted output from a BST." }, { "topic": "DSA", "question": "What is the time complexity of finding the Longest Common Subsequence (LCS) of two strings of length m and n using dynamic programming?", "options": ["O(m+n)", "O(m*n)", "O(2^(m+n))", "O(m^2 * n^2)", "O(log(m*n))"], "correct": "B", "explanation": "The standard DP solution for LCS builds an (m+1) x (n+1) table, filling each cell in O(1) time, giving overall time complexity O(m*n)." }, { "topic": "DSA", "question": "Which sorting algorithm has the same time complexity (O(n log n)) in the best, average, and worst case?", "options": ["Bubble sort", "Insertion sort", "Quick sort", "Merge sort", "Selection sort"], "correct": "D", "explanation": "Merge sort always divides the array into halves and merges them, giving a consistent O(n log n) in every case, unlike quick sort whose worst case is O(n^2)." }, { "topic": "DSA", "question": "Which sorting algorithm performs the least number of swaps in the worst case (only up to n-1 swaps)?", "options": ["Bubble sort", "Insertion sort", "Selection sort", "Quick sort", "Merge sort"], "correct": "C", "explanation": "Selection sort selects the minimum element in each pass and swaps it into position at most once per pass, resulting in at most n-1 swaps overall — fewer than bubble or insertion sort." }, { "topic": "Python", "question": "In Python, why is the 'global' keyword used inside a function?", "options": ["To create a new local variable", "To allow a function to modify a variable defined outside its local scope", "To delete a variable permanently", "To import a module globally", "To make a variable constant"], "correct": "B", "explanation": "By default, assignments inside a function create a local variable. The 'global' keyword tells Python to use and modify the variable from the global/module scope instead." }, { "topic": "Python", "question": "Given the tuple a = (10, 20, 30, 40, 50), what does a[-4:-1] return?", "options": ["(20, 30, 40)", "(10, 20, 30)", "(30, 40, 50)", "(20, 30, 40, 50)", "(40, 50)"], "correct": "A", "explanation": "Negative indices count from the end: -4 is index 1 (20), -1 is index 4 (50) but the end index is exclusive, so slicing stops before index 4, giving elements at index 1,2,3 → (20, 30, 40)." }, { "topic": "Python", "question": "Which method/operator is used to check if a key exists in a Python dictionary?", "options": ["dict.contains(key)", "key in dict", "dict.find(key)", "dict.has(key)", "key.exists(dict)"], "correct": "B", "explanation": "Python uses the 'in' operator (e.g., 'key in my_dict') to efficiently check for key membership in a dictionary. The older has_key() method was removed in Python 3." }, { "topic": "OOPS", "question": "Which OOPS concept is used to hide the internal implementation details of an object and expose only the necessary functionality?", "options": ["Inheritance", "Polymorphism", "Abstraction", "Encapsulation", "Overloading"], "correct": "C", "explanation": "Abstraction focuses on hiding complex implementation details and showing only essential features to the user (e.g., an abstract class or interface), whereas Encapsulation is about bundling data and methods together." }, { "topic": "Networking", "question": "Which technology allows multiple devices on a local network to share a single public IP address while hiding internal IPs?", "options": ["VPN", "Firewall", "NAT (Network Address Translation)", "DNS", "Proxy chaining"], "correct": "C", "explanation": "NAT translates private internal IP addresses to a single public IP address (and vice versa), effectively hiding the internal network structure from external systems." }, { "topic": "Networking", "question": "Which protocol is used to map a known IP address to its corresponding physical (MAC) address on a LAN?", "options": ["DHCP", "ARP (Address Resolution Protocol)", "ICMP", "SNMP", "RARP only"], "correct": "B", "explanation": "ARP resolves a device's IP address to its MAC address so that data frames can be correctly delivered at the data link layer within a local network." }, { "topic": "Cyber Security", "question": "An attack that overwhelms a web server with a massive volume of HTTP requests from a single or multiple sources, causing it to slow down or crash, is called:", "options": ["Man-in-the-Middle attack", "SQL Injection", "HTTP Flood (DoS/DDoS) attack", "Phishing", "Session Hijacking"], "correct": "C", "explanation": "An HTTP Flood attack sends a huge number of seemingly legitimate HTTP GET/POST requests to exhaust server resources, resulting in denial of service." }, { "topic": "Cyber Security", "question": "An attacker sets up a rogue wireless access point with the same SSID as a legitimate network to trick users into connecting. This is known as:", "options": ["ARP Spoofing", "Evil Twin attack", "DNS Spoofing", "Brute Force attack", "Cross-Site Scripting (XSS)"], "correct": "B", "explanation": "In an Evil Twin attack, a fake Wi-Fi access point mimics a legitimate one's name (SSID) to intercept victims' traffic or steal credentials once they connect." }, { "topic": "Cyber Security", "question": "Which attack forces an authenticated user's browser to unknowingly send a malicious request to a web application on which the user is logged in?", "options": ["Cross-Site Request Forgery (CSRF)", "SQL Injection", "Buffer Overflow", "Evil Twin attack", "DNS Poisoning"], "correct": "A", "explanation": "CSRF exploits the trust a website has in a logged-in user's browser, tricking it into submitting unwanted requests (like fund transfers) without the user's consent." }, { "topic": "DBMS/SQL", "question": "Which ACID property ensures that if a transaction fails midway (e.g., after debiting one account but before crediting another), all partial changes are rolled back?", "options": ["Consistency", "Isolation", "Durability", "Atomicity", "Concurrency"], "correct": "D", "explanation": "Atomicity guarantees a transaction is treated as a single indivisible unit — either all its operations complete successfully, or none of them are applied (rollback on failure)." }, { "topic": "DBMS/SQL", "question": "Which SQL clause is used to group rows sharing a common value so that aggregate functions like SUM() or COUNT() can be applied to each group?", "options": ["ORDER BY", "WHERE", "GROUP BY", "HAVING", "DISTINCT"], "correct": "C", "explanation": "GROUP BY groups rows with identical values in specified columns, enabling aggregate functions to summarize data per group (often combined with HAVING to filter groups)." }, { "topic": "DBMS/SQL", "question": "Which SQL query correctly returns the 3rd highest salary from a table named employee?", "options": ["SELECT salary FROM employee ORDER BY salary ASC LIMIT 3", "SELECT salary FROM employee ORDER BY salary DESC LIMIT 2,1", "SELECT salary FROM employee WHERE salary = MAX(salary)", "SELECT TOP 3 salary FROM employee", "SELECT salary FROM employee GROUP BY salary LIMIT 3"], "correct": "B", "explanation": "Ordering salaries in descending order and using LIMIT with an OFFSET of 2 (LIMIT 2,1 in MySQL) skips the top 2 salaries and returns the 3rd highest value." }, { "topic": "DBMS/SQL", "question": "In a data warehouse, which schema design uses multiple fact tables sharing common dimension tables?", "options": ["Star Schema", "Snowflake Schema", "Fact Constellation Schema", "Flat file Schema", "Normalized Schema"], "correct": "C", "explanation": "A Fact Constellation (galaxy) schema consists of multiple fact tables that share dimension tables, unlike a Star Schema which has a single central fact table." }, { "topic": "Operating System", "question": "Which command-line utility is used at the Windows Recovery Command Prompt to attempt repair of a corrupted Master Boot Record (MBR)?", "options": ["chkdsk /f", "bootrec /fixmbr", "sfc /scannow", "diskpart /repair", "format /mbr"], "correct": "B", "explanation": "The 'bootrec /fixmbr' command writes a new, compatible Master Boot Record to the system partition, which helps resolve boot-related MBR corruption issues. Subscribe: YouTube — Way2Officers Guide Telegram: t.me/way2officersguide | @waystoofficer Ways to Officer · Dpksanu — IBPS/RRB/IBPS SO IT Officer Exam Prep" }, { "topic": "ER Model", "question": "Which relationship represents the strongest form of ownership, where the 'part' cannot exist without the 'whole'?", "options": ["Association", "Aggregation", "Composition", "Generalization", "Specialization"], "correct": "C", "explanation": "Composition is a strong 'part-of' relationship — if the whole is destroyed, its parts are destroyed too (e.g., Rooms cannot exist without a House). Aggregation is weaker; the part can exist independently." }, { "topic": "ER Model", "question": "A relationship where one Department can have many Employees, but each Employee belongs to only one Department, is an example of:", "options": ["One-to-One", "Many-to-Many", "One-to-Many", "Many-to-One only", "Self-relationship"], "correct": "C", "explanation": "This is a One-to-Many (1:N) relationship from Department to Employee — one department maps to many employees, but each employee maps back to exactly one department." }, { "topic": "ER Model", "question": "Which type of attribute can be broken down into smaller sub-parts, such as splitting 'Name' into 'First Name' and 'Last Name'?", "options": ["Simple attribute", "Derived attribute", "Composite attribute", "Multi-valued attribute", "Key attribute"], "correct": "C", "explanation": "A composite attribute can be divided into smaller sub-attributes with independent meaning, unlike a simple (atomic) attribute which cannot be divided further." }, { "topic": "Keys", "question": "Which of the following is a minimal super key, i.e., a super key from which no attribute can be removed without losing the uniqueness property?", "options": ["Foreign Key", "Candidate Key", "Alternate Key", "Composite Key", "Unique Key"], "correct": "B", "explanation": "A candidate key is a minimal super key — removing any attribute from it would cause it to lose the ability to uniquely identify rows. The primary key is chosen from among the candidate keys." }, { "topic": "Keys", "question": "Which key type can accept exactly one NULL value while still enforcing uniqueness on non-null values?", "options": ["Primary Key", "Foreign Key", "Composite Key", "Unique Key", "Super Key"], "correct": "D", "explanation": "A Unique Key enforces uniqueness like a Primary Key but, unlike a Primary Key, it allows one NULL value in most RDBMS implementations." }, { "topic": "Keys", "question": "If a child table's foreign key is set with 'ON DELETE SET NULL', what happens when the referenced parent row is deleted?", "options": ["The child row is also deleted", "The delete operation is blocked", "The foreign key value in the child row becomes NULL", "The parent row deletion fails silently", "Nothing happens to the child row"], "correct": "C", "explanation": "'ON DELETE SET NULL' sets the foreign key column in matching child rows to NULL when the referenced parent row is deleted, instead of deleting the child rows (which is what CASCADE would do)." }, { "topic": "Normalization", "question": "A table has a composite primary key (Student_ID, Subject_ID), and a non-key column 'Student_Name' depends only on Student_ID. Which normalization violation does this represent?", "options": ["Violation of 1NF", "Partial dependency (violates 2NF)", "Transitive dependency (violates 3NF)", "Violation of BCNF", "No violation — this is fully normalized"], "correct": "B", "explanation": "Since Student_Name depends only on part of the composite key (Student_ID) and not on the whole key (Student_ID, Subject_ID), this is a partial dependency, which violates 2NF." }, { "topic": "Normalization", "question": "In a table (Emp_ID, Dept_ID, Dept_Location) where Dept_Location depends on Dept_ID, and Dept_ID depends on Emp_ID, this is an example of:", "options": ["Partial dependency", "Multivalued dependency", "Transitive dependency", "Join dependency", "Functional independence"], "correct": "C", "explanation": "Dept_Location depends on Dept_ID, a non-key attribute, rather than directly on the primary key Emp_ID. This chain (Emp_ID → Dept_ID → Dept_Location) is a transitive dependency, which violates 3NF." }, { "topic": "Normalization", "question": "A relation is in BCNF if, for every non-trivial functional dependency X → Y:", "options": ["Y must be a prime attribute", "X must be a candidate key (super key)", "X and Y must both be composite", "Y must be a foreign key", "X must contain only one attribute"], "correct": "B", "explanation": "BCNF requires that for every functional dependency X → Y, X (the determinant) must be a super key. This is a stricter condition than 3NF and resolves certain anomalies 3NF cannot." }, { "topic": "Normalization", "question": "Which normal form specifically requires that all attribute values in a table be atomic (indivisible)?", "options": ["1NF", "2NF", "3NF", "BCNF", "4NF"], "correct": "A", "explanation": "1NF (First Normal Form) requires that every column contain only atomic, single values — no lists, sets, or repeating groups within a single cell." }, { "topic": "SQL", "question": "Which SQL clause is used to filter groups AFTER the GROUP BY clause has been applied, especially when filtering on an aggregate function result?", "options": ["WHERE", "HAVING", "ORDER BY", "FILTER", "GROUP FILTER"], "correct": "B", "explanation": "HAVING filters grouped results based on aggregate conditions (e.g., HAVING COUNT(*) > 5), whereas WHERE filters individual rows before grouping and cannot reference aggregate functions." }, { "topic": "SQL", "question": "Which command permanently removes both the data AND the structure of a table from the database?", "options": ["DELETE", "TRUNCATE", "DROP", "REMOVE", "CLEAR"], "correct": "C", "explanation": "DROP TABLE removes the entire table object — both its data and its schema/structure — from the database, and this action cannot be rolled back in most systems." }, { "topic": "SQL", "question": "Which SQL statement correctly retrieves the department-wise total salary, but only for departments where the total salary exceeds 100000?", "options": ["SELECT dept_id, SUM(salary) FROM emp WHERE SUM(salary) > 100000 GROUP BY dept_id", "SELECT dept_id, SUM(salary) FROM emp GROUP BY dept_id HAVING SUM(salary) > 100000", "SELECT dept_id, SUM(salary) FROM emp HAVING SUM(salary) > 100000", "SELECT dept_id, SUM(salary) FROM emp WHERE dept_id > 100000 GROUP BY dept_id", "SELECT dept_id, SUM(salary) FROM emp ORDER BY SUM(salary) > 100000"], "correct": "B", "explanation": "Aggregate conditions must be filtered using HAVING (applied after GROUP BY), not WHERE — WHERE cannot use aggregate functions like SUM() directly." }, { "topic": "SQL", "question": "Which query correctly returns the 2nd highest salary from the Employee table using the LIMIT/OFFSET approach?", "options": ["SELECT salary FROM employee ORDER BY salary ASC LIMIT 1", "SELECT salary FROM employee ORDER BY salary DESC LIMIT 1,1", "SELECT salary FROM employee ORDER BY salary DESC LIMIT 2", "SELECT MAX(salary) FROM employee", "SELECT salary FROM employee GROUP BY salary LIMIT 2"], "correct": "B", "explanation": "Ordering salaries in descending order and skipping the first (top) row using LIMIT 1,1 (OFFSET 1, fetch 1 row) correctly returns the 2nd highest salary." }, { "topic": "SQL", "question": "Which SQL command is used to grant or revoke access permissions to database users?", "options": ["DML", "DDL", "DCL", "TCL", "DQL"], "correct": "C", "explanation": "DCL (Data Control Language) commands — GRANT and REVOKE — are used to manage user access permissions and privileges on database objects." }, { "topic": "Joins", "question": "Which type of JOIN returns all rows from the left table and only the matching rows from the right table, with NULLs where there is no match?", "options": ["INNER JOIN", "RIGHT JOIN", "LEFT JOIN", "FULL OUTER JOIN", "CROSS JOIN"], "correct": "C", "explanation": "A LEFT (OUTER) JOIN returns every row from the left table, filling in NULL for columns from the right table when there is no matching row." }, { "topic": "Joins", "question": "Which JOIN automatically matches columns with the same name across two tables, without requiring an explicit ON condition?", "options": ["INNER JOIN", "SELF JOIN", "NATURAL JOIN", "CROSS JOIN", "OUTER JOIN"], "correct": "C", "explanation": "A NATURAL JOIN automatically joins tables based on all columns that share the same name and compatible data types, eliminating the need for an explicit ON/USING clause." }, { "topic": "Joins", "question": "A JOIN operation that produces the Cartesian product of two tables (every row of Table A combined with every row of Table B) is called:", "options": ["INNER JOIN", "CROSS JOIN", "SELF JOIN", "NATURAL JOIN", "LEFT JOIN"], "correct": "B", "explanation": "A CROSS JOIN produces the Cartesian product — pairing every row in the first table with every row in the second table, with no matching condition applied." }, { "topic": "Joins", "question": "Which JOIN is used when a table needs to be joined with itself, such as finding an employee's manager who is also stored in the same Employee table?", "options": ["Natural Join", "Self Join", "Cross Join", "Equi Join", "Theta Join"], "correct": "B", "explanation": "A Self Join joins a table to itself, typically using table aliases, and is commonly used for hierarchical relationships like employee-manager stored in a single table." }, { "topic": "Transactions/ACID", "question": "Which ACID property ensures that the total value of data (e.g., account balances) remains logically correct before and after a transaction?", "options": ["Atomicity", "Consistency", "Isolation", "Durability", "Concurrency"], "correct": "B", "explanation": "Consistency ensures that a transaction moves the database from one valid state to another, preserving all defined rules, constraints, and invariants (like conservation of total balance)." }, { "topic": "Transactions/ACID", "question": "Which ACID property guarantees that once a transaction is committed, its changes will survive even a system crash or power failure?", "options": ["Atomicity", "Consistency", "Isolation", "Durability", "Serializability"], "correct": "D", "explanation": "Durability ensures that committed transaction changes are permanently saved (typically to non-volatile storage/logs) and will not be lost even if the system crashes immediately afterward." }, { "topic": "Transactions/ACID", "question": "Which problem occurs when a transaction reads data that has been modified by another transaction that has NOT yet been committed?", "options": ["Lost Update", "Dirty Read", "Phantom Read", "Unrepeatable Read", "Deadlock"], "correct": "B", "explanation": "A Dirty Read happens when Transaction A reads data written by Transaction B before B commits; if B later rolls back, A has read invalid/non-existent data." }, { "topic": "Transactions/ACID", "question": "In which transaction state has the final operation been executed, but the transaction has not yet been permanently saved to the database?", "options": ["Active", "Partially Committed", "Committed", "Failed", "Aborted"], "correct": "B", "explanation": "The Partially Committed state occurs after the last statement has executed but before the changes are made permanent — the transaction can still fail during this stage (e.g., due to a system crash) before reaching Committed." }, { "topic": "Transactions/ACID", "question": "Which locking protocol ensures conflict-serializability by dividing a transaction into a 'growing phase' (acquiring locks) and a 'shrinking phase' (releasing locks)?", "options": ["Timestamp Ordering Protocol", "Two-Phase Locking (2PL) Protocol", "Optimistic Concurrency Control", "Multiversion Concurrency Control", "Validation-based Protocol"], "correct": "B", "explanation": "The Two-Phase Locking (2PL) Protocol requires a transaction to acquire all necessary locks in a growing phase before releasing any lock in a shrinking phase, guaranteeing conflict-serializable schedules." }, { "topic": "Relational Calculus", "question": "In Tuple Relational Calculus, which symbol represents the 'there exists' (existential) quantifier?", "options": ["∀", "∃", "∧", "¬", "∪"], "correct": "B", "explanation": "∃ (there exists) is the existential quantifier, meaning at least one value satisfies the given condition; ∀ (for all) is the universal quantifier, requiring the condition to hold for every value." }, { "topic": "Relational Calculus", "question": "The relational algebra expression π(name)(σ(salary>50000)(Employee)) means:", "options": ["Select employees, then find their maximum salary", "Project the salary column where name is greater than 50000", "Select employees with salary greater than 50000, then project only their names", "Join Employee table with itself on salary", "Select all employees and rename the salary column"], "correct": "C", "explanation": "σ (select) first filters rows where salary > 50000; π (project) then extracts only the 'name' column from those filtered rows — reading inside-out: select first, then project." }, { "topic": "Relational Calculus", "question": "Which relational algebra operation combines two relations by matching related tuples based on a common condition?", "options": ["Union (∪)", "Set Difference (−)", "Join (■)", "Rename (ρ)", "Project (π)"], "correct": "C", "explanation": "The Join (■) operation combines tuples from two relations that satisfy a specified join condition, effectively merging related data from both relations." }, { "topic": "Indexing/Views", "question": "Which type of index physically reorders the actual data rows on disk according to the index key, and can exist only once per table?", "options": ["Secondary Index", "Non-Clustered Index", "Clustered Index", "Unique Index", "Bitmap Index"], "correct": "C", "explanation": "A Clustered Index determines the physical storage order of data rows in the table itself, which is why a table can have only one clustered index, unlike non-clustered (secondary) indexes." }, { "topic": "Indexing/Views", "question": "What is a primary reason for using a VIEW in a database?", "options": ["To physically duplicate and store all table data permanently", "To restrict user access to specific columns/rows and simplify complex queries", "To increase data redundancy intentionally", "To replace the need for primary keys", "To automatically create backups of tables"], "correct": "B", "explanation": "Views act as virtual tables that expose only selected columns/rows to users (improving security) and simplify recurring complex queries by hiding the underlying joins/logic." }, { "topic": "OLAP/Data Warehouse", "question": "Which OLAP operation involves aggregating data by moving up a concept hierarchy, such as from 'Day' to 'Month' to 'Year'?", "options": ["Drill-down", "Roll-up", "Slice", "Dice", "Pivot"], "correct": "B", "explanation": "Roll-up aggregates data by climbing up a concept hierarchy (e.g., summarizing daily sales into monthly, then yearly totals) — the opposite of drill-down, which moves to more detailed levels. Subscribe: YouTube — Way2Officers Guide Telegram: t.me/way2officersguide | @waystoofficer Ways to Officer · Dpksanu — IBPS/RRB/IBPS SO IT Officer Exam Prep" }, { "topic": "OSI Model", "question": "Which layer of the OSI model is responsible for logical addressing and routing of packets between different networks?", "options": ["Data Link Layer", "Network Layer", "Transport Layer", "Session Layer", "Physical Layer"], "correct": "B", "explanation": "The Network Layer (Layer 3) handles logical (IP) addressing and determines the best path for packets to travel from source to destination across different networks, using routers." }, { "topic": "OSI Model", "question": "Which OSI layer is responsible for establishing, maintaining, and terminating sessions between two communicating applications?", "options": ["Presentation Layer", "Session Layer", "Transport Layer", "Application Layer", "Network Layer"], "correct": "B", "explanation": "The Session Layer (Layer 5) manages dialog control — opening, maintaining, synchronizing, and closing sessions between applications on different hosts." }, { "topic": "OSI Model", "question": "Encryption, compression, and data format translation (e.g., converting between character encodings) are handled at which OSI layer?", "options": ["Application Layer", "Session Layer", "Presentation Layer", "Transport Layer", "Data Link Layer"], "correct": "C", "explanation": "The Presentation Layer (Layer 6) is responsible for data translation, encryption/decryption, and compression so that the Application Layer receives data in a usable format." }, { "topic": "OSI Model", "question": "Which OSI layer adds MAC addresses and handles error detection/correction for frames transmitted over a physical link?", "options": ["Physical Layer", "Data Link Layer", "Network Layer", "Transport Layer", "Session Layer"], "correct": "B", "explanation": "The Data Link Layer (Layer 2) frames data, adds MAC (physical) addresses, and performs error detection (e.g., via CRC) for reliable node-to-node delivery over a single link." }, { "topic": "TCP/IP Model", "question": "How many layers does the TCP/IP reference model typically have, as compared to the OSI model's seven layers?", "options": ["Three", "Four", "Five", "Six", "Eight"], "correct": "B", "explanation": "The TCP/IP model is commonly described with four layers: Network Access (Link), Internet, Transport, and Application — condensing several OSI layers together." }, { "topic": "Transport Layer", "question": "Which transport layer protocol is connection-oriented and guarantees reliable, ordered delivery of data?", "options": ["UDP", "IP", "TCP", "ICMP", "ARP"], "correct": "C", "explanation": "TCP (Transmission Control Protocol) is connection-oriented, using acknowledgments and retransmission to guarantee reliable, in-order delivery, unlike the connectionless UDP." }, { "topic": "Transport Layer", "question": "Which protocol is preferred for real-time applications like video streaming and online gaming because it has lower overhead despite being unreliable?", "options": ["TCP", "UDP", "FTP", "HTTP", "SMTP"], "correct": "B", "explanation": "UDP (User Datagram Protocol) is connectionless with minimal overhead and no guaranteed delivery, making it faster and suitable for real-time applications where speed matters more than reliability." }, { "topic": "Delay Calculation", "question": "If a message of data size L is transmitted through N routers, with each link having a transmission rate R, what is the total transmission delay (ignoring propagation and queuing delay)?", "options": ["N × (L/R)", "(N+1) × (L/R)", "L/(N×R)", "N/(L×R)", "(N-1) × (L/R)"], "correct": "B", "explanation": "The message must be transmitted across N+1 links (N routers create N+1 hops from source to destination), so total transmission delay = (N+1) × (L/R)." }, { "topic": "Delay Calculation", "question": "Propagation delay in a network is calculated using which formula?", "options": ["Distance × Bandwidth", "Distance / Propagation speed", "Packet size / Bandwidth", "Bandwidth / Distance", "Packet size × Propagation speed"], "correct": "B", "explanation": "Propagation delay = Distance between sender and receiver / Propagation speed of the signal in the medium — it depends on physical distance and the medium, not on data size." }, { "topic": "IP Addressing", "question": "What is the default subnet mask for a Class C IP address?", "options": ["255.0.0.0", "255.255.0.0", "255.255.255.0", "255.255.255.255", "255.255.254.0"], "correct": "C", "explanation": "A Class C address has the first three octets as the network portion and the last octet for hosts, giving a default subnet mask of 255.255.255.0 (/24)." }, { "topic": "IP Addressing", "question": "Which IP address range belongs to Class A networks?", "options": ["0.0.0.0 – 127.255.255.255", "128.0.0.0 – 191.255.255.255", "192.0.0.0 – 223.255.255.255", "224.0.0.0 – 239.255.255.255", "240.0.0.0 – 255.255.255.255"], "correct": "A", "explanation": "Class A addresses range from 0.0.0.0 to 127.255.255.255 (first bit is 0), providing a large number of host addresses per network — typically used for very large networks." }, { "topic": "IP Addressing", "question": "How many usable host addresses are available in a subnet with a /28 CIDR notation?", "options": ["16", "30", "14", "62", "8"], "correct": "C", "explanation": "/28 means 4 host bits remain (32-28=4), giving 2^4 = 16 total addresses. Subtracting the network address and broadcast address leaves 14 usable host addresses." }, { "topic": "Protocols", "question": "Which protocol is used to automatically assign IP addresses to devices on a network?", "options": ["DNS", "DHCP", "ARP", "SNMP", "FTP"], "correct": "B", "explanation": "DHCP (Dynamic Host Configuration Protocol) automatically assigns IP addresses, subnet masks, gateways, and other network configuration parameters to devices joining a network." }, { "topic": "Protocols", "question": "Which protocol translates human-readable domain names (like www.example.com) into IP addresses?", "options": ["DHCP", "ARP", "DNS", "NAT", "ICMP"], "correct": "C", "explanation": "DNS (Domain Name System) resolves domain names into their corresponding IP addresses, acting like the 'phonebook' of the internet." }, { "topic": "Protocols", "question": "Which protocol is used for transferring files between a client and server, and can operate in both active and passive modes?", "options": ["HTTP", "SMTP", "FTP", "SNMP", "Telnet"], "correct": "C", "explanation": "FTP (File Transfer Protocol) is specifically designed for transferring files between systems and supports active and passive connection modes for establishing the data channel." }, { "topic": "Protocols", "question": "Which protocol is used to send email from a client to a mail server or between mail servers?", "options": ["POP3", "IMAP", "SMTP", "HTTP", "FTP"], "correct": "C", "explanation": "SMTP (Simple Mail Transfer Protocol) handles the sending/relaying of outgoing email; POP3 and IMAP are used for retrieving/reading received email." }, { "topic": "Protocols", "question": "What is a key functional difference between IMAP and POP3 for retrieving emails?", "options": ["POP3 keeps mail synced on the server while IMAP downloads and deletes it", "IMAP allows managing/manipulating emails directly on the server while POP3 typically downloads and removes them", "Both are identical in function", "POP3 is used only for sending emails", "IMAP cannot be used with attachments"], "correct": "B", "explanation": "IMAP keeps emails on the server and allows users to organize, read, and manage them across multiple devices, whereas POP3 typically downloads emails to a single device and removes them from the server." }, { "topic": "Protocols", "question": "Which protocol is used to monitor and manage network devices such as routers and switches?", "options": ["SNMP", "SMTP", "FTP", "ARP", "RIP"], "correct": "A", "explanation": "SNMP (Simple Network Management Protocol) is used to collect and organize information about managed network devices and to modify that information to change device behavior." }, { "topic": "Address Resolution", "question": "Which protocol is used to find the MAC address associated with a known IP address on a local network?", "options": ["RARP", "ARP", "DNS", "DHCP", "ICMP"], "correct": "B", "explanation": "ARP (Address Resolution Protocol) broadcasts a request on the local network to discover which device owns a given IP address, and that device replies with its MAC address." }, { "topic": "Address Resolution", "question": "Which protocol performs the reverse function of ARP — finding an IP address when only the MAC address is known?", "options": ["ARP", "RARP", "ICMP", "SNMP", "IGMP"], "correct": "B", "explanation": "RARP (Reverse Address Resolution Protocol) allows a device to request its IP address when it knows only its own MAC address (largely replaced today by DHCP)." }, { "topic": "Network Devices/NAT", "question": "Which technology allows multiple devices on a private network to share a single public IP address for internet access?", "options": ["DHCP", "NAT", "VPN", "DNS", "Proxy ARP"], "correct": "B", "explanation": "NAT (Network Address Translation) translates private internal IP addresses into a single (or few) public IP address(es), conserving public IP space and hiding internal network structure." }, { "topic": "Network Devices/NAT", "question": "Which technology creates a secure, encrypted tunnel over a public network (like the internet) to connect remote users or offices to a private network?", "options": ["NAT", "Firewall", "VPN", "Proxy Server", "Load Balancer"], "correct": "C", "explanation": "A VPN (Virtual Private Network) encrypts traffic between endpoints, effectively extending a private network securely across a public network such as the internet." }, { "topic": "Network Devices", "question": "Which network device operates at the Data Link Layer and forwards frames based on MAC addresses, effectively reducing collision domains?", "options": ["Hub", "Switch", "Repeater", "Router", "Modem"], "correct": "B", "explanation": "A Switch operates at Layer 2, learning MAC addresses of connected devices and forwarding frames only to the intended port, unlike a hub which broadcasts to all ports." }, { "topic": "Network Devices", "question": "Which device connects different networks together and forwards packets based on IP addresses, operating at the Network Layer?", "options": ["Switch", "Bridge", "Router", "Hub", "Repeater"], "correct": "C", "explanation": "A Router operates at Layer 3, using IP addresses and routing tables to determine the best path to forward packets between different networks." }, { "topic": "Security", "question": "Which type of firewall filtering technique inspects packets dynamically based on the state of active connections, rather than just static rules?", "options": ["Static Packet Filtering", "Dynamic (Stateful) Packet Filtering", "Proxy Filtering only", "MAC Filtering", "Content Filtering only"], "correct": "B", "explanation": "Dynamic/Stateful Packet Filtering firewalls track the state of active connections and make filtering decisions based on the context of the traffic flow, not just fixed rules per packet." }, { "topic": "Security", "question": "What is a Next-Generation Firewall (NGFW) generally considered to be, in terms of firewall evolution?", "options": ["First generation firewall", "Second generation firewall", "Third generation firewall", "A type of hub", "A type of DNS server"], "correct": "C", "explanation": "NGFWs are considered third-generation firewalls, combining traditional packet filtering with additional capabilities like deep packet inspection, intrusion prevention, and application awareness." }, { "topic": "Security", "question": "An attack where huge volumes of traffic are sent from a single source IP address to overwhelm a target website is best classified as:", "options": ["DDoS attack", "DoS (HTTP Flooding) attack", "Man-in-the-Middle attack", "Phishing attack", "SQL Injection"], "correct": "B", "explanation": "When the flood of traffic originates from one specific source, it is a DoS (Denial of Service) / HTTP Flooding attack; if it comes from multiple distributed sources simultaneously, it becomes a DDoS attack." }, { "topic": "Security", "question": "Which security measure primarily blocks/filters unauthorized traffic on specific ports (like HTTP port 80 or SSH port 22) but cannot prevent all forms of theft such as social engineering?", "options": ["Antivirus", "Firewall", "VPN", "IDS only", "Encryption"], "correct": "B", "explanation": "A Firewall filters and blocks traffic on defined ports/protocols based on rules, but it cannot prevent threats like social engineering, insider theft, or phishing, since these don't rely purely on network-level access." }, { "topic": "Congestion/Error Control", "question": "Which mechanism is used to detect errors in transmitted data by appending a calculated remainder bit sequence to the data before sending?", "options": ["Parity Check", "Cyclic Redundancy Check (CRC)", "Hamming Code", "Checksum", "Stop-and-Wait"], "correct": "B", "explanation": "CRC (Cyclic Redundancy Check) appends a calculated checksum-like value (derived from polynomial division) to detect errors in transmitted data blocks, widely used in Ethernet frames." }, { "topic": "Congestion/Error Control", "question": "Which flow control protocol allows the sender to transmit multiple frames before needing an acknowledgment, improving efficiency over Stop-and-Wait?", "options": ["Stop-and-Wait ARQ", "Sliding Window Protocol", "CSMA/CD", "Token Passing", "ALOHA"], "correct": "B", "explanation": "The Sliding Window Protocol allows a sender to transmit multiple frames within a defined 'window' before requiring acknowledgment, improving link utilization compared to Stop-and-Wait. Subscribe: YouTube — Way2Officers Guide Telegram: t.me/way2officersguide | @waystoofficer Ways to Officer · Dpksanu — IBPS/RRB/IBPS SO IT Officer Exam Prep" }, { "topic": "Process Management", "question": "What is the term for the process state where a process has all resources except the CPU and is waiting to be scheduled by the dispatcher?", "options": ["New", "Ready", "Running", "Waiting/Blocked", "Terminated"], "correct": "B", "explanation": "A process in the Ready state has everything it needs to run except the CPU; it waits in the ready queue until the scheduler assigns it CPU time." }, { "topic": "Process Management", "question": "Which data structure maintains all the information about a process, including its PID, program counter, CPU registers, and memory management info?", "options": ["Process Queue", "Process Control Block (PCB)", "Job Table", "Page Table", "Inode Table"], "correct": "B", "explanation": "The Process Control Block (PCB) is a data structure maintained by the OS for every process, storing its state, PID, program counter, registers, scheduling info, and memory allocation details." }, { "topic": "Process Management", "question": "What is the primary difference between a process and a thread?", "options": ["A thread has its own separate address space, a process does not", "A process is lightweight, a thread is heavyweight", "Threads within the same process share the same address space, while each process has its own separate address space", "A process cannot be scheduled independently, but a thread can be", "There is no difference"], "correct": "C", "explanation": "Threads are lightweight units of execution within a process that share the same memory/address space, whereas each process has its own independent address space and resources." }, { "topic": "CPU Scheduling", "question": "Which CPU scheduling algorithm can lead to the 'Convoy Effect', where short processes wait behind one long process?", "options": ["Shortest Job First (SJF)", "Round Robin", "First Come First Served (FCFS)", "Priority Scheduling", "Multilevel Queue"], "correct": "C", "explanation": "FCFS schedules processes strictly in arrival order; if a long process arrives first, all shorter processes behind it must wait, causing the Convoy Effect and increasing average waiting time." }, { "topic": "CPU Scheduling", "question": "Which scheduling algorithm is provably optimal for minimizing the average waiting time, but is difficult to implement because it requires knowing the burst time in advance?", "options": ["FCFS", "Round Robin", "Shortest Job First (SJF)", "Priority Scheduling (non-preemptive)", "Multilevel Feedback Queue"], "correct": "C", "explanation": "SJF minimizes average waiting time theoretically, but it requires prior knowledge of each process's CPU burst time, which is generally not known in advance in real systems." }, { "topic": "CPU Scheduling", "question": "In Round Robin scheduling, what happens if the time quantum is set too small?", "options": ["CPU utilization improves drastically with no downside", "Overhead increases significantly due to frequent context switching", "It becomes identical to FCFS", "Starvation occurs for all processes", "Deadlock occurs"], "correct": "B", "explanation": "A very small time quantum causes the CPU to switch between processes very frequently, and the overhead of context switching starts to dominate, reducing overall efficiency." }, { "topic": "CPU Scheduling", "question": "Which scheduling algorithm can cause starvation for low-priority processes if not handled with aging?", "options": ["Round Robin", "FCFS", "Priority Scheduling", "Shortest Job First (non-preemptive with equal arrival)", "None of these"], "correct": "C", "explanation": "In Priority Scheduling, low-priority processes may never get CPU time if higher-priority processes keep arriving — this is called starvation, and it's typically resolved using aging (gradually increasing priority over time)." }, { "topic": "Deadlocks", "question": "Which of the following is NOT one of the four necessary conditions for a deadlock to occur?", "options": ["Mutual Exclusion", "Hold and Wait", "Preemption", "Circular Wait", "No Preemption"], "correct": "C", "explanation": "The four necessary conditions for deadlock are Mutual Exclusion, Hold and Wait, No Preemption, and Circular Wait. 'Preemption' itself (forcibly taking a resource) is actually a strategy used to PREVENT deadlock, not a cause of it." }, { "topic": "Deadlocks", "question": "Which algorithm is used for deadlock avoidance by checking if a resource allocation will leave the system in a 'safe state' before granting it?", "options": ["Round Robin Algorithm", "Banker's Algorithm", "FIFO Algorithm", "Optimal Page Replacement Algorithm", "Clock Algorithm"], "correct": "B", "explanation": "The Banker's Algorithm avoids deadlock by simulating resource allocation and checking whether the resulting state is 'safe' (i.e., all processes can still complete) before actually granting the request." }, { "topic": "Deadlocks", "question": "Which technique for handling deadlock involves the OS taking a resource away from a process and later returning it once the deadlock is resolved?", "options": ["Deadlock Prevention", "Deadlock Avoidance", "Deadlock Detection and Recovery (via Preemption)", "Deadlock Ignorance (Ostrich algorithm)", "Mutual Exclusion Removal"], "correct": "C", "explanation": "Deadlock Recovery via Preemption involves forcibly taking resources away from one or more processes involved in a deadlock to break the cycle, allowing other processes to proceed." }, { "topic": "Memory Management", "question": "What is the main problem caused by fixed-size partitioning of memory, where allocated memory is larger than what a process actually needs?", "options": ["External Fragmentation", "Internal Fragmentation", "Thrashing", "Page Fault", "Segmentation Fault"], "correct": "B", "explanation": "Internal Fragmentation occurs when memory is allocated in fixed-size blocks, and the process doesn't use the entire block, wasting the unused space within the allocated partition." }, { "topic": "Memory Management", "question": "What is the term for wasted memory that exists between allocated blocks in variable-size partitioning, too small to be useful for any new process?", "options": ["Internal Fragmentation", "External Fragmentation", "Page Fault", "Thrashing", "Compaction"], "correct": "B", "explanation": "External Fragmentation occurs when free memory is broken into small, scattered blocks between allocated partitions, such that the total free memory may be sufficient but not contiguous enough for a new process." }, { "topic": "Memory Management", "question": "Which memory management technique divides a process's logical address space into fixed-size blocks and physical memory into frames of the same size?", "options": ["Segmentation", "Paging", "Swapping", "Overlay", "Dynamic Partitioning"], "correct": "B", "explanation": "Paging divides logical memory into fixed-size pages and physical memory into frames of the same size, eliminating external fragmentation by allowing non-contiguous allocation." }, { "topic": "Memory Management", "question": "Which memory management technique divides a process into variable-sized logical units based on the program's structure, such as functions, arrays, and stacks?", "options": ["Paging", "Segmentation", "Demand Paging", "Buddy System", "Fixed Partitioning"], "correct": "B", "explanation": "Segmentation divides a process according to logical divisions in the program (like a function, an array, or the stack), where each segment can be of a different, variable size." }, { "topic": "Memory Management", "question": "What is 'Thrashing' in the context of virtual memory management?", "options": ["A technique to speed up disk access", "A state where the system spends more time swapping pages in/out than executing actual processes", "A method for compacting memory", "A type of CPU scheduling", "A file system corruption issue"], "correct": "B", "explanation": "Thrashing occurs when the system is overcommitted with too many processes, causing excessive page faults and swapping, so the CPU spends most of its time on paging activity rather than useful execution." }, { "topic": "Memory Management", "question": "Which page replacement algorithm replaces the page that will NOT be used for the longest period of time in the future, and is theoretically optimal?", "options": ["FIFO (First In First Out)", "LRU (Least Recently Used)", "Optimal Page Replacement", "Second Chance Algorithm", "Clock Algorithm"], "correct": "C", "explanation": "The Optimal Page Replacement algorithm replaces the page that won't be needed for the longest time in the future, giving the lowest possible page-fault rate — but it requires future knowledge, so it's mainly used as a theoretical benchmark." }, { "topic": "Memory Management", "question": "Which page replacement algorithm can suffer from 'Belady's Anomaly', where increasing the number of frames can sometimes increase the number of page faults?", "options": ["LRU", "Optimal", "FIFO", "Second Chance", "Clock"], "correct": "C", "explanation": "FIFO page replacement is notably subject to Belady's Anomaly, an unusual situation where adding more frames results in more page faults, contrary to intuition." }, { "topic": "File Systems", "question": "Which of the following is NOT a valid/real file system format?", "options": ["NTFS", "ext4", "FAT32", "FAT84", "exFAT"], "correct": "D", "explanation": "FAT84 is not a real file system — the actual FAT family includes FAT12, FAT16, FAT32, and exFAT. This kind of 'spot the fake option' question has appeared in past IBPS SO IT papers." }, { "topic": "File Systems", "question": "Which file allocation method stores each file as a linked list of disk blocks, where each block contains a pointer to the next block?", "options": ["Contiguous Allocation", "Linked Allocation", "Indexed Allocation", "Direct Allocation", "FAT-based Allocation only"], "correct": "B", "explanation": "In Linked Allocation, each file is a linked list of disk blocks scattered anywhere on the disk, with each block holding a pointer to the next block in the file — this avoids external fragmentation but has slow random access." }, { "topic": "File Systems", "question": "Which file allocation method uses a separate index block containing pointers to all the blocks of a file, allowing efficient direct access?", "options": ["Linked Allocation", "Contiguous Allocation", "Indexed Allocation", "Sequential Allocation", "Bitmap Allocation"], "correct": "C", "explanation": "Indexed Allocation maintains a dedicated index block per file, storing pointers to all data blocks, which supports efficient direct (random) access without the pointer-chasing overhead of linked allocation." }, { "topic": "Boot Process", "question": "Which command, run from the Windows Recovery Command Prompt, attempts to repair a corrupted Master Boot Record (MBR)?", "options": ["chkdsk /r", "bootrec /fixmbr", "diskpart /clean", "sfc /scannow", "format c: /mbr"], "correct": "B", "explanation": "The 'bootrec /fixmbr' command writes a compatible Master Boot Record to the system partition, commonly used to resolve boot failures caused by MBR corruption." }, { "topic": "Boot Process", "question": "What is the primary function of the Master Boot Record (MBR) located in the first sector of a bootable disk?", "options": ["Store all user files", "Contain the partition table and bootloader code to start the OS boot process", "Manage RAM allocation during runtime", "Handle network configuration at startup", "Store the page table for virtual memory"], "correct": "B", "explanation": "The MBR, located in the disk's first sector, contains the partition table describing disk partitions and bootloader code that loads and starts the operating system." }, { "topic": "Linux Commands", "question": "Which Linux command, when combined with the 'ls' command's appropriate flag, sorts files by their last modified time?", "options": ["ls -a", "ls -l", "ls -t", "ls -R", "ls -h"], "correct": "C", "explanation": "'ls -t' sorts directory listing output by modification time, showing the most recently modified files first — a commonly tested Linux command in IT officer exams." }, { "topic": "Linux Commands", "question": "In Linux, which special variable holds the exit status of the most recently executed command in a bash script?", "options": ["$0", "$#", "$?", "$@", "$$"], "correct": "C", "explanation": "'$?' stores the exit status of the last executed command in bash — a value of 0 typically indicates success, while non-zero indicates an error." }, { "topic": "Linux Commands", "question": "What is the primary role of /bin/bash on a Linux system?", "options": ["It is a configuration file for network settings", "It is the executable for the Bash shell, used for command interpretation and script execution", "It stores the system's boot loader", "It is a log file for system errors", "It manages user permissions only"], "correct": "B", "explanation": "/bin/bash is the actual executable binary for the Bash (Bourne Again SHell) program, which interprets commands typed by the user or executes shell scripts." }, { "topic": "Synchronization", "question": "Which synchronization tool allows only one process/thread to access a critical section at a time, typically implemented with a binary lock value?", "options": ["Semaphore (counting)", "Mutex (Mutual Exclusion Lock)", "Monitor only", "Spinlock only", "Message Queue"], "correct": "B", "explanation": "A Mutex is a locking mechanism that allows only one thread/process to enter a critical section at a time, ensuring mutual exclusion — commonly implemented as a binary lock (locked/unlocked)." }, { "topic": "Synchronization", "question": "What is the classic problem where multiple processes read and write to a shared buffer, requiring synchronization to avoid overwriting data or reading empty slots?", "options": ["Dining Philosophers Problem", "Producer-Consumer (Bounded Buffer) Problem", "Readers-Writers Problem", "Sleeping Barber Problem", "Banker's Problem"], "correct": "B", "explanation": "The Producer-Consumer Problem involves producers adding items to a shared buffer and consumers removing them, requiring synchronization (usually via semaphores) to prevent buffer overflow/underflow and race conditions." }, { "topic": "Disk Scheduling", "question": "Which disk scheduling algorithm services requests in the order they arrive, without considering their location on the disk?", "options": ["SSTF (Shortest Seek Time First)", "SCAN", "FCFS", "C-SCAN", "LOOK"], "correct": "C", "explanation": "FCFS (First Come First Served) disk scheduling processes requests strictly in the order they are received, which can lead to poor performance if requests are scattered across the disk." }, { "topic": "Disk Scheduling", "question": "Which disk scheduling algorithm moves the disk arm in one direction servicing requests until the end, then jumps back to the beginning without servicing requests on the return trip?", "options": ["SCAN", "LOOK", "C-SCAN (Circular SCAN)", "SSTF", "FCFS"], "correct": "C", "explanation": "C-SCAN moves the disk arm in one direction servicing all requests, then quickly returns to the starting end (without servicing requests on the way back) before scanning again — providing more uniform wait times than plain SCAN." }, { "topic": "OS Concepts", "question": "Which OS technique restricts user/application input to only pre-approved, safe values or sources, often used as a security best practice?", "options": ["Blacklisting", "Whitelisting", "Sandboxing only", "Encryption", "Load Balancing"], "correct": "B", "explanation": "Whitelisting restricts input, applications, or access to only a pre-approved ('safe') list, blocking everything not explicitly allowed — a stronger security posture than blacklisting, which blocks only known bad items. Subscribe: YouTube — Way2Officers Guide Telegram: t.me/way2officersguide | @waystoofficer Ways to Officer · Dpksanu — IBPS/RRB/IBPS SO IT Officer Exam Prep" }, { "topic": "SDLC Models", "question": "Which SDLC model follows a strict sequential flow where each phase must be completed before the next begins, making it difficult to go back and make changes?", "options": ["Agile Model", "Spiral Model", "Waterfall Model", "Iterative Model", "Prototype Model"], "correct": "C", "explanation": "The Waterfall Model follows a linear, sequential flow (Requirements → Design → Implementation → Testing → Deployment → Maintenance) where each phase must fully complete before the next starts." }, { "topic": "SDLC Models", "question": "Which SDLC model combines iterative development with a strong focus on risk analysis at every cycle, making it suitable for large, complex, and high-risk projects?", "options": ["Waterfall Model", "V-Model", "Spiral Model", "Big Bang Model", "RAD Model"], "correct": "C", "explanation": "The Spiral Model combines iterative development with systematic risk analysis at each loop/cycle, making it well suited for large and risky projects where requirements may evolve." }, { "topic": "SDLC Models", "question": "Which software development model emphasizes iterative, incremental delivery, close customer collaboration, and adapting to changing requirements over following a strict plan?", "options": ["Waterfall Model", "Agile Model", "V-Model", "Big Bang Model", "Prototype Model"], "correct": "B", "explanation": "The Agile Model emphasizes short iterations (sprints), continuous customer feedback, and flexibility to adapt to changing requirements, as opposed to rigid upfront planning." }, { "topic": "SDLC Models", "question": "In the V-Model of software development, each development phase is directly associated with a corresponding testing phase. Which testing phase corresponds to the 'Requirements Analysis' phase?", "options": ["Unit Testing", "Integration Testing", "System Testing", "Acceptance Testing", "Regression Testing"], "correct": "D", "explanation": "In the V-Model, Requirements Analysis (business requirements) maps to Acceptance Testing, ensuring the final system meets the business needs defined at the very start." }, { "topic": "SDLC Models", "question": "Which SDLC model is best suited when requirements are unclear, and a working model needs to be shown to the client early for feedback before full development begins?", "options": ["Waterfall Model", "Prototype Model", "V-Model", "Big Bang Model", "Spiral Model (exclusively)"], "correct": "B", "explanation": "The Prototype Model builds a working sample/prototype of the system early on, allowing the client to review and give feedback before the actual full-scale development begins, which helps clarify unclear requirements." }, { "topic": "Testing", "question": "Which type of testing is conducted to verify that the software meets business/contractual requirements and is ready for delivery to the customer?", "options": ["Unit Testing", "Integration Testing", "System Testing", "Acceptance Testing", "Regression Testing"], "correct": "D", "explanation": "Acceptance Testing is performed to check whether the software satisfies the business requirements and compliance/contractual criteria, and is typically the final testing stage before delivery/go-live." }, { "topic": "Testing", "question": "Which type of testing focuses on verifying the smallest testable parts of an application, such as individual functions or methods, usually performed by developers?", "options": ["System Testing", "Unit Testing", "Acceptance Testing", "Regression Testing", "Stress Testing"], "correct": "B", "explanation": "Unit Testing verifies the smallest individual components (functions, methods, or classes) in isolation, typically written and executed by developers during coding." }, { "topic": "Testing", "question": "Which testing technique tests the software's functionality without any knowledge of its internal code structure, focusing only on inputs and expected outputs?", "options": ["White Box Testing", "Black Box Testing", "Grey Box Testing", "Unit Testing", "Static Testing"], "correct": "B", "explanation": "Black Box Testing examines the functionality of software without looking at its internal code/logic — testers only care about given inputs producing the expected outputs." }, { "topic": "Testing", "question": "Which testing technique requires knowledge of the internal code structure, logic, and paths, and is often used to test individual code branches and conditions?", "options": ["Black Box Testing", "White Box Testing", "Acceptance Testing", "Alpha Testing", "Beta Testing"], "correct": "B", "explanation": "White Box Testing (also called clear/glass box testing) requires knowledge of the internal code structure and is used to test specific logic paths, conditions, and branches within the code." }, { "topic": "Testing", "question": "What is the primary purpose of Regression Testing?", "options": ["To test the software for the very first time", "To verify that recent code changes have not broken existing functionality", "To test only the user interface", "To measure the software's performance under heavy load", "To test hardware compatibility only"], "correct": "B", "explanation": "Regression Testing re-runs existing test cases after code changes (bug fixes, new features) to ensure that previously working functionality has not been broken by the new changes." }, { "topic": "Testing", "question": "Which type of testing is conducted by real end-users at the customer's location, as opposed to Alpha Testing which is done in-house?", "options": ["Alpha Testing", "Beta Testing", "Smoke Testing", "Sanity Testing", "Unit Testing"], "correct": "B", "explanation": "Beta Testing is performed by actual end-users in a real-world environment (outside the development organization), after Alpha Testing has already been completed internally." }, { "topic": "Testing", "question": "Which type of testing checks whether the newly built software build is stable enough for further detailed testing (a preliminary 'build verification' check)?", "options": ["Regression Testing", "Smoke Testing", "Load Testing", "Acceptance Testing", "Mutation Testing"], "correct": "B", "explanation": "Smoke Testing is a shallow, quick test performed on a new build to verify that the critical/core functionalities work, before investing time in more detailed testing." }, { "topic": "Coupling & Cohesion", "question": "In software design, which term refers to the degree of interdependence between software modules — lower values are generally preferred for better design?", "options": ["Cohesion", "Coupling", "Abstraction", "Inheritance", "Modularity Index"], "correct": "B", "explanation": "Coupling measures how closely connected/dependent different modules are on each other. Low coupling is desirable because it makes modules easier to modify, test, and reuse independently." }, { "topic": "Coupling & Cohesion", "question": "Which term describes how strongly related and focused the responsibilities of a single module are — higher values indicate better design?", "options": ["Coupling", "Cohesion", "Fan-in", "Fan-out", "Complexity"], "correct": "B", "explanation": "Cohesion measures how closely the elements within a single module are related to each other in terms of purpose. High cohesion (a module doing one well-defined job) is considered good design." }, { "topic": "Coupling & Cohesion", "question": "Which type of coupling is considered the WORST (highest/most undesirable) form of coupling between modules?", "options": ["Data Coupling", "Stamp Coupling", "Control Coupling", "Content Coupling", "Common Coupling"], "correct": "D", "explanation": "Content Coupling is the worst form, where one module directly modifies or relies on the internal data/code of another module, creating extremely tight and fragile dependencies." }, { "topic": "UML", "question": "Which UML diagram is primarily used to represent the static structure of a system, showing classes, their attributes, methods, and relationships?", "options": ["Use Case Diagram", "Sequence Diagram", "Class Diagram", "Activity Diagram", "State Diagram"], "correct": "C", "explanation": "A Class Diagram models the static structure of a system by depicting classes, their attributes and operations, and the relationships (association, inheritance, aggregation, composition) between them." }, { "topic": "UML", "question": "Which UML diagram captures the interactions between system actors (users/external systems) and the functionalities the system provides, showing the 'what' rather than the 'how'?", "options": ["Use Case Diagram", "Class Diagram", "Sequence Diagram", "Deployment Diagram", "Component Diagram"], "correct": "A", "explanation": "A Use Case Diagram shows the functional requirements of a system from the users'/actors' perspective, illustrating which actors interact with which use cases (system functions)." }, { "topic": "UML", "question": "Which UML diagram shows the time-ordered sequence of messages exchanged between objects to accomplish a specific task or scenario?", "options": ["Class Diagram", "Sequence Diagram", "Use Case Diagram", "Deployment Diagram", "Object Diagram"], "correct": "B", "explanation": "A Sequence Diagram illustrates how objects interact with one another over time, showing the exact order in which messages/calls are exchanged for a particular scenario." }, { "topic": "Requirements Engineering", "question": "Which type of requirement describes what the system should do (specific functions/features), as opposed to how well the system performs?", "options": ["Functional Requirement", "Non-Functional Requirement", "Business Requirement only", "Design Constraint", "Quality Attribute"], "correct": "A", "explanation": "Functional Requirements define specific behaviors/functions the system must perform (e.g., 'the system shall allow users to log in'), while Non-Functional Requirements define quality attributes like performance, security, and usability." }, { "topic": "Requirements Engineering", "question": "Which of the following is an example of a Non-Functional Requirement?", "options": ["The system shall allow a user to reset their password", "The system shall generate a monthly report", "The system shall respond to any user request within 2 seconds", "The system shall allow admin users to add new products", "The system shall send a confirmation email after registration"], "correct": "C", "explanation": "A response-time constraint ('within 2 seconds') is a performance-related quality attribute — a Non-Functional Requirement — rather than a specific function the system performs." }, { "topic": "Project Management", "question": "Which software cost/effort estimation model, developed by Barry Boehm, uses factors like project size (in KLOC) to estimate effort and development time?", "options": ["Function Point Analysis only", "COCOMO (Constructive Cost Model)", "PERT", "Gantt Chart Method", "Delphi Technique"], "correct": "B", "explanation": "COCOMO (Constructive Cost Model), developed by Barry Boehm, estimates software development effort and schedule based primarily on the estimated size of the software in KLOC (thousands of lines of code)." }, { "topic": "Project Management", "question": "In COCOMO, which of the following is NOT one of its three basic project modes/categories?", "options": ["Organic", "Semi-detached", "Embedded", "Distributed", "None of the above (all three are valid)"], "correct": "D", "explanation": "COCOMO defines three project modes: Organic (simple, small teams), Semi-detached (medium complexity), and Embedded (complex, tight constraints). 'Distributed' is not one of the COCOMO project categories." }, { "topic": "Project Management", "question": "Which project management chart visually represents a project schedule using horizontal bars to show the start and end dates of individual tasks?", "options": ["PERT Chart", "Gantt Chart", "Fishbone Diagram", "Flowchart", "Class Diagram"], "correct": "B", "explanation": "A Gantt Chart is a bar-chart style scheduling tool that visually shows the start and end dates of tasks along a timeline, helping track project progress." }, { "topic": "Version Control", "question": "In Git, which command is used to combine changes from one branch into the currently checked-out branch, potentially creating a merge commit?", "options": ["git clone", "git merge", "git branch", "git fetch", "git stash"], "correct": "B", "explanation": "'git merge' integrates changes from a specified branch into the current branch, creating a merge commit if the histories have diverged (unlike 'git rebase', which rewrites commit history)." }, { "topic": "Version Control", "question": "Which Git command creates a complete local copy of a remote repository, including its full history?", "options": ["git pull", "git fetch", "git clone", "git init", "git checkout"], "correct": "C", "explanation": "'git clone' creates a full local copy of a remote repository, including all files, branches, and the complete commit history, and sets up tracking to the remote origin." }, { "topic": "Design Principles", "question": "In the SOLID design principles, what does the 'S' stand for, which states that a class should have only one reason to change?", "options": ["Simplicity Principle", "Single Responsibility Principle", "Segregation Principle", "Structure Principle", "Substitution Principle"], "correct": "B", "explanation": "The Single Responsibility Principle (SRP) states that a class should have only one job/responsibility and therefore only one reason to change, improving maintainability." }, { "topic": "Design Principles", "question": "Which SOLID principle states that objects of a superclass should be replaceable with objects of a subclass without breaking the application's correctness?", "options": ["Open/Closed Principle", "Liskov Substitution Principle", "Interface Segregation Principle", "Dependency Inversion Principle", "Single Responsibility Principle"], "correct": "B", "explanation": "The Liskov Substitution Principle (LSP) states that subtypes must be substitutable for their base types without altering the correctness of the program's behavior." }, { "topic": "Software Maintenance", "question": "Which type of software maintenance is performed to fix bugs/defects discovered after the software has been delivered to the customer?", "options": ["Adaptive Maintenance", "Perfective Maintenance", "Corrective Maintenance", "Preventive Maintenance", "Predictive Maintenance"], "correct": "C", "explanation": "Corrective Maintenance involves fixing bugs and defects that are discovered by users after the software has been deployed into production." }, { "topic": "Software Maintenance", "question": "Which type of software maintenance is carried out to modify the software so it continues to work correctly after changes in its operating environment (e.g., new OS version, new hardware)?", "options": ["Corrective Maintenance", "Adaptive Maintenance", "Perfective Maintenance", "Preventive Maintenance", "Emergency Maintenance"], "correct": "B", "explanation": "Adaptive Maintenance modifies the software to keep it compatible with a changing environment, such as new operating systems, hardware platforms, or third-party dependencies." }, { "topic": "Software Maintenance", "question": "Which type of software maintenance involves restructuring or optimizing code to improve future maintainability, without changing its external functionality?", "options": ["Corrective Maintenance", "Adaptive Maintenance", "Perfective Maintenance", "Preventive Maintenance", "Both Perfective and Preventive Maintenance"], "correct": "E", "explanation": "Preventive Maintenance (sometimes grouped with Perfective Maintenance) involves proactively restructuring, refactoring, or documenting code to make future maintenance easier, without changing what the software actually does for the user. Subscribe: YouTube — Way2Officers Guide Telegram: t.me/way2officersguide | @waystoofficer Ways to Officer · Dpksanu — IBPS/RRB/IBPS SO IT Officer Exam Prep" }, { "topic": "Number Systems", "question": "Convert the binary number 10111010 into its hexadecimal equivalent.", "options": ["B9", "BA", "AB", "A9", "9B"], "correct": "B", "explanation": "Splitting 10111010 into 4-bit groups: 1011 = B, 1010 = A. So the hexadecimal equivalent is BA." }, { "topic": "Number Systems", "question": "What is the 2's complement of the 8-bit binary number 00010110?", "options": ["11101001", "11101010", "11101000", "00010110", "11110110"], "correct": "B", "explanation": "1's complement of 00010110 is 11101001; adding 1 gives 11101010, which is the 2's complement (used to represent negative numbers in binary arithmetic)." }, { "topic": "Number Systems", "question": "Which number system is most directly and efficiently used by digital computers for internal processing and storage?", "options": ["Decimal", "Octal", "Binary", "Hexadecimal", "Roman numeral"], "correct": "C", "explanation": "Digital computers use binary (base-2) internally because digital circuits naturally represent two states (0 and 1) using voltage levels (low/high)." }, { "topic": "Computer Arithmetic", "question": "In IEEE 754 single-precision floating-point representation, how many bits are allocated to the mantissa (significand)?", "options": ["8 bits", "23 bits", "24 bits", "52 bits", "11 bits"], "correct": "B", "explanation": "IEEE 754 single precision uses 1 sign bit, 8 exponent bits, and 23 mantissa (fraction) bits, totaling 32 bits." }, { "topic": "Computer Arithmetic", "question": "Which addition method is generally used to add two signed binary numbers directly in 2's complement representation?", "options": ["Sign-magnitude addition with separate handling for signs", "Direct binary addition, discarding any final carry-out", "1's complement addition with end-around carry", "BCD addition only", "Excess-3 addition"], "correct": "B", "explanation": "In 2's complement representation, signed numbers can be added just like unsigned numbers via straightforward binary addition, and any carry-out beyond the register width is simply discarded." }, { "topic": "Instruction Cycle", "question": "What is the correct sequence of the basic instruction cycle in a CPU?", "options": ["Execute → Fetch → Decode", "Fetch → Execute → Decode", "Fetch → Decode → Execute", "Decode → Fetch → Execute", "Execute → Decode → Fetch"], "correct": "C", "explanation": "The basic instruction cycle follows Fetch (get instruction from memory) → Decode (interpret the opcode/operands) → Execute (perform the operation)." }, { "topic": "Instruction Cycle", "question": "Which CPU register holds the address of the next instruction to be fetched from memory?", "options": ["Accumulator", "Instruction Register (IR)", "Program Counter (PC)", "Memory Address Register (MAR)", "Stack Pointer (SP)"], "correct": "C", "explanation": "The Program Counter (PC) holds the memory address of the next instruction to be fetched and executed; it's automatically incremented after each fetch (unless a branch occurs)." }, { "topic": "Instruction Cycle", "question": "Which register temporarily holds the instruction that has just been fetched from memory, before it is decoded?", "options": ["Program Counter", "Instruction Register (IR)", "Memory Buffer Register (MBR)", "Status Register", "Stack Pointer"], "correct": "B", "explanation": "The Instruction Register (IR) holds the currently fetched instruction so the control unit can decode its opcode and operands." }, { "topic": "Addressing Modes", "question": "In which addressing mode does the instruction directly contain the actual data (operand) to be used, rather than a memory address?", "options": ["Direct Addressing", "Indirect Addressing", "Immediate Addressing", "Register Addressing", "Indexed Addressing"], "correct": "C", "explanation": "In Immediate Addressing mode, the operand value itself is specified directly within the instruction (e.g., MOV A, #05H), avoiding any extra memory access to fetch the data." }, { "topic": "Addressing Modes", "question": "In which addressing mode does the instruction contain the address of a memory location that itself contains the address of the actual operand?", "options": ["Direct Addressing", "Indirect Addressing", "Immediate Addressing", "Register Addressing", "Relative Addressing"], "correct": "B", "explanation": "Indirect Addressing uses a memory location as a pointer — the instruction gives an address whose contents point to another address, which finally holds the actual operand." }, { "topic": "Addressing Modes", "question": "Which addressing mode calculates the effective address by adding an offset/displacement value to the contents of the Program Counter?", "options": ["Immediate Addressing", "Direct Addressing", "Relative Addressing", "Register Indirect Addressing", "Base Addressing"], "correct": "C", "explanation": "Relative Addressing computes the effective address by adding a signed displacement to the current value of the Program Counter, commonly used for branch/jump instructions." }, { "topic": "CPU Design", "question": "Which type of instruction set architecture uses a small set of simple instructions, each typically executing in one clock cycle, favoring a load/store architecture?", "options": ["CISC", "RISC", "VLIW only", "Hybrid architecture", "Microcoded architecture only"], "correct": "B", "explanation": "RISC (Reduced Instruction Set Computer) architectures use a smaller set of simple, uniform-length instructions that execute quickly (often in one cycle), relying on load/store operations for memory access." }, { "topic": "CPU Design", "question": "Which type of instruction set architecture has a large number of complex instructions, some of which can directly operate on memory operands and take multiple clock cycles?", "options": ["RISC", "CISC", "MIPS-style RISC only", "Superscalar RISC only", "VLIW"], "correct": "B", "explanation": "CISC (Complex Instruction Set Computer) architectures support a large, complex instruction set where a single instruction may perform multi-step operations (like a memory-to-memory add), often taking multiple clock cycles." }, { "topic": "CPU Design", "question": "Which control unit design directly generates control signals using combinational logic circuits (gates/flip-flops), offering higher speed but less flexibility, as opposed to one that uses a control store of microinstructions?", "options": ["Microprogrammed Control Unit", "Hardwired Control Unit", "Nanoprogrammed Control Unit", "Firmware Control Unit", "Software Control Unit"], "correct": "B", "explanation": "A Hardwired Control Unit uses fixed combinational logic circuitry to generate control signals directly, making it fast but difficult to modify. A Microprogrammed Control Unit instead stores microinstructions in a control store, offering more flexibility at some cost to speed." }, { "topic": "Pipelining", "question": "What is the term for the performance degradation in a pipelined processor caused by a data, control, or structural hazard forcing a stall?", "options": ["Pipeline Bubble", "Cache Miss", "Page Fault", "Thrashing", "Register Spill"], "correct": "A", "explanation": "A Pipeline Bubble (or stall) occurs when the pipeline must insert a 'do-nothing' cycle to resolve a hazard (data dependency, resource conflict, or branch), delaying instruction completion." }, { "topic": "Pipelining", "question": "Which type of pipeline hazard occurs when an instruction depends on the result of a previous instruction that has not yet completed?", "options": ["Structural Hazard", "Data Hazard", "Control Hazard", "Branch Hazard only", "Resource Hazard only (different term)"], "correct": "B", "explanation": "A Data Hazard arises when an instruction needs a value that a previous, still-executing instruction hasn't yet produced, requiring stalling or forwarding to resolve." }, { "topic": "Pipelining", "question": "Which type of pipeline hazard occurs due to a conditional branch instruction, where the next instruction to fetch is not known until the branch is resolved?", "options": ["Structural Hazard", "Data Hazard", "Control Hazard", "Memory Hazard", "Register Hazard"], "correct": "C", "explanation": "A Control Hazard (branch hazard) occurs because the pipeline doesn't know which instruction to fetch next until a branch condition is evaluated, potentially causing wasted fetched instructions if mispredicted." }, { "topic": "Memory Hierarchy", "question": "What is the primary purpose of Cache Memory in a computer system?", "options": ["To provide permanent, non-volatile data storage", "To bridge the speed gap between the fast CPU and slower main memory by storing frequently accessed data", "To replace the need for RAM entirely", "To store the operating system's boot files only", "To manage network communication"], "correct": "B", "explanation": "Cache memory is a small, fast memory located close to the CPU that stores frequently/recently accessed data and instructions, reducing the average time to access data from the slower main memory." }, { "topic": "Memory Hierarchy", "question": "Which cache mapping technique allows a given block of main memory to be placed in exactly one specific cache line, determined by a fixed formula?", "options": ["Fully Associative Mapping", "Direct Mapping", "Set-Associative Mapping", "Random Mapping", "Sector Mapping"], "correct": "B", "explanation": "In Direct Mapping, each main memory block maps to exactly one specific cache line (typically block_address MOD number_of_cache_lines), making it simple and fast but prone to more conflict misses." }, { "topic": "Memory Hierarchy", "question": "Which cache mapping technique allows a memory block to be placed in ANY available cache line, offering the most flexibility but requiring more complex hardware (comparators) for searching?", "options": ["Direct Mapping", "Fully Associative Mapping", "Set-Associative Mapping", "Sequential Mapping", "Hash Mapping"], "correct": "B", "explanation": "Fully Associative Mapping allows any memory block to be placed in any cache line, minimizing conflict misses, but it requires comparing the tag against every cache line simultaneously, increasing hardware complexity." }, { "topic": "Memory Types", "question": "Which type of memory is volatile, meaning it loses all stored data when power is turned off, and is commonly used as main memory (RAM)?", "options": ["ROM", "PROM", "DRAM/SRAM", "EEPROM", "Flash Memory"], "correct": "C", "explanation": "DRAM and SRAM (types of RAM) are volatile memories, losing their stored contents as soon as power is removed, unlike non-volatile memory types such as ROM, EEPROM, or Flash." }, { "topic": "Memory Types", "question": "Which type of ROM can be erased using ultraviolet light and then reprogrammed multiple times?", "options": ["PROM", "EPROM", "EEPROM", "Mask ROM", "Flash Memory only"], "correct": "B", "explanation": "EPROM (Erasable Programmable Read-Only Memory) can be erased by exposing the chip to ultraviolet (UV) light through a small window, after which it can be reprogrammed." }, { "topic": "Memory Types", "question": "Which type of ROM can be erased and reprogrammed electrically, without needing UV light, and is commonly used in modern devices for firmware storage?", "options": ["PROM", "EPROM", "EEPROM", "Mask ROM", "Static RAM"], "correct": "C", "explanation": "EEPROM (Electrically Erasable Programmable Read-Only Memory) can be erased and rewritten electrically in-circuit, without requiring UV light exposure, making it convenient for firmware updates." }, { "topic": "I/O & Interrupts", "question": "Which data transfer technique allows peripheral devices to transfer data directly to/from main memory without continuous CPU intervention, freeing up the CPU for other tasks?", "options": ["Programmed I/O", "Interrupt-driven I/O", "Direct Memory Access (DMA)", "Polling", "Memory-mapped I/O only"], "correct": "C", "explanation": "DMA (Direct Memory Access) allows a peripheral device (via a DMA controller) to transfer data directly to/from memory, bypassing the CPU for the actual data movement, greatly improving efficiency for bulk transfers." }, { "topic": "I/O & Interrupts", "question": "What is the term for a signal sent to the CPU by a device (or software) indicating that it needs immediate attention, causing the CPU to temporarily suspend its current task?", "options": ["Trap", "Interrupt", "Exception only", "Polling Signal", "Clock Pulse"], "correct": "B", "explanation": "An Interrupt is a signal that alerts the CPU to an event requiring immediate handling, causing the CPU to pause its current execution, save its state, and jump to an Interrupt Service Routine (ISR)." }, { "topic": "I/O & Interrupts", "question": "What is the term for a small block of code that the CPU executes in response to a recognized interrupt?", "options": ["Interrupt Service Routine (ISR)", "Device Driver only", "Boot Loader", "System Call Handler only", "Kernel Thread"], "correct": "A", "explanation": "An Interrupt Service Routine (ISR), also called an interrupt handler, is the specific code executed by the CPU to respond to and process a particular interrupt." }, { "topic": "Bus Architecture", "question": "Which system bus carries the memory addresses (or I/O port addresses) that the CPU wants to access?", "options": ["Data Bus", "Address Bus", "Control Bus", "System Bus (as a separate type)", "Expansion Bus"], "correct": "B", "explanation": "The Address Bus carries the address of the memory location or I/O device the CPU wants to read from or write to; it is unidirectional (CPU to memory/device)." }, { "topic": "Bus Architecture", "question": "Which system bus is bidirectional and used to actually transfer data values between the CPU, memory, and I/O devices?", "options": ["Address Bus", "Data Bus", "Control Bus", "Clock Bus", "Reset Bus"], "correct": "B", "explanation": "The Data Bus carries the actual data being read from or written to memory/I/O devices, and is bidirectional since data can flow in either direction." }, { "topic": "Bus Architecture", "question": "Which system bus carries signals such as Read, Write, Memory/IO select, and interrupt acknowledgments to coordinate operations?", "options": ["Data Bus", "Address Bus", "Control Bus", "Expansion Bus", "Local Bus"], "correct": "C", "explanation": "The Control Bus carries command/control signals (Read, Write, Clock, Interrupt, Reset, etc.) that coordinate and synchronize activities between the CPU, memory, and I/O devices." }, { "topic": "Logic Design", "question": "Which logic gate produces a HIGH (1) output only when ALL of its inputs are HIGH (1)?", "options": ["OR gate", "AND gate", "NAND gate", "XOR gate", "NOR gate"], "correct": "B", "explanation": "An AND gate outputs 1 only when every input is 1; if any input is 0, the output is 0." }, { "topic": "Logic Design", "question": "Which logic gate is known as a 'Universal Gate' because any other logic gate can be constructed using only this gate?", "options": ["XOR gate", "AND gate", "NAND gate", "OR gate", "Buffer"], "correct": "C", "explanation": "The NAND gate (and equivalently the NOR gate) is a universal gate — any Boolean function or other logic gate (AND, OR, NOT, etc.) can be built using only NAND gates." }, { "topic": "Logic Design", "question": "Which flip-flop is commonly used to eliminate the 'race-around condition' problem found in a basic JK flip-flop?", "options": ["SR Flip-Flop", "D Flip-Flop", "Master-Slave JK Flip-Flop", "T Flip-Flop (standalone)", "Basic Latch"], "correct": "C", "explanation": "A Master-Slave JK Flip-Flop uses two flip-flops (master and slave) triggered on opposite clock edges, preventing the race-around condition that can occur in a basic JK flip-flop when J=K=1." }, { "topic": "Logic Design", "question": "Which flip-flop simply stores (holds) the value present at its input on a clock edge, and is often used in registers?", "options": ["JK Flip-Flop", "T Flip-Flop", "D Flip-Flop", "SR Flip-Flop", "Master Flip-Flop only"], "correct": "C", "explanation": "A D (Data/Delay) Flip-Flop captures and stores the value at its D input at the triggering clock edge, making it ideal for simple data storage in registers." }, { "topic": "Microprocessor Basics", "question": "In an 8085 microprocessor, how many address lines are used, and what is the resulting maximum addressable memory?", "options": ["8 address lines, 256 bytes", "16 address lines, 64 KB", "20 address lines, 1 MB", "32 address lines, 4 GB", "24 address lines, 16 MB"], "correct": "B", "explanation": "The 8085 microprocessor has 16 address lines, allowing it to address 2^16 = 65,536 bytes = 64 KB of memory directly." }, { "topic": "Microprocessor Basics", "question": "What is the size of the data bus in the Intel 8085 microprocessor?", "options": ["4-bit", "8-bit", "16-bit", "32-bit", "64-bit"], "correct": "B", "explanation": "The 8085 is an 8-bit microprocessor, meaning it has an 8-bit data bus and processes data in 8-bit chunks at a time." }, { "topic": "Microprocessor Basics", "question": "Which register in a microprocessor is used to hold the address of the top of the stack in memory?", "options": ["Program Counter", "Accumulator", "Stack Pointer (SP)", "Instruction Register", "Flag Register"], "correct": "C", "explanation": "The Stack Pointer (SP) holds the memory address of the current top of the stack, used for operations like PUSH, POP, CALL, and RET." }, { "topic": "Microprocessor Basics", "question": "Which register in a microprocessor holds status flags such as Carry, Zero, Sign, Parity, and Overflow after an ALU operation?", "options": ["Accumulator", "Program Counter", "Flag Register (Status Register)", "Stack Pointer", "Instruction Register"], "correct": "C", "explanation": "The Flag (Status) Register holds individual bits (flags) representing the outcome of the last ALU operation — such as Zero, Carry, Sign, Parity, and Overflow — used for conditional branching." }, { "topic": "8051 Microcontroller", "question": "How many bits does the 8051 microcontroller's data bus (accumulator) primarily process at a time?", "options": ["4-bit", "8-bit", "16-bit", "32-bit", "64-bit"], "correct": "B", "explanation": "The 8051 is an 8-bit microcontroller, meaning its ALU, accumulator, and data bus are designed to process 8 bits of data at a time." }, { "topic": "8051 Microcontroller", "question": "How many I/O ports does the standard 8051 microcontroller have, each typically being 8 bits wide?", "options": ["Two (P0, P1)", "Three (P0, P1, P2)", "Four (P0, P1, P2, P3)", "Five (P0-P4)", "One (P0 only)"], "correct": "C", "explanation": "The standard 8051 microcontroller has four 8-bit bidirectional I/O ports: P0, P1, P2, and P3, each usable for general-purpose I/O (with P0, P2, P3 having additional special functions)." }, { "topic": "8051 Microcontroller", "question": "How much on-chip RAM does the standard 8051 microcontroller typically have?", "options": ["64 bytes", "128 bytes", "256 bytes", "1 KB", "4 KB"], "correct": "B", "explanation": "The classic 8051 microcontroller has 128 bytes of on-chip internal RAM used for general-purpose registers, the stack, and bit-addressable memory." }, { "topic": "8051 Microcontroller", "question": "How many 16-bit timers/counters does the standard 8051 microcontroller have built in?", "options": ["One", "Two", "Three", "Four", "None — external timers required"], "correct": "B", "explanation": "The standard 8051 has two 16-bit timers/counters, Timer 0 and Timer 1, which can be used for timing operations, event counting, or generating baud rates for serial communication." }, { "topic": "8051 Microcontroller", "question": "Which pin/mechanism is used to bring the 8051 microcontroller back to its initial state, clearing registers and starting program execution from address 0000H?", "options": ["ALE pin", "RESET pin", "EA pin (External Access)", "PSEN pin", "RD pin"], "correct": "B", "explanation": "Asserting the RESET pin on the 8051 forces the microcontroller to reinitialize its internal registers (like the Program Counter, which is set to 0000H) and restart program execution from the beginning." }, { "topic": "8051 Microcontroller", "question": "Which pin on the 8051, when held LOW, forces the microcontroller to fetch program code from external memory instead of its internal ROM?", "options": ["ALE", "PSEN", "EA (External Access)", "RESET", "RD"], "correct": "C", "explanation": "The EA (External Access) pin, when held LOW, forces the 8051 to execute program instructions exclusively from external program memory, bypassing any internal ROM." }, { "topic": "Interrupts (Microcontroller)", "question": "How many interrupt sources does the standard 8051 microcontroller support?", "options": ["Two", "Three", "Four", "Five", "Six"], "correct": "D", "explanation": "The standard 8051 microcontroller supports five interrupt sources: two external interrupts (INT0, INT1), two timer interrupts (Timer 0, Timer 1 overflow), and one serial communication interrupt." }, { "topic": "Interrupts (Microcontroller)", "question": "In the 8051's interrupt priority scheme, what happens if two interrupts of the same priority level occur simultaneously?", "options": ["Both are ignored", "The interrupt with the higher fixed internal polling sequence/priority order is serviced first", "A random one is chosen", "The CPU halts until manually resolved", "Both are serviced in parallel"], "correct": "B", "explanation": "When multiple interrupts of the same priority level occur simultaneously, the 8051 uses a fixed internal polling sequence to decide which interrupt gets serviced first (e.g., external interrupt 0 typically has the highest natural priority)." }, { "topic": "Serial Communication", "question": "Which serial communication mode is used when both a start bit, 8 data bits, and a stop bit are transmitted asynchronously, common in the 8051's UART?", "options": ["Mode 0 (Shift Register mode)", "Mode 1 (8-bit UART, variable baud rate)", "Synchronous mode only", "Parallel Mode", "SPI mode"], "correct": "B", "explanation": "Mode 1 in the 8051's serial communication is the standard 8-bit UART mode, transmitting a start bit, 8 data bits, and a stop bit asynchronously, with the baud rate set by Timer 1." }, { "topic": "Assembly/Programming", "question": "In 8051 assembly language, which instruction is used to move a specific immediate value into the Accumulator?", "options": ["ADD A, #data", "MOV A, #data", "MOV A, @R0", "SUBB A, #data", "SWAP A"], "correct": "B", "explanation": "'MOV A, #data' loads an immediate constant value directly into the Accumulator register in 8051 assembly language." }, { "topic": "Assembly/Programming", "question": "Which 8051 assembly instruction is used to call a subroutine, saving the return address onto the stack?", "options": ["JMP", "CALL (LCALL/ACALL)", "RET", "PUSH", "SJMP"], "correct": "B", "explanation": "CALL instructions (LCALL for long call, ACALL for absolute call) transfer program execution to a subroutine while automatically saving the return address on the stack, so execution can resume afterward using RET." }, { "topic": "General Architecture", "question": "Which architecture uses separate memory spaces and buses for program (instruction) memory and data memory, commonly found in many microcontrollers including the 8051?", "options": ["Von Neumann Architecture", "Harvard Architecture", "RISC Architecture only", "CISC Architecture only", "Pipelined Architecture"], "correct": "B", "explanation": "Harvard Architecture uses physically separate memory and bus systems for instructions (program memory) and data, allowing simultaneous access to both — a design used in many microcontrollers, including the 8051." }, { "topic": "General Architecture", "question": "Which architecture uses a single, shared memory space and bus system for both instructions and data, requiring sequential access to each?", "options": ["Harvard Architecture", "Von Neumann Architecture", "Modified Harvard Architecture only", "Superscalar Architecture", "VLIW Architecture"], "correct": "B", "explanation": "Von Neumann Architecture stores both program instructions and data in the same memory space, accessed via a shared bus, which can create a bottleneck (the 'Von Neumann bottleneck') since only one can be accessed at a time. Subscribe: YouTube — Way2Officers Guide Telegram: t.me/way2officersguide | @waystoofficer Ways to Officer · Dpksanu — IBPS/RRB/IBPS SO IT Officer Exam Prep" }, { "topic": "DSA - Arrays", "question": "What is the time complexity of accessing an element at a given index in an array?", "options": ["O(1)", "O(n)", "O(log n)", "O(n log n)", "O(n^2)"], "correct": "A", "explanation": "Arrays provide direct/random access using index arithmetic (base_address + index*size), so accessing any element takes constant time, O(1)." }, { "topic": "DSA - Arrays", "question": "What is the worst-case time complexity of inserting an element at the beginning of an array of size n?", "options": ["O(1)", "O(log n)", "O(n)", "O(n^2)", "O(n log n)"], "correct": "C", "explanation": "Inserting at the beginning of an array requires shifting all existing n elements one position to the right, giving a worst-case time complexity of O(n)." }, { "topic": "DSA - Linked List", "question": "What is the main advantage of a Linked List over an Array for insertion and deletion operations?", "options": ["Linked Lists provide O(1) random access", "Linked Lists don't require shifting elements, allowing O(1) insertion/deletion at a known node", "Linked Lists use less memory per element", "Linked Lists are always faster to search", "Arrays cannot store more than 100 elements"], "correct": "B", "explanation": "In a Linked List, inserting or deleting a node (once you have a reference/pointer to the position) doesn't require shifting other elements, unlike an array, giving O(1) insertion/deletion at a known point." }, { "topic": "DSA - Linked List", "question": "In a Singly Linked List, what does the last node's 'next' pointer typically point to?", "options": ["The first node (head)", "NULL", "Itself", "The second-to-last node", "An empty linked list object"], "correct": "B", "explanation": "In a Singly Linked List, the last node's next pointer is set to NULL, signaling the end of the list." }, { "topic": "DSA - Linked List", "question": "Which type of linked list allows traversal in both forward and backward directions?", "options": ["Singly Linked List", "Circular Linked List (singly)", "Doubly Linked List", "Static Linked List", "None of these"], "correct": "C", "explanation": "A Doubly Linked List has two pointers per node (next and previous), enabling traversal in both forward and backward directions, unlike a singly linked list." }, { "topic": "DSA - Stack", "question": "Which data structure follows the LIFO (Last In, First Out) principle?", "options": ["Queue", "Stack", "Linked List", "Array", "Tree"], "correct": "B", "explanation": "A Stack follows LIFO — the last element pushed onto the stack is the first one popped off, like a stack of plates." }, { "topic": "DSA - Stack", "question": "Which operation removes and returns the top element of a stack?", "options": ["Push", "Pop", "Peek", "Enqueue", "Dequeue"], "correct": "B", "explanation": "The Pop operation removes the topmost element from the stack and returns its value, reducing the stack's size by one." }, { "topic": "DSA - Stack", "question": "What is a common real-world application of a stack data structure?", "options": ["Managing print job order in a printer queue", "Undo/Redo functionality in text editors and function call management (call stack)", "Breadth-First Search of a graph", "Round Robin CPU scheduling", "Storing employee records for random access"], "correct": "B", "explanation": "Stacks (LIFO) are used for undo/redo operations and to manage function call returns (the 'call stack'), where the most recently called function must return first." }, { "topic": "DSA - Queue", "question": "Which data structure follows the FIFO (First In, First Out) principle?", "options": ["Stack", "Queue", "Binary Tree", "Hash Table", "Graph"], "correct": "B", "explanation": "A Queue follows FIFO — the first element added is the first one removed, similar to a line of people waiting." }, { "topic": "DSA - Queue", "question": "In a Circular Queue, what is the main advantage over a simple linear queue?", "options": ["It allows LIFO ordering", "It efficiently reuses empty space at the front of the queue after dequeue operations, avoiding wasted space", "It doesn't require a fixed size", "It allows random access to any element in O(1)", "It automatically sorts elements"], "correct": "B", "explanation": "A Circular Queue wraps around to reuse the freed-up space at the front (after dequeue operations), preventing the wasted, unusable space that a simple linear queue would accumulate." }, { "topic": "DSA - Trees", "question": "In a Binary Search Tree (BST), where are values smaller than a node's value stored relative to that node?", "options": ["In the right subtree", "In the left subtree", "At the root only", "In a separate structure", "They cannot be stored in a BST"], "correct": "B", "explanation": "In a BST, for every node, all values in its left subtree are smaller and all values in its right subtree are greater than the node's value, enabling efficient searching." }, { "topic": "DSA - Trees", "question": "What is the time complexity of searching for an element in a balanced Binary Search Tree with n nodes?", "options": ["O(1)", "O(log n)", "O(n)", "O(n log n)", "O(n^2)"], "correct": "B", "explanation": "In a balanced BST, the height is O(log n), and since search follows a single root-to-leaf path, the search time complexity is O(log n)." }, { "topic": "DSA - Trees", "question": "What is the worst-case time complexity of searching in a BST that has degenerated into a skewed (linked-list-like) structure?", "options": ["O(1)", "O(log n)", "O(n)", "O(n^2)", "O(sqrt(n))"], "correct": "C", "explanation": "If a BST becomes skewed (e.g., all nodes inserted in sorted order, forming essentially a linked list), the height becomes n, making search operations O(n) in the worst case." }, { "topic": "DSA - Trees", "question": "Which self-balancing binary search tree automatically maintains a height difference of at most 1 between left and right subtrees of any node?", "options": ["Red-Black Tree only", "AVL Tree", "B-Tree", "Splay Tree", "Trie"], "correct": "B", "explanation": "An AVL Tree is a self-balancing BST where the balance factor (height difference between left and right subtrees) of every node is restricted to -1, 0, or +1, using rotations to maintain this property." }, { "topic": "DSA - Trees", "question": "Which tree traversal visits the Root node first, then the Left subtree, and finally the Right subtree?", "options": ["Inorder (LNR)", "Preorder (NLR)", "Postorder (LRN)", "Level order", "Reverse inorder"], "correct": "B", "explanation": "Preorder traversal follows the order Node-Left-Right (NLR): visit the root first, then recursively traverse the left subtree, then the right subtree." }, { "topic": "DSA - Trees", "question": "Which tree traversal visits the Left subtree, then the Right subtree, and finally the Root node?", "options": ["Inorder (LNR)", "Preorder (NLR)", "Postorder (LRN)", "Level order (BFS)", "Boundary traversal"], "correct": "C", "explanation": "Postorder traversal follows the order Left-Right-Node (LRN): both subtrees are fully traversed before visiting the root — commonly used to safely delete a tree, since children are processed before the parent." }, { "topic": "DSA - Graphs", "question": "Which graph traversal algorithm uses a Queue and explores all neighbors of a node before moving to the next level (level-by-level)?", "options": ["Depth-First Search (DFS)", "Breadth-First Search (BFS)", "Dijkstra's Algorithm only", "Topological Sort only", "Kruskal's Algorithm"], "correct": "B", "explanation": "BFS (Breadth-First Search) uses a Queue and explores a graph level by level, visiting all neighbors of the current node before moving deeper — useful for finding the shortest path in unweighted graphs." }, { "topic": "DSA - Graphs", "question": "Which graph traversal algorithm uses a Stack (or recursion) and explores as far as possible along a branch before backtracking?", "options": ["Breadth-First Search (BFS)", "Depth-First Search (DFS)", "Bellman-Ford Algorithm", "Prim's Algorithm", "Floyd-Warshall Algorithm"], "correct": "B", "explanation": "DFS (Depth-First Search) uses a Stack (implicit via recursion or explicit) and dives deep along one path as far as possible before backtracking to explore other branches." }, { "topic": "DSA - Graphs", "question": "Which algorithm is used to find the shortest path from a single source vertex to all other vertices in a weighted graph with non-negative edge weights?", "options": ["Kruskal's Algorithm", "Prim's Algorithm", "Dijkstra's Algorithm", "DFS", "Topological Sort"], "correct": "C", "explanation": "Dijkstra's Algorithm computes the shortest path from a single source to all other vertices in a graph with non-negative edge weights, using a greedy approach with a priority queue." }, { "topic": "DSA - Graphs", "question": "Which algorithm is used to construct a Minimum Spanning Tree (MST) by always picking the smallest available edge that doesn't form a cycle?", "options": ["Dijkstra's Algorithm", "Kruskal's Algorithm", "Bellman-Ford Algorithm", "Floyd-Warshall Algorithm", "BFS"], "correct": "B", "explanation": "Kruskal's Algorithm builds an MST by sorting all edges by weight and greedily adding the smallest edge that doesn't create a cycle (checked via Union-Find), until all vertices are connected." }, { "topic": "DSA - Sorting", "question": "Which sorting algorithm follows the 'Divide and Conquer' strategy, splitting the array into halves, sorting each recursively, and then merging them?", "options": ["Bubble Sort", "Insertion Sort", "Merge Sort", "Selection Sort", "Counting Sort"], "correct": "C", "explanation": "Merge Sort recursively divides the array into halves, sorts each half independently, and then merges the sorted halves back together, achieving a consistent O(n log n) time complexity." }, { "topic": "DSA - Sorting", "question": "Which sorting algorithm selects a 'pivot' element and partitions the array such that elements smaller than the pivot come before it, and larger ones come after?", "options": ["Merge Sort", "Quick Sort", "Bubble Sort", "Insertion Sort", "Heap Sort (directly)"], "correct": "B", "explanation": "Quick Sort works by choosing a pivot element and partitioning the array around it, then recursively sorting the sub-arrays on either side of the pivot." }, { "topic": "DSA - Sorting", "question": "Which sorting algorithm is considered 'stable', meaning equal elements retain their original relative order after sorting?", "options": ["Quick Sort", "Heap Sort", "Merge Sort", "Selection Sort", "None of the standard comparison sorts are stable"], "correct": "C", "explanation": "Merge Sort is a stable sorting algorithm — when merging, if two elements are equal, the one from the left (earlier) sub-array is placed first, preserving original relative order." }, { "topic": "DSA - Sorting", "question": "What is the average-case time complexity of Quick Sort?", "options": ["O(n)", "O(n log n)", "O(n^2)", "O(log n)", "O(2^n)"], "correct": "B", "explanation": "Quick Sort has an average-case time complexity of O(n log n), though its worst case (e.g., with a poorly chosen pivot on already sorted data) can degrade to O(n^2)." }, { "topic": "DSA - Searching", "question": "What is the prerequisite condition for applying Binary Search on an array?", "options": ["The array must contain only unique elements", "The array must be sorted", "The array must have an even number of elements", "The array must be a linked list", "The array must contain only integers"], "correct": "B", "explanation": "Binary Search requires the array to be sorted, as it repeatedly divides the search interval in half by comparing the target with the middle element and discarding the half that cannot contain it." }, { "topic": "DSA - Searching", "question": "What is the time complexity of Binary Search on a sorted array of n elements?", "options": ["O(n)", "O(log n)", "O(n log n)", "O(1)", "O(n^2)"], "correct": "B", "explanation": "Binary Search repeatedly halves the search space, so the number of comparisons needed is proportional to log2(n), giving a time complexity of O(log n)." }, { "topic": "DSA - Hashing", "question": "What is a 'collision' in the context of a hash table?", "options": ["When two different keys are hashed to the same index/bucket", "When the hash table becomes full", "When a key is deleted incorrectly", "When the hash function returns a negative value", "When two hash tables merge"], "correct": "A", "explanation": "A collision occurs when two different keys map to the same index (bucket) after applying the hash function, requiring a collision resolution strategy like chaining or open addressing." }, { "topic": "DSA - Hashing", "question": "Which collision resolution technique stores multiple colliding elements in a linked list (or similar structure) at the same bucket index?", "options": ["Linear Probing", "Quadratic Probing", "Chaining", "Double Hashing", "Perfect Hashing"], "correct": "C", "explanation": "Chaining resolves collisions by maintaining a linked list (or similar structure) at each bucket, allowing multiple keys that hash to the same index to coexist in that bucket." }, { "topic": "DSA - Complexity Notation", "question": "Which asymptotic notation is used to describe the tight (both upper and lower) bound of an algorithm's running time?", "options": ["Big O (O)", "Big Omega (Ω)", "Big Theta (Θ)", "Little o (o)", "Little omega (ω)"], "correct": "C", "explanation": "Big Theta (Θ) notation describes a tight bound, meaning the algorithm's running time is bounded both above and below by the same function (up to constant factors)." }, { "topic": "DSA - Recursion/DP", "question": "What is a key characteristic that makes a problem suitable for solving using Dynamic Programming?", "options": ["It has no repeating sub-problems", "It exhibits overlapping sub-problems and optimal substructure", "It can only be solved iteratively", "It requires exponential extra memory always", "It cannot be broken into smaller problems"], "correct": "B", "explanation": "Dynamic Programming is applicable when a problem has overlapping sub-problems (the same sub-problems are solved repeatedly) and optimal substructure (the optimal solution can be built from optimal solutions to sub-problems)." }, { "topic": "DSA - Greedy/Heap", "question": "Which data structure is typically used to efficiently implement a Priority Queue, allowing quick access to the minimum or maximum element?", "options": ["Stack", "Simple Array (unsorted)", "Heap (Binary Heap)", "Singly Linked List", "Hash Table"], "correct": "C", "explanation": "A Binary Heap (min-heap or max-heap) efficiently implements a Priority Queue, offering O(log n) insertion and O(1) access to the minimum/maximum element, with O(log n) removal." }, { "topic": "OOPS - Basics", "question": "In Object-Oriented Programming, what is a 'Class'?", "options": ["An instance of an object in memory", "A blueprint/template that defines the properties and behaviors (methods) an object will have", "A type of loop construct", "A built-in data type like int or float", "A function that returns void"], "correct": "B", "explanation": "A Class is a blueprint or template defining the attributes (data members) and methods (behaviors) that objects created from it will have; an 'object' is a specific instance of a class." }, { "topic": "OOPS - Basics", "question": "What is an 'Object' in Object-Oriented Programming?", "options": ["A class definition without any data", "A runtime instance of a class, having its own state (data) and behavior (methods)", "A function that has no return type", "A type of array", "A comment in the code"], "correct": "B", "explanation": "An Object is a concrete instance of a class created at runtime, having its own specific values for the class's attributes and access to the class's methods." }, { "topic": "OOPS - Encapsulation", "question": "What is the primary purpose of Encapsulation in OOPS?", "options": ["To allow a class to inherit from multiple parent classes", "To bundle data and methods that operate on that data within a single unit, restricting direct access to some components", "To enable a single interface to represent multiple underlying forms", "To convert an object into a string representation", "To speed up compilation time"], "correct": "B", "explanation": "Encapsulation bundles data (attributes) and the methods that operate on them into a single unit (class), while restricting direct external access to internal data (often through private/protected access modifiers and public getter/setter methods)." }, { "topic": "OOPS - Abstraction", "question": "How does Abstraction differ from Encapsulation in Object-Oriented Programming?", "options": ["They are exactly the same concept", "Abstraction hides implementation complexity and shows only essential features; Encapsulation bundles data and methods while restricting direct access", "Encapsulation is only used in interfaces, Abstraction is only used in classes", "Abstraction always requires multiple inheritance", "Encapsulation cannot be achieved without Abstraction"], "correct": "B", "explanation": "Abstraction focuses on hiding complex implementation details and exposing only necessary functionality (e.g., via abstract classes/interfaces), while Encapsulation focuses on bundling data with methods and controlling access to that data." }, { "topic": "OOPS - Inheritance", "question": "What is 'Inheritance' in Object-Oriented Programming?", "options": ["The ability of a class to have multiple constructors", "A mechanism where a new class (child/derived) acquires properties and behaviors from an existing class (parent/base)", "The process of converting one data type to another", "A way to hide a class's internal implementation entirely", "The ability to overload operators"], "correct": "B", "explanation": "Inheritance allows a derived (child) class to acquire the properties and methods of a base (parent) class, promoting code reuse and establishing an 'is-a' relationship." }, { "topic": "OOPS - Inheritance", "question": "Which type of inheritance involves a class inheriting from more than one base/parent class directly?", "options": ["Single Inheritance", "Multiple Inheritance", "Multilevel Inheritance", "Hierarchical Inheritance", "Hybrid Inheritance only"], "correct": "B", "explanation": "Multiple Inheritance occurs when a single derived class inherits directly from two or more base classes simultaneously (supported directly in languages like C++, but not in Java for classes)." }, { "topic": "OOPS - Inheritance", "question": "Which type of inheritance involves a chain, where a class is derived from another derived class (e.g., A → B → C)?", "options": ["Single Inheritance", "Multiple Inheritance", "Multilevel Inheritance", "Hierarchical Inheritance", "Hybrid Inheritance"], "correct": "C", "explanation": "Multilevel Inheritance forms a chain of inheritance, where a class inherits from a derived class, which itself inherited from another base class (e.g., Class C inherits from Class B, which inherits from Class A)." }, { "topic": "OOPS - Inheritance", "question": "Which type of inheritance involves multiple derived classes all inheriting from a single common base class?", "options": ["Single Inheritance", "Multilevel Inheritance", "Hierarchical Inheritance", "Multiple Inheritance", "Hybrid Inheritance"], "correct": "C", "explanation": "Hierarchical Inheritance occurs when multiple child classes inherit from the same single parent class (e.g., both 'Car' and 'Bike' classes inheriting from a common 'Vehicle' class)." }, { "topic": "OOPS - Inheritance", "question": "What is the 'Diamond Problem' commonly associated with multiple inheritance?", "options": ["A performance issue caused by too many objects", "An ambiguity that arises when a class inherits from two classes that both inherit from a common base class, causing conflicting inherited members", "A syntax error found only in interpreted languages", "A memory leak caused by circular references", "An issue only found in single inheritance"], "correct": "B", "explanation": "The Diamond Problem arises when a class inherits from two classes that share a common base class, creating ambiguity about which inherited version of a member/method should be used — languages handle this differently (e.g., C++ uses virtual inheritance, Java avoids it by disallowing multiple class inheritance)." }, { "topic": "OOPS - Polymorphism", "question": "What does 'Polymorphism' mean in Object-Oriented Programming?", "options": ["The ability of an object to take on many forms, allowing the same interface/method name to behave differently based on context", "The ability to hide a class's data completely", "The process of creating multiple copies of the same object", "A technique for reducing memory usage in arrays", "The ability to inherit from only one class"], "correct": "A", "explanation": "Polymorphism (meaning 'many forms') allows objects of different classes to be treated through a common interface, and the same method name/call can behave differently depending on the actual object type or arguments involved." }, { "topic": "OOPS - Polymorphism", "question": "What is 'Compile-Time Polymorphism' (also known as Static Polymorphism), typically achieved through method/function overloading?", "options": ["Polymorphism resolved during program execution based on the actual object type", "Polymorphism resolved at compile time, based on the number/type of arguments passed to a method with the same name", "A feature only available in dynamically-typed languages", "The same as multiple inheritance", "A type of runtime exception handling"], "correct": "B", "explanation": "Compile-Time (Static) Polymorphism is resolved during compilation, typically via method overloading, where multiple methods share the same name but differ in parameter type/count/order, and the compiler decides which to call based on the arguments." }, { "topic": "OOPS - Polymorphism", "question": "What is 'Run-Time Polymorphism' (also known as Dynamic Polymorphism), typically achieved through method overriding?", "options": ["Polymorphism resolved during compilation", "Polymorphism where the method to be executed is determined at runtime based on the actual object type (often via virtual functions)", "A feature that only works with primitive data types", "The process of hiding data members", "A synonym for method overloading"], "correct": "B", "explanation": "Run-Time (Dynamic) Polymorphism is resolved during program execution, typically through method overriding and virtual functions, where the actual method invoked depends on the real (derived) object type, not just the reference/pointer type." }, { "topic": "OOPS - Polymorphism", "question": "What is the key difference between Method Overloading and Method Overriding?", "options": ["Overloading occurs across different classes with inheritance; Overriding occurs within the same class", "Overloading is same method name with different parameters within the same class (or scope); Overriding is redefining a parent class's method with the same signature in a derived class", "Both are exactly identical concepts", "Overriding can only occur with static methods", "Overloading requires inheritance, but overriding does not"], "correct": "B", "explanation": "Overloading defines multiple methods with the same name but different parameter lists within the same class (resolved at compile time), while Overriding redefines a method with the exact same signature in a derived class to provide specific behavior (resolved at runtime)." }, { "topic": "OOPS - Constructors", "question": "What is a 'Constructor' in Object-Oriented Programming?", "options": ["A special method used to destroy an object when it goes out of scope", "A special method automatically invoked when an object is created, typically used to initialize its data members", "A method that must always return a value", "A keyword used to inherit from a base class", "A type of loop used only in classes"], "correct": "B", "explanation": "A Constructor is a special method with the same name as the class (in most languages) that is automatically called when an object is instantiated, primarily used to initialize the object's attributes." }, { "topic": "OOPS - Constructors", "question": "What is a 'Destructor', and when is it typically invoked?", "options": ["A method invoked when an object is created, to allocate memory", "A special method invoked automatically when an object is destroyed or goes out of scope, typically used to release resources", "A method used to overload operators", "A method that must have parameters", "A synonym for a static method"], "correct": "B", "explanation": "A Destructor is a special method (e.g., ~ClassName() in C++) automatically invoked when an object is destroyed or goes out of scope, typically used to release resources like memory, file handles, or network connections that the object was holding." }, { "topic": "OOPS - Constructors", "question": "What is a 'Copy Constructor' used for?", "options": ["To destroy an existing object", "To create a new object as a copy of an existing object of the same class", "To convert one class type into another entirely different class", "To overload the addition operator", "To define static class members"], "correct": "B", "explanation": "A Copy Constructor creates a new object by copying the data members from an already existing object of the same class, commonly invoked during object initialization from another object or when passing/returning objects by value." }, { "topic": "OOPS - Access Modifiers", "question": "Which access modifier allows a class member to be accessed only within the same class, and not from derived classes or outside code?", "options": ["Public", "Protected", "Private", "Friend", "Internal"], "correct": "C", "explanation": "The Private access modifier restricts a member's visibility to only within the class it is declared in — it cannot be directly accessed from derived classes or external code." }, { "topic": "OOPS - Access Modifiers", "question": "Which access modifier allows a class member to be accessed within the same class AND by derived (child) classes, but not by unrelated external code?", "options": ["Public", "Private", "Protected", "Static", "Final"], "correct": "C", "explanation": "The Protected access modifier allows access within the declaring class and its subclasses (derived classes), while still restricting access from unrelated external code." }, { "topic": "OOPS - Access Modifiers", "question": "Which access modifier allows a class member to be accessed from anywhere in the program, without any restriction?", "options": ["Private", "Protected", "Public", "Internal only", "Package-private only"], "correct": "C", "explanation": "The Public access modifier places no restriction on visibility — the member can be accessed from any part of the program, including outside the class and outside its package/module." }, { "topic": "OOPS - Keywords", "question": "What is the primary purpose of the 'this' keyword (or its equivalent, e.g., 'self') in Object-Oriented Programming?", "options": ["To call a static method", "To refer to the current instance/object within a class's own method", "To declare a constant value", "To inherit from a parent class explicitly", "To define an abstract method"], "correct": "B", "explanation": "The 'this' keyword refers to the current object instance within a non-static method, commonly used to distinguish instance variables from parameters/local variables with the same name, or to pass the current object as a reference." }, { "topic": "OOPS - Keywords", "question": "What is the primary purpose of the 'super' keyword (or its equivalent) in Object-Oriented Programming?", "options": ["To refer to the current object instance", "To refer to the immediate parent (base) class, often used to call its constructor or overridden methods", "To declare a variable as constant", "To create multiple objects at once", "To define a private method"], "correct": "B", "explanation": "The 'super' keyword is used within a derived class to refer to its immediate parent class, commonly to invoke the parent's constructor or to call an overridden method's original parent implementation." }, { "topic": "OOPS - Static Members", "question": "What does declaring a class member as 'static' generally mean in Object-Oriented Programming?", "options": ["The member belongs to each individual object separately", "The member belongs to the class itself rather than any individual object, and is shared across all instances", "The member can never be modified once set", "The member must always be private", "The member is automatically destroyed after use"], "correct": "B", "explanation": "A static member belongs to the class as a whole rather than to any specific object instance — all objects of the class share the same single copy of that static member." }, { "topic": "OOPS - Interfaces/Abstract Classes", "question": "What is a key difference between an Abstract Class and an Interface in most Object-Oriented languages?", "options": ["An Interface can have constructors, but an Abstract Class cannot", "An Abstract Class can have both fully implemented methods and abstract (unimplemented) methods, while a traditional Interface typically only declares method signatures (without implementation)", "There is no difference between them", "Interfaces can only be used with primitive data types", "Abstract classes cannot be inherited from"], "correct": "B", "explanation": "An Abstract Class can provide a mix of fully implemented (concrete) methods and abstract methods (to be implemented by subclasses), while a traditional Interface generally only declares method signatures that implementing classes must define (though modern languages allow some default implementations)." }, { "topic": "OOPS - Interfaces/Abstract Classes", "question": "Can an Abstract Class be instantiated directly (i.e., can you create an object of an abstract class type)?", "options": ["Yes, always", "No, an abstract class cannot be instantiated directly; it must be subclassed and its abstract methods implemented", "Only if it has no methods at all", "Only if declared as 'static'", "Only if it implements an interface"], "correct": "B", "explanation": "An Abstract Class cannot be instantiated directly because it may contain one or more unimplemented (abstract) methods; a concrete subclass must implement these methods before an object can be created." }, { "topic": "OOPS - Exception Handling", "question": "Which block of code is used to catch and handle exceptions that may occur during the execution of a 'try' block?", "options": ["finally", "catch", "throw", "try", "except (only in some languages, not universal)"], "correct": "B", "explanation": "The 'catch' block (or 'except' in Python) is used to handle exceptions thrown within the corresponding 'try' block, allowing the program to respond gracefully instead of crashing." }, { "topic": "OOPS - Exception Handling", "question": "Which block of code is guaranteed to execute regardless of whether an exception was thrown or caught, typically used for cleanup operations?", "options": ["try", "catch", "throw", "finally", "default"], "correct": "D", "explanation": "The 'finally' block always executes after the try/catch blocks complete, regardless of whether an exception occurred, making it ideal for cleanup tasks like closing file handles or releasing resources." }, { "topic": "OOPS - Relationships", "question": "Which OOPS relationship represents a 'has-a' association where the contained object CAN exist independently of the containing object?", "options": ["Composition", "Inheritance", "Aggregation", "Polymorphism", "Encapsulation"], "correct": "C", "explanation": "Aggregation represents a 'has-a' relationship where the part object can exist independently of the whole (e.g., a Department 'has' Employees, but Employees can exist even if the Department is dissolved)." }, { "topic": "OOPS - Relationships", "question": "Which OOPS relationship represents a strong 'part-of' association where the contained object CANNOT exist independently of the containing object?", "options": ["Aggregation", "Association", "Composition", "Generalization", "Realization"], "correct": "C", "explanation": "Composition represents a strong ownership relationship where the part cannot exist without the whole — if the containing object is destroyed, its composed parts are destroyed too (e.g., a House's Rooms)." }, { "topic": "OOPS - Virtual Functions", "question": "In C++, what is the primary purpose of declaring a member function as 'virtual'?", "options": ["To make the function execute faster", "To enable runtime polymorphism, allowing a derived class's overridden version of the function to be called through a base class pointer/reference", "To make the function private automatically", "To prevent the function from being overloaded", "To convert the function into a static function"], "correct": "B", "explanation": "Declaring a function as 'virtual' in C++ enables dynamic (runtime) binding, so that calling the function through a base class pointer/reference invokes the derived class's overridden version, based on the actual object type — this is central to achieving runtime polymorphism. Subscribe: YouTube — Way2Officers Guide Telegram: t.me/way2officersguide | @waystoofficer Ways to Officer · Dpksanu — IBPS/RRB/IBPS SO IT Officer Exam Prep" }, { "topic": "DBMS", "question": "Which normal form removes transitive dependency from a relation?", "options": ["1NF", "2NF", "3NF", "BCNF", "4NF"], "correct": "C", "explanation": "3NF requires that no non-key attribute depends transitively on the primary key through another non-key attribute, eliminating transitive dependency." }, { "topic": "OS", "question": "Which CPU scheduling algorithm can lead to the 'Convoy Effect'?", "options": ["Round Robin", "Shortest Job First", "First Come First Served", "Priority Scheduling", "Multilevel Feedback Queue"], "correct": "C", "explanation": "FCFS processes requests in strict arrival order, so a long process arriving first forces all shorter processes to wait behind it, causing the Convoy Effect." }, { "topic": "Networks", "question": "Which layer of the OSI model is responsible for logical addressing and routing?", "options": ["Data Link Layer", "Network Layer", "Transport Layer", "Session Layer", "Physical Layer"], "correct": "B", "explanation": "The Network Layer (Layer 3) handles logical IP addressing and determines the best path for packets using routers." }, { "topic": "DSA", "question": "What is the time complexity of binary search on a sorted array of n elements?", "options": ["O(1)", "O(n)", "O(log n)", "O(n log n)", "O(n^2)"], "correct": "C", "explanation": "Binary search repeatedly halves the search space, giving a time complexity of O(log n)." }, { "topic": "OOPS", "question": "Which OOPS concept allows a subclass to provide a specific implementation of a method already defined in its parent class?", "options": ["Overloading", "Overriding", "Encapsulation", "Abstraction", "Composition"], "correct": "B", "explanation": "Method Overriding allows a derived class to redefine a method with the same signature as one in its base class, providing specific behavior." }, { "topic": "Software Engineering", "question": "Which SDLC model is best suited for large, high-risk projects due to its focus on iterative risk analysis?", "options": ["Waterfall Model", "Spiral Model", "V-Model", "Big Bang Model", "RAD Model"], "correct": "B", "explanation": "The Spiral Model combines iterative development with systematic risk analysis at each loop, making it ideal for large, risky projects." }, { "topic": "COA", "question": "Which addressing mode has the operand value given directly within the instruction itself?", "options": ["Direct Addressing", "Indirect Addressing", "Immediate Addressing", "Register Addressing", "Indexed Addressing"], "correct": "C", "explanation": "In Immediate Addressing, the operand value is specified directly in the instruction (e.g., MOV A, #05H), requiring no extra memory access." }, { "topic": "Cyber Security", "question": "Which type of malware requires a host file to attach itself to and spread?", "options": ["Worm", "Virus", "Trojan Horse", "Rootkit", "Adware"], "correct": "B", "explanation": "A Virus attaches itself to a legitimate host file/program and spreads when that file is executed, unlike a Worm which spreads independently." }, { "topic": "Data Warehouse", "question": "Which OLAP operation aggregates data by climbing up a concept hierarchy, reducing the level of detail?", "options": ["Drill-down", "Roll-up", "Slice", "Dice", "Pivot"], "correct": "B", "explanation": "Roll-up aggregates data by moving up a hierarchy (e.g., Daily to Monthly to Yearly), reducing detail, the opposite of drill-down." }, { "topic": "Programming", "question": "In Java, which keyword is used to prevent a class from being inherited?", "options": ["static", "private", "final", "abstract", "protected"], "correct": "C", "explanation": "Declaring a class as 'final' in Java prevents any other class from extending (inheriting from) it." }, { "topic": "DBMS", "question": "Which type of SQL join returns all rows from the left table and only matching rows from the right table?", "options": ["INNER JOIN", "RIGHT JOIN", "LEFT JOIN", "FULL OUTER JOIN", "CROSS JOIN"], "correct": "C", "explanation": "A LEFT (OUTER) JOIN returns every row from the left table, filling in NULLs for unmatched columns from the right table." }, { "topic": "OS", "question": "Which memory management technique divides a process into fixed-size blocks and physical memory into frames of the same size?", "options": ["Segmentation", "Paging", "Swapping", "Overlaying", "Dynamic Partitioning"], "correct": "B", "explanation": "Paging divides logical memory into fixed-size pages and physical memory into equal-size frames, avoiding external fragmentation." }, { "topic": "Networks", "question": "Which protocol automatically assigns IP addresses to devices on a network?", "options": ["DNS", "DHCP", "ARP", "SNMP", "FTP"], "correct": "B", "explanation": "DHCP (Dynamic Host Configuration Protocol) automatically assigns IP addresses and other network configuration parameters to devices." }, { "topic": "DSA", "question": "Which data structure follows the LIFO (Last In, First Out) principle?", "options": ["Queue", "Stack", "Linked List", "Array", "Tree"], "correct": "B", "explanation": "A Stack follows LIFO, the last element pushed is the first one popped, like a stack of plates." }, { "topic": "OOPS", "question": "Which type of inheritance forms a chain, where a class is derived from another derived class?", "options": ["Single Inheritance", "Multiple Inheritance", "Multilevel Inheritance", "Hierarchical Inheritance", "Hybrid Inheritance"], "correct": "C", "explanation": "Multilevel Inheritance forms a chain (A to B to C), where a class inherits from a class that itself inherited from another base class." }, { "topic": "Software Engineering", "question": "Which type of software testing verifies that the software meets business/contractual requirements and is ready for delivery?", "options": ["Unit Testing", "Integration Testing", "System Testing", "Acceptance Testing", "Regression Testing"], "correct": "D", "explanation": "Acceptance Testing checks whether the software satisfies business requirements and is ready for delivery, typically the final stage before go-live." }, { "topic": "COA", "question": "Which control unit design uses a Control Store containing microinstructions to generate control signals?", "options": ["Hardwired Control Unit", "Microprogrammed Control Unit", "Pipelined Control Unit", "Combinational Control Unit", "None of these"], "correct": "B", "explanation": "A Microprogrammed Control Unit stores microinstructions in a control memory (control store), offering flexibility compared to hardwired control." }, { "topic": "Cyber Security", "question": "Which technology hides internal IP addresses and allows multiple devices to share a single public IP address?", "options": ["VPN", "Firewall", "NAT", "DNS", "Proxy chaining"], "correct": "C", "explanation": "NAT (Network Address Translation) translates private internal IP addresses to a single public IP address, hiding the internal network structure." }, { "topic": "Data Warehouse", "question": "Which data warehouse schema uses multiple fact tables sharing common dimension tables?", "options": ["Star Schema", "Snowflake Schema", "Fact Constellation Schema", "Flat File Schema", "Normalized Schema"], "correct": "C", "explanation": "A Fact Constellation (galaxy) schema consists of multiple fact tables sharing dimension tables, unlike a Star Schema which has one central fact table." }, { "topic": "Programming", "question": "In Python, which keyword is used to handle exceptions that may occur in a 'try' block?", "options": ["catch", "except", "handle", "rescue", "trap"], "correct": "B", "explanation": "Python uses 'except' (not 'catch' as in Java/C++) to handle exceptions raised within a corresponding 'try' block." }, { "topic": "DBMS", "question": "Which ACID property ensures that a transaction is treated as a single indivisible unit, either fully completed or not applied at all?", "options": ["Consistency", "Isolation", "Durability", "Atomicity", "Concurrency"], "correct": "D", "explanation": "Atomicity guarantees that all operations in a transaction succeed together, or none of them are applied (rollback on failure)." }, { "topic": "OS", "question": "Which algorithm avoids deadlock by simulating resource allocation and checking if the resulting state is 'safe' before granting a request?", "options": ["Round Robin Algorithm", "Banker's Algorithm", "FIFO Algorithm", "Optimal Page Replacement", "Clock Algorithm"], "correct": "B", "explanation": "The Banker's Algorithm avoids deadlock by checking whether granting a resource request leaves the system in a safe state before actually allocating it." }, { "topic": "Networks", "question": "Which device operates at the Data Link Layer and forwards frames based on MAC addresses?", "options": ["Hub", "Switch", "Repeater", "Router", "Modem"], "correct": "B", "explanation": "A Switch operates at Layer 2, learning device MAC addresses and forwarding frames only to the intended port, reducing collision domains." }, { "topic": "DSA", "question": "What is the worst-case time complexity of Quick Sort?", "options": ["O(n)", "O(n log n)", "O(n^2)", "O(log n)", "O(2^n)"], "correct": "C", "explanation": "Quick Sort's worst case occurs with a poorly chosen pivot (e.g., on already sorted data), degrading performance to O(n^2), though its average case is O(n log n)." }, { "topic": "OOPS", "question": "Which OOPS principle focuses on hiding complex implementation details and exposing only essential features?", "options": ["Encapsulation", "Abstraction", "Inheritance", "Polymorphism", "Overloading"], "correct": "B", "explanation": "Abstraction hides implementation complexity, showing only essential features to the user, typically via abstract classes or interfaces." }, { "topic": "Software Engineering", "question": "Which coupling type, where one module directly modifies the internal data of another module, is considered the WORST form of coupling?", "options": ["Data Coupling", "Stamp Coupling", "Control Coupling", "Content Coupling", "Common Coupling"], "correct": "D", "explanation": "Content Coupling is the worst form, where one module directly accesses or modifies another module's internal data, creating extremely fragile dependencies." }, { "topic": "COA", "question": "Which cache mapping technique allows a memory block to be placed in exactly one specific cache line?", "options": ["Fully Associative Mapping", "Direct Mapping", "Set-Associative Mapping", "Random Mapping", "Sector Mapping"], "correct": "B", "explanation": "In Direct Mapping, each memory block maps to exactly one cache line (via a fixed formula), which is simple and fast but prone to conflict misses." }, { "topic": "Cyber Security", "question": "Which attack involves a rogue Wi-Fi access point mimicking a legitimate network's SSID to intercept user traffic?", "options": ["ARP Spoofing", "Evil Twin Attack", "DNS Spoofing", "Brute Force Attack", "Cross-Site Scripting"], "correct": "B", "explanation": "An Evil Twin Attack sets up a fake access point copying a legitimate network's name (SSID) to trick users into connecting and intercept their traffic." }, { "topic": "Data Warehouse", "question": "In a data warehouse, which table stores quantitative, measurable business data along with foreign keys to dimension tables?", "options": ["Dimension Table", "Fact Table", "Lookup Table", "Staging Table", "Metadata Table"], "correct": "B", "explanation": "A Fact Table is the central table storing measurable business metrics (e.g., sales amount) plus foreign keys linking to descriptive dimension tables." }, { "topic": "Programming", "question": "Which Java collection class does NOT allow duplicate elements?", "options": ["ArrayList", "LinkedList", "HashSet", "Vector", "Stack"], "correct": "C", "explanation": "A HashSet is based on the Set interface, which by definition does not allow duplicate elements, unlike List-based collections like ArrayList." }, { "topic": "DBMS", "question": "Which key type is a candidate key that was NOT chosen as the primary key of a table?", "options": ["Foreign Key", "Alternate Key", "Composite Key", "Super Key", "Unique Key"], "correct": "B", "explanation": "An Alternate Key refers to candidate keys that could have uniquely identified rows but were not selected as the primary key." }, { "topic": "OS", "question": "Which page replacement algorithm can suffer from Belady's Anomaly, where adding more frames can increase page faults?", "options": ["LRU", "Optimal", "FIFO", "Second Chance", "Clock"], "correct": "C", "explanation": "FIFO page replacement is notably subject to Belady's Anomaly, an unusual case where increasing the number of frames results in MORE page faults." }, { "topic": "Networks", "question": "Which transport layer protocol is connectionless and does not guarantee reliable delivery?", "options": ["TCP", "UDP", "IP", "ICMP", "ARP"], "correct": "B", "explanation": "UDP (User Datagram Protocol) is connectionless, with no delivery guarantees, making it fast but unreliable compared to TCP." }, { "topic": "DSA", "question": "Which traversal of a Binary Search Tree visits nodes in ascending sorted order?", "options": ["Preorder", "Inorder", "Postorder", "Level order", "Reverse postorder"], "correct": "B", "explanation": "Inorder traversal (Left-Root-Right) of a BST always visits nodes in ascending sorted order." }, { "topic": "OOPS", "question": "In C++, which keyword is used to enable runtime polymorphism by allowing a derived class's overridden method to be called through a base class pointer?", "options": ["static", "virtual", "const", "friend", "explicit"], "correct": "B", "explanation": "Declaring a function 'virtual' in C++ enables dynamic (runtime) binding, so the derived class's overridden version is called via a base class pointer/reference." }, { "topic": "Software Engineering", "question": "Which UML diagram is used to represent the static structure of a system, showing classes and their relationships?", "options": ["Use Case Diagram", "Sequence Diagram", "Class Diagram", "Activity Diagram", "State Diagram"], "correct": "C", "explanation": "A Class Diagram models the static structure of a system, depicting classes, their attributes/operations, and relationships like inheritance and association." }, { "topic": "COA", "question": "Which type of ROM can be erased using ultraviolet light and then reprogrammed?", "options": ["PROM", "EPROM", "EEPROM", "Mask ROM", "Flash Memory only"], "correct": "B", "explanation": "EPROM (Erasable Programmable ROM) can be erased by exposing the chip to UV light, after which it can be reprogrammed." }, { "topic": "Cyber Security", "question": "Which firewall generation is a Next-Generation Firewall (NGFW) considered to be?", "options": ["1st Generation", "2nd Generation", "3rd Generation", "4th Generation", "5th Generation"], "correct": "C", "explanation": "NGFWs are considered 3rd-generation firewalls, combining traditional packet filtering with deep packet inspection and application awareness." }, { "topic": "Data Warehouse", "question": "Which type of OLAP server stores pre-aggregated data in a proprietary multidimensional cube structure for the fastest query performance?", "options": ["ROLAP", "MOLAP", "HOLAP", "DOLAP", "WOLAP"], "correct": "B", "explanation": "MOLAP (Multidimensional OLAP) stores data in pre-aggregated cube structures, offering the fastest query performance but with less scalability than ROLAP." }, { "topic": "Programming", "question": "Which SQL command is used to remove a table's structure AND its data permanently from a database?", "options": ["DELETE", "TRUNCATE", "DROP", "REMOVE", "CLEAR"], "correct": "C", "explanation": "DROP TABLE removes the entire table object, both its structure and data, and cannot be rolled back in most database systems." }, { "topic": "DBMS", "question": "Which normal form requires that every non-key attribute depends on the WHOLE composite primary key, not just part of it?", "options": ["1NF", "2NF", "3NF", "BCNF", "4NF"], "correct": "B", "explanation": "2NF eliminates partial dependency, requiring non-key attributes to depend on the entire composite primary key, not just a portion of it." }, { "topic": "OS", "question": "What is the term for a technique where a device can transfer data directly to/from memory without continuous CPU involvement?", "options": ["Programmed I/O", "Interrupt-driven I/O", "DMA", "Polling", "Memory-mapped I/O"], "correct": "C", "explanation": "DMA (Direct Memory Access) allows a device to transfer data directly to/from memory via a DMA controller, bypassing the CPU for the actual transfer." }, { "topic": "Networks", "question": "Which protocol translates human-readable domain names into IP addresses?", "options": ["DHCP", "ARP", "DNS", "NAT", "ICMP"], "correct": "C", "explanation": "DNS (Domain Name System) resolves domain names into their corresponding IP addresses, acting as the internet's 'phonebook'." }, { "topic": "DSA", "question": "Which sorting algorithm is 'stable', meaning equal elements retain their original relative order after sorting?", "options": ["Quick Sort", "Heap Sort", "Merge Sort", "Selection Sort", "None of the standard comparison sorts are stable"], "correct": "C", "explanation": "Merge Sort is stable, during merging, if two elements are equal, the one from the earlier sub-array is placed first, preserving original order." }, { "topic": "OOPS", "question": "Which type of polymorphism is resolved at compile time, typically achieved through method overloading?", "options": ["Runtime Polymorphism", "Dynamic Polymorphism", "Compile-Time Polymorphism", "Late Binding", "Virtual Polymorphism"], "correct": "C", "explanation": "Compile-Time (Static) Polymorphism is resolved during compilation, typically via method overloading, where the compiler decides which method to call based on arguments." }, { "topic": "Software Engineering", "question": "Which cost estimation model, developed by Barry Boehm, uses project size in KLOC to estimate development effort?", "options": ["Function Point Analysis", "COCOMO", "PERT", "Gantt Chart Method", "Delphi Technique"], "correct": "B", "explanation": "COCOMO (Constructive Cost Model) estimates software development effort and schedule based on the estimated size of the software in KLOC." }, { "topic": "Cyber Security", "question": "Which access control model grants access based on a user's assigned role within an organization?", "options": ["DAC", "MAC", "RBAC", "ABAC", "None of these"], "correct": "C", "explanation": "RBAC (Role-Based Access Control) grants access permissions based on a user's assigned organizational role (e.g., Manager, Admin)." }, { "topic": "Data Warehouse", "question": "Data Mining is considered to be which part of the broader KDD (Knowledge Discovery in Databases) process?", "options": ["The entire process itself", "A single step within the process", "A pre-processing step only", "An unrelated separate process", "The final output only"], "correct": "B", "explanation": "Data Mining is just ONE step within the broader KDD process, which also includes data cleaning, integration, selection, transformation, and pattern evaluation." }, { "topic": "OS", "question": "Which of the following is NOT one of the four necessary conditions for a deadlock to occur?", "options": ["Mutual Exclusion", "Hold and Wait", "Preemption", "Circular Wait", "No Preemption"], "correct": "C", "explanation": "The four necessary conditions for deadlock are Mutual Exclusion, Hold and Wait, No Preemption, and Circular Wait. 'Preemption' itself is a strategy used to PREVENT deadlock, not a cause of it." }, { "topic": "Networks", "question": "Which security device monitors network traffic and actively BLOCKS detected malicious activity in real time, as opposed to merely alerting administrators?", "options": ["IDS (Intrusion Detection System)", "IPS (Intrusion Prevention System)", "Proxy Server", "Load Balancer", "Hub"], "correct": "B", "explanation": "An IPS (Intrusion Prevention System) both monitors traffic and actively blocks/prevents malicious activity in real time, unlike an IDS which only detects and alerts without blocking." }, { "topic": "DBMS", "question": "Which anomaly occurs when deleting a row inadvertently causes the loss of other important, unrelated information due to poor table design?", "options": ["Insertion Anomaly", "Deletion Anomaly", "Update Anomaly", "Referential Anomaly", "Redundancy Anomaly"], "correct": "B", "explanation": "A Deletion Anomaly occurs when removing a record unintentionally deletes other important data that happened to be stored in the same row, a symptom of insufficient normalization." }, { "topic": "OS", "question": "If a system using the Banker's Algorithm is found to be in a 'safe state', what does this guarantee?", "options": ["No deadlock will ever occur regardless of any future request pattern", "There exists at least one safe sequence in which all processes can complete without deadlock", "All processes will finish in the exact order they requested resources", "The system currently has zero allocated resources", "Every process immediately receives its maximum resource claim"], "correct": "B", "explanation": "A 'safe state' guarantees that at least one ordering (safe sequence) of process execution exists that allows every process to complete without deadlock, given careful future allocation decisions." }, { "topic": "Networks", "question": "In a TCP three-way handshake, Host A sends a SYN with sequence number 100. Host B replies with SYN-ACK using seq=500. What acknowledgment number will Host A use in its final ACK segment?", "options": ["100", "101", "500", "501", "601"], "correct": "D", "explanation": "The acknowledgment number equals the received sequence number plus 1. Host B's SYN-ACK had seq=500, so Host A's ACK will carry ack=501, confirming receipt." }, { "topic": "DSA", "question": "What is the space complexity of Merge Sort (including the auxiliary array and recursion stack) when sorting n elements?", "options": ["O(1)", "O(log n)", "O(n)", "O(n log n)", "O(n^2)"], "correct": "C", "explanation": "Merge Sort requires an auxiliary array of size O(n) for merging, which dominates the O(log n) recursion stack depth, giving overall space complexity O(n)." }, { "topic": "OOPS", "question": "In Java, if a subclass defines a method with the same name and signature as a PRIVATE method in its parent class, what is the result?", "options": ["It overrides the parent's private method", "It causes a compile-time error", "It creates an independent new method unrelated to the parent's private method (not overriding)", "It causes a runtime exception", "The subclass method automatically becomes private too"], "correct": "C", "explanation": "Private methods are not inherited or visible to subclasses, so a same-named method in the subclass is treated as an entirely new, independent method rather than an override." }, { "topic": "Software Engineering", "question": "In Function Point Analysis, which of the following is NOT one of the five standard components counted?", "options": ["External Inputs", "External Outputs", "External Inquiries", "Internal Logical Files", "Cyclomatic Complexity"], "correct": "E", "explanation": "Function Point Analysis counts External Inputs, External Outputs, External Inquiries, Internal Logical Files, and External Interface Files. Cyclomatic Complexity is a separate McCabe metric for code path complexity, unrelated to FPA." }, { "topic": "COA", "question": "A cache has a hit ratio of 0.8, a hit time of 10 ns, and a miss penalty of 100 ns. What is the Average Memory Access Time (AMAT)?", "options": ["20 ns", "26 ns", "28 ns", "30 ns", "32 ns"], "correct": "D", "explanation": "AMAT = Hit Time + (Miss Rate &times; Miss Penalty) = 10 + (0.2 &times; 100) = 10 + 20 = 30 ns." }, { "topic": "Cyber Security", "question": "In the RSA algorithm, if p = 3 and q = 11 are the two chosen prime numbers, what is the value of n (the modulus)?", "options": ["14", "20", "30", "33", "44"], "correct": "D", "explanation": "In RSA, n = p &times; q = 3 &times; 11 = 33, which forms part of both the public and private keys." }, { "topic": "Data Warehouse", "question": "Dimension tables in a Snowflake Schema are typically normalized to which level, unlike the flat dimension tables of a Star Schema?", "options": ["1NF only", "2NF only", "3NF (fully normalized)", "Not normalized at all", "BCNF is strictly mandatory"], "correct": "C", "explanation": "Snowflake Schema dimension tables are further normalized (typically to 3NF), splitting them into related sub-dimension tables, unlike the deliberately denormalized flat dimension tables of a Star Schema." }, { "topic": "Programming", "question": "What is the output of this Java code?<br/>int x = 5;<br/>System.out.println(x++ + ++x);", "options": ["10", "11", "12", "13", "14"], "correct": "C", "explanation": "x++ (post-increment) evaluates to 5, then x becomes 6. ++x (pre-increment) then makes x = 7 and evaluates to 7. Sum = 5 + 7 = 12." }, { "topic": "DBMS", "question": "Which SQL transaction isolation level prevents 'non-repeatable reads' but still allows 'phantom reads' to occur?", "options": ["Read Uncommitted", "Read Committed", "Repeatable Read", "Serializable", "Snapshot"], "correct": "C", "explanation": "Repeatable Read locks the rows it has read, preventing non-repeatable reads, but does not lock the range of a query, so new rows (phantoms) can still appear on re-execution. Serializable is the only level that prevents both." }, { "topic": "OS", "question": "In a system with degree of multiprogramming n=8, if each process spends 40% of its time waiting for I/O, what is the approximate CPU utilization using the formula (1 - p^n)?", "options": ["60%", "75%", "90%", "99.93%", "100%"], "correct": "D", "explanation": "CPU Utilization = 1 - p^n = 1 - (0.4)^8. Since 0.4^8 &asymp; 0.000655, Utilization &asymp; 1 - 0.000655 = 0.999345, i.e., approximately 99.93%." }, { "topic": "Networks", "question": "How many usable host addresses does a subnet with mask 255.255.255.192 (/26) provide?", "options": ["30", "62", "64", "126", "254"], "correct": "B", "explanation": "/26 leaves 6 host bits, giving 2^6 = 64 total addresses. Subtracting the network and broadcast addresses leaves 62 usable host addresses." }, { "topic": "DSA", "question": "In a max-heap stored as a 0-indexed array, what are the indices of the left and right children of the node at index i?", "options": ["i-1 and i+1", "2i and 2i+1", "2i+1 and 2i+2", "i/2 and i/2+1", "2i-1 and 2i"], "correct": "C", "explanation": "For a 0-indexed array representation of a heap, the left child of node i is at index 2i+1, and the right child is at index 2i+2." }, { "topic": "OOPS", "question": "Which SOLID design principle states that a class should have only one reason to change?", "options": ["Single Responsibility Principle", "Open/Closed Principle", "Liskov Substitution Principle", "Interface Segregation Principle", "Dependency Inversion Principle"], "correct": "A", "explanation": "The Single Responsibility Principle (SRP) states that a class should have only one job or responsibility, and therefore only one reason to change." }, { "topic": "Software Engineering", "question": "For a program's control flow graph with 9 edges, 7 nodes, and 1 connected component, what is its McCabe Cyclomatic Complexity, V(G) = E - N + 2P?", "options": ["2", "3", "4", "5", "6"], "correct": "C", "explanation": "V(G) = E - N + 2P = 9 - 7 + 2(1) = 9 - 7 + 2 = 4." }, { "topic": "COA", "question": "In an 8-bit system using 2's complement representation, what is the range of representable signed integers?", "options": ["-127 to 127", "-128 to 127", "-128 to 128", "0 to 255", "-256 to 255"], "correct": "B", "explanation": "With n=8 bits in 2's complement, the representable range is -2^(n-1) to 2^(n-1)-1, which for n=8 gives -128 to 127." }, { "topic": "Cyber Security", "question": "Which hashing algorithm produces a 256-bit digest?", "options": ["MD5", "SHA-1", "SHA-256", "SHA-512", "CRC32"], "correct": "C", "explanation": "SHA-256, part of the SHA-2 family, produces a fixed 256-bit hash digest, unlike MD5 (128-bit), SHA-1 (160-bit), and SHA-512 (512-bit)." }, { "topic": "Data Warehouse", "question": "If a fact table's primary key is a composite of Time, Product, and Store dimension keys, what does this combination define?", "options": ["The measure of the fact table", "The grain of the fact table", "A derived attribute", "A concept hierarchy", "An aggregate table"], "correct": "B", "explanation": "The 'grain' of a fact table refers to the level of detail at which facts are recorded, which is defined by exactly which combination of dimension keys forms its primary key." }, { "topic": "Programming", "question": "What is the output of this Python code?<br/>a = [1, 2, 3, 4, 5]<br/>print(a[1:4:2])", "options": ["[1, 3]", "[2, 4]", "[2, 3, 4]", "[1, 2, 3]", "[3, 4]"], "correct": "B", "explanation": "Slicing a[1:4:2] starts at index 1, stops before index 4, and steps by 2, selecting indices 1 and 3, which hold values 2 and 4." }, { "topic": "DBMS", "question": "Which statement about SQL Views is correct?", "options": ["A view always physically stores its own copy of the data separately from the base table", "Views cannot be used inside SELECT queries", "A view is a virtual table based on the result of a query and does not store data itself in most cases", "Views automatically alter the base table's schema", "Views cannot include JOIN operations"], "correct": "C", "explanation": "A View is generally a virtual table defined by a stored query; it does not physically store the data itself (unless materialized), and can include joins and be queried like a table." }, { "topic": "OS", "question": "Which non-preemptive CPU scheduling algorithm minimizes average waiting time but requires advance knowledge of each process's burst time?", "options": ["FCFS", "Shortest Job First (SJF)", "Round Robin", "Priority Scheduling", "Multilevel Feedback Queue"], "correct": "B", "explanation": "Non-preemptive SJF is provably optimal for minimizing average waiting time, but it requires knowing each process's CPU burst time in advance, which is difficult in practice." }, { "topic": "Networks", "question": "What is the primary purpose of the 'Time to Live (TTL)' field in an IP packet header?", "options": ["To encrypt the packet payload", "To prevent packets from circulating indefinitely by decrementing at each hop until discarded at zero", "To specify the destination port number", "To indicate the packet's priority level", "To compress the packet for faster transmission"], "correct": "B", "explanation": "TTL is decremented by each router the packet passes through; when it reaches zero, the packet is discarded, preventing packets from looping endlessly due to routing errors." }, { "topic": "DSA", "question": "What is the minimum number of comparisons required, in the worst case, to find BOTH the minimum and maximum of n elements using the optimal pairwise comparison technique?", "options": ["n - 1", "2n - 2", "Approximately (3n/2) - 2", "n log n", "n^2"], "correct": "C", "explanation": "By comparing elements in pairs first and then comparing the smaller/larger elements separately, the optimal algorithm finds both min and max in approximately ceil(3n/2) - 2 comparisons, better than the naive 2n-2." }, { "topic": "OOPS", "question": "Which C++ mechanism resolves the 'Diamond Problem' in multiple inheritance by ensuring only one shared instance of the common base class exists?", "options": ["Multiple Inheritance itself", "Virtual Inheritance", "Friend Functions", "Operator Overloading", "Templates"], "correct": "B", "explanation": "Virtual Inheritance ensures that when two classes inherit from a common base class, and a further class inherits from both, only a single shared instance of the common base exists, resolving the ambiguity." }, { "topic": "Software Engineering", "question": "According to the Scrum Guide, what is the recommended maximum length of a single Sprint?", "options": ["1 week", "2 weeks", "1 month", "3 months", "6 months"], "correct": "C", "explanation": "The Scrum framework recommends Sprints of a consistent, fixed length not exceeding one month, allowing regular inspection and adaptation." }, { "topic": "COA", "question": "Which pipeline hazard is typically resolved using the 'forwarding' (or 'bypassing') technique?", "options": ["Structural Hazard", "Data Hazard", "Control Hazard", "Resource Hazard", "Memory Hazard"], "correct": "B", "explanation": "Forwarding (bypassing) routes a computed result directly to a dependent instruction before it is formally written back, resolving Data Hazards without requiring a full pipeline stall." }, { "topic": "Cyber Security", "question": "In a Diffie-Hellman key exchange, what is actually transmitted between the two parties over the insecure channel?", "options": ["Their private keys directly", "The symmetric encryption key directly", "Public values derived from private keys, used to jointly compute a shared secret", "The final shared secret itself", "Plaintext passwords"], "correct": "C", "explanation": "Diffie-Hellman allows two parties to exchange publicly computable values (based on their own private keys and a shared base/modulus) that let each side independently compute the same shared secret, without ever transmitting the secret or private keys directly." }, { "topic": "Data Warehouse", "question": "Which stage of the ETL process typically comes FIRST, retrieving data from heterogeneous source systems?", "options": ["Load", "Transform", "Extract", "Aggregate", "Stage"], "correct": "C", "explanation": "ETL begins with the Extract stage, where data is pulled from multiple heterogeneous source systems (databases, files, APIs), before being cleaned/transformed and finally loaded." }, { "topic": "Programming", "question": "Which C++ parameter declaration avoids copying an object while also preventing the function from modifying it?", "options": ["const int& x", "int& x", "const int x", "int* x", "const int* const x"], "correct": "A", "explanation": "'const int& x' passes the argument by reference (avoiding a copy) while the 'const' qualifier prevents the function from modifying the original value through that reference." }, { "topic": "DBMS", "question": "A relation R(A,B,C,D) has functional dependencies A&rarr;B, B&rarr;C, C&rarr;D, where A is the only candidate key. What is the highest normal form R satisfies?", "options": ["1NF", "2NF", "3NF", "BCNF", "4NF"], "correct": "B", "explanation": "Since A is a single-attribute key, there's no partial dependency issue (2NF is automatically satisfied). However, B&rarr;C and C&rarr;D create a transitive dependency chain (A&rarr;B&rarr;C&rarr;D), violating 3NF. So R satisfies only 2NF." }, { "topic": "OS", "question": "Which of the following is a key symptom of 'thrashing' in a virtual memory system?", "options": ["Extremely high CPU utilization with very few page faults", "A high page fault rate causing low CPU utilization despite a high degree of multiprogramming", "Complete elimination of all page faults", "Reduced memory usage across all processes", "Faster process execution due to more RAM"], "correct": "B", "explanation": "Thrashing occurs when the system is overcommitted with too many processes, causing excessive page faults; the CPU spends most of its time swapping pages rather than executing useful work, resulting in low utilization despite high multiprogramming." }, { "topic": "Networks", "question": "What subnet mask corresponds to a /28 CIDR notation?", "options": ["255.255.255.192", "255.255.255.224", "255.255.255.240", "255.255.255.248", "255.255.255.252"], "correct": "C", "explanation": "/28 leaves 4 host bits (32-28=4). The mask value is 256 - 2^4 = 256-16 = 240, giving the mask 255.255.255.240." }, { "topic": "DSA", "question": "What is the time complexity to build a heap from an unsorted array of n elements using the bottom-up heapify approach?", "options": ["O(1)", "O(n)", "O(n log n)", "O(log n)", "O(n^2)"], "correct": "B", "explanation": "Although each heapify call can take O(log n), a careful amortized analysis shows building a heap bottom-up from an unsorted array takes only O(n) total time, not the naively expected O(n log n)." }, { "topic": "OOPS", "question": "Regarding Java 8+ interfaces (which allow default methods) versus abstract classes, which key limitation still differentiates them?", "options": ["Interfaces cannot have any methods at all", "A class can implement multiple interfaces but can extend only ONE abstract class", "Abstract classes cannot have constructors", "Interfaces can have private instance fields with state", "Abstract classes cannot be used in Java at all"], "correct": "B", "explanation": "Even with default methods, Java still enforces single inheritance for classes — a class can implement multiple interfaces, but it can extend only one abstract (or concrete) class." }, { "topic": "Software Engineering", "question": "Which level of software testing focuses specifically on verifying the interactions and data flow between integrated modules/components?", "options": ["Unit Testing", "Integration Testing", "System Testing", "Acceptance Testing", "Regression Testing"], "correct": "B", "explanation": "Integration Testing specifically verifies that individually-tested modules work correctly together, focusing on interfaces and data flow between them." }, { "topic": "COA", "question": "If a CPU's clock frequency is 2 GHz and its average CPI (Cycles Per Instruction) is 1.5, what is the average time to execute one instruction?", "options": ["0.5 ns", "0.75 ns", "1 ns", "1.5 ns", "2 ns"], "correct": "B", "explanation": "Clock cycle time = 1/frequency = 1/(2&times;10^9) = 0.5 ns. Average instruction time = CPI &times; cycle time = 1.5 &times; 0.5 ns = 0.75 ns." }, { "topic": "Cyber Security", "question": "What does 'salting' refer to in the context of password hashing?", "options": ["Encrypting the password twice with different algorithms", "Adding random data to a password before hashing it, to defend against precomputed rainbow table attacks", "Storing passwords in plain text for faster lookup", "Compressing the password hash to save storage", "Sending the password over an encrypted channel only"], "correct": "B", "explanation": "Salting adds unique random data to each password before hashing, ensuring that even identical passwords produce different hashes, which defeats precomputed rainbow table attacks." }, { "topic": "Data Warehouse", "question": "What term describes a table storing pre-computed, summarized values (like totals) specifically to speed up common OLAP queries?", "options": ["Fact Table", "Aggregate Table", "Staging Table", "Dimension Table", "Metadata Table"], "correct": "B", "explanation": "An Aggregate Table stores pre-calculated summary values (e.g., monthly totals) so that common OLAP queries can be answered faster without repeatedly scanning and summing detailed fact table rows." }, { "topic": "Programming", "question": "What is the output of this Python expression (using right-to-left exponentiation associativity)?<br/>print(2 ** 3 ** 2)", "options": ["64", "512", "216", "729", "1024"], "correct": "B", "explanation": "Python's ** operator is right-associative, so 3**2 is evaluated first, giving 9. Then 2**9 = 512." }, { "topic": "DBMS", "question": "Which SQL constraint ensures a column's values are unique across all rows, while still typically allowing multiple NULL values (in most RDBMS)?", "options": ["PRIMARY KEY", "UNIQUE", "CHECK", "NOT NULL", "FOREIGN KEY"], "correct": "B", "explanation": "A UNIQUE constraint enforces distinct values among non-null entries but, unlike PRIMARY KEY, generally still permits multiple NULL values in most database systems, since NULL is not considered equal to another NULL." }, { "topic": "OS", "question": "What is the primary difference between a process and a thread in terms of memory?", "options": ["A thread has its own completely separate address space, unlike a process", "Threads within the same process share the same address space, while each process has its own separate address space", "Processes cannot access any memory at all", "Threads require more memory than processes always", "There is no memory-related difference between them"], "correct": "B", "explanation": "Threads belonging to the same process share that process's memory/address space, enabling fast communication, whereas each process has its own independent, isolated address space." }, { "topic": "Networks", "question": "Which routing protocol is a link-state protocol that uses Dijkstra's algorithm to compute the shortest path?", "options": ["RIP", "OSPF", "BGP", "IGRP", "EIGRP"], "correct": "B", "explanation": "OSPF (Open Shortest Path First) is a link-state protocol that uses Dijkstra's shortest-path-first algorithm to build its routing table, unlike RIP which is a simpler distance-vector protocol." }, { "topic": "DSA", "question": "What is the space complexity of representing a graph with V vertices using an adjacency matrix?", "options": ["O(V)", "O(V + E)", "O(V^2)", "O(E)", "O(log V)"], "correct": "C", "explanation": "An adjacency matrix requires a V &times; V grid to represent all possible vertex pairs, giving a space complexity of O(V^2), regardless of how many edges actually exist." }, { "topic": "Software Engineering", "question": "What does the 'V' shape in the V-Model of the SDLC primarily represent?", "options": ["The programming language syntax used", "Verification and Validation activities mapped against corresponding development phases", "A visual representation of team velocity", "The version control branching strategy", "The variance in project cost estimates"], "correct": "B", "explanation": "The V-Model's shape reflects how each development phase (left side, e.g., requirements, design) has a corresponding testing/validation phase (right side, e.g., acceptance testing, system testing) at the same level." }, { "topic": "COA", "question": "Which addressing mode requires NO memory access at all to fetch the operand, since the operand resides directly in a CPU register?", "options": ["Immediate Addressing", "Direct Addressing", "Indirect Addressing", "Register Addressing", "Indexed Addressing"], "correct": "D", "explanation": "In Register Addressing, the operand is already located in a CPU register, so no memory access is needed at all — making it even faster than Immediate Addressing, which at least reads the instruction itself." }, { "topic": "Cyber Security", "question": "At which OSI layers does a traditional packet-filtering firewall primarily operate?", "options": ["Application and Presentation Layer", "Network and Transport Layer", "Physical and Data Link Layer", "Session Layer only", "Presentation Layer only"], "correct": "B", "explanation": "A traditional packet-filtering firewall inspects IP addresses (Network Layer) and port numbers/protocols (Transport Layer) to make filtering decisions, operating primarily at Layers 3 and 4." }, { "topic": "Data Warehouse", "question": "What is 'Data Scrubbing' also commonly known as in the context of the ETL process?", "options": ["Data Loading", "Data Cleaning", "Data Extraction", "Data Mining", "Data Warehousing"], "correct": "B", "explanation": "Data Scrubbing is another term for Data Cleaning — the process of detecting and correcting (or removing) inaccurate, incomplete, or inconsistent data during the Transform stage of ETL." }, { "topic": "OS", "question": "Which of the following is NOT one of the four necessary conditions for a deadlock to occur?", "options": ["Mutual Exclusion", "Hold and Wait", "Preemption", "Circular Wait", "No Preemption"], "correct": "C", "explanation": "The four necessary conditions for deadlock are Mutual Exclusion, Hold and Wait, No Preemption, and Circular Wait. 'Preemption' is actually a strategy used to PREVENT deadlock, not a cause of it." }, { "topic": "Networks", "question": "Which security device monitors network traffic and actively BLOCKS detected malicious activity in real time, as opposed to merely alerting administrators?", "options": ["IDS (Intrusion Detection System)", "IPS (Intrusion Prevention System)", "Proxy Server", "Load Balancer", "Hub"], "correct": "B", "explanation": "An IPS (Intrusion Prevention System) both monitors traffic and actively blocks/prevents malicious activity in real time, unlike an IDS, which only detects and alerts without blocking." }] }];
